INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4a73922-2acd-41b8-aebc-91d6c82938aa', '奉和正日臨朝', '奉和正日臨朝', '586bafa4-cbba-45a3-af6a-5dd16b70c7a9', '唐', '["時雍表昌運，日正叶靈符。","德兼三代禮，功包四海圖。","踰沙紛在列，執玉儼相趨。","清蹕喧輦道，張樂駭天衢。","拂蜺九旗暎，儀鳳八音殊。","佳氣浮仙掌，熏風繞帝梧。","天文光七政，皇恩被九區。","方陪瘞玉禮，珥筆岱山隅。"]', '["时雍表昌運，日正叶靈符。","德兼三代禮，功包四海圖。","踰沙紛在列，執玉儼相趨。","清蹕喧輦道，張乐駭天衢。","拂蜺九旗暎，儀鳳八音殊。","佳氣浮仙掌，熏风繞帝梧。","天文光七政，皇恩被九區。","方陪瘞玉禮，珥笔岱山隅。"]', '诗', 'shi', '', NULL, '奉和正日臨朝 岑文本 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56a1301a-de61-4570-96f8-9764d72b362b', '奉述飛白書勢', '奉述飞白书勢', '586bafa4-cbba-45a3-af6a-5dd16b70c7a9', '唐', '["六文開玉篆，八體曜銀書。","飛毫列錦繡，拂素起龍魚。","鳳舉崩雲絕，鸞驚遊霧疎。","別有臨池草，恩霑垂露餘。"]', '["六文开玉篆，八體曜銀书。","飞毫列錦繡，拂素起龙鱼。","鳳舉崩云絕，鸾驚游霧疎。","別有臨池草，恩霑垂露餘。"]', '诗', 'shi', '', NULL, '奉述飛白書勢 岑文本 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d90209d5-cce5-4548-9317-5c05ade10b8d', '冬日宴于庶子宅各賦一字得平', '冬日宴于庶子宅各賦一字得平', '586bafa4-cbba-45a3-af6a-5dd16b70c7a9', '唐', '["金蘭篤惠好，尊酒暢生平。","既欣投轄賞，暫緩望鄉情。","愛景含霜晦，落照帶風輕。","於茲歡宴洽，寵辱詎相驚。"]', '["金蘭篤惠好，尊酒暢生平。","既欣投轄賞，暫緩望乡情。","愛景含霜晦，落照带风轻。","於茲歡宴洽，寵辱詎相驚。"]', '诗', 'shi', '', NULL, '冬日宴于庶子宅各賦一字得平 岑文本 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf662230-6124-427a-9050-9a57938c9986', '安德山池宴集', '安德山池宴集', '586bafa4-cbba-45a3-af6a-5dd16b70c7a9', '唐', '["甲第多清賞，芳辰命羽巵。","書帷通竹徑，琴臺枕槿籬。","池疑夜壑徙，山似鬱洲移。","雕楹網蘿薜，激瀨合塤篪。","鳥戲翻新葉，魚躍動清漪。","自得淹留趣，寧勞攀桂枝。"]', '["甲第多清賞，芳辰命羽巵。","书帷通竹徑，琴台枕槿籬。","池疑夜壑徙，山似鬱洲移。","雕楹網蘿薜，激瀨合塤篪。","鸟戲翻新葉，鱼躍动清漪。","自得淹留趣，寧勞攀桂枝。"]', '诗', 'shi', '', NULL, '安德山池宴集 岑文本 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1898e009-3428-440a-9559-884dfc68e5d3', '安德山池宴集', '安德山池宴集', '674082e0-f20e-4845-a5a2-68e31e646153', '唐', '["平陽擅歌舞，金谷盛招攜。","何如兼往烈，會賞叶幽栖。","已均朝野致，還欣物我齊。","春晚花方落，蘭深徑漸迷。","蒲新節尚短，荷小蓋猶低。","無勞拂長袖，直待夜烏啼。"]', '["平陽擅歌舞，金谷盛招携。","何如兼往烈，會賞叶幽栖。","已均朝野致，還欣物我齊。","春晚花方落，蘭深徑漸迷。","蒲新節尚短，荷小蓋猶低。","無勞拂长袖，直待夜烏啼。"]', '诗', 'shi', '', NULL, '安德山池宴集 劉洎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbfd3cf4-87b3-4f1d-ab4e-a094aec724de', '安德山池宴集', '安德山池宴集', '23e9e4ff-a165-447c-a60d-51ce4ee39fb8', '唐', '["伏櫪丹霞外，遮園煥景舒。","行雲泛層阜，蔽月下清渠。","亭中奏趙瑟，席上舞燕裾。","花落春鶯晚，風光夏葉初。","良朋比蘭蕙，雕藻邁瓊琚。","獨有狂歌客，來承歡宴餘。"]', '["伏櫪丹霞外，遮园煥景舒。","行云泛層阜，蔽月下清渠。","亭中奏趙瑟，席上舞燕裾。","花落春鶯晚，风光夏葉初。","良朋比蘭蕙，雕藻邁瓊琚。","独有狂歌客，来承歡宴餘。"]', '诗', 'shi', '', NULL, '安德山池宴集 褚遂良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6afd5890-6b81-47f0-8896-ef82623a1dbd', '安德山池宴集', '安德山池宴集', '167598ac-b53a-4bbc-a7dc-e8b4125419b7', '唐', '["狹斜通鳳闕，上路抵青樓。","簪紱啓賓館，軒蓋臨御溝。","西城多妙舞，主第出名謳。","列峰疑宿霧，疏壑擬藏舟。","花蝶辭風影，蘋藻含春流。","酒闌高宴畢，自反山之幽。"]', '["狹斜通鳳闕，上路抵青楼。","簪紱啓賓館，軒蓋臨御溝。","西城多妙舞，主第出名謳。","列峰疑宿霧，疏壑擬藏舟。","花蝶辞风影，蘋藻含春流。","酒闌高宴畢，自反山之幽。"]', '诗', 'shi', '', NULL, '安德山池宴集 楊續 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35775b11-83ef-458b-9358-4f05285db0b1', '遊清都觀尋沈道士得仙字', '游清都观尋沈道士得仙字', '4991a3e0-b225-45fb-9e67-bce2d1bd1bc5', '唐', '["紛吾因暇豫，行樂極留連。","尋真謁紫府，披霧覿青天。","緬懷金闕外，遐想玉京前。","飛軒俯松柏，抗殿接雲煙。","滔滔清夏景，嘒嘒早秋蟬。","橫琴對危石，酌醴臨寒泉。","聊祛塵俗累，寧希龜鶴年。","無勞生羽翼，自可狎神仙。"]', '["紛吾因暇豫，行乐極留連。","尋真謁紫府，披霧覿青天。","緬懷金闕外，遐想玉京前。","飞軒俯松柏，抗殿接云煙。","滔滔清夏景，嘒嘒早秋蟬。","橫琴对危石，酌醴臨寒泉。","聊祛塵俗累，寧希龟鹤年。","無勞生羽翼，自可狎神仙。"]', '诗', 'shi', '', NULL, '遊清都觀尋沈道士得仙字 劉孝孫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('055bba81-4c1a-46a0-bb05-67739d1cc395', '早發成皐望河', '早發成皐望河', '4991a3e0-b225-45fb-9e67-bce2d1bd1bc5', '唐', '["清晨發巖邑，車馬走轘轅。","迴瞰黃河上，惝怳屢飛魂。","鴻流遵積石，驚浪下龍門。","仙槎不辨處，沈璧想猶存。","遠近洲渚出，颯沓鳧鴈喧。","懷古空延佇，歎逝將何言。"]', '["清晨發巖邑，车马走轘轅。","迴瞰黄河上，惝怳屢飞魂。","鴻流遵積石，驚浪下龙门。","仙槎不辨处，沈璧想猶存。","远近洲渚出，颯沓鳧鴈喧。","懷古空延佇，歎逝將何言。"]', '诗', 'shi', '', NULL, '早發成皐望河 劉孝孫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9666ac5-1ab3-49e1-9a02-8a61381fd21d', '遊靈山寺', '游靈山寺', '4991a3e0-b225-45fb-9e67-bce2d1bd1bc5', '唐', '["吾王遊勝地，驂駕歷祗園。","臨風畫角憤，耀日采旗翻。","永懷筌了義，寂念啓玄門。","深谿窮地脉，高嶂接雲根。","信美諧心賞，幽邃且攀援。","曳裾欣扈從，方悟屏塵諠。"]', '["吾王游勝地，驂駕歷祗园。","臨风畫角憤，耀日采旗翻。","永懷筌了義，寂念啓玄门。","深谿窮地脉，高嶂接云根。","信美諧心賞，幽邃且攀援。","曳裾欣扈從，方悟屏塵諠。"]', '诗', 'shi', '', NULL, '遊靈山寺 劉孝孫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59005266-3c8a-486e-afae-43f553681f8b', '冬日宴于庶子宅各賦一字得鮮', '冬日宴于庶子宅各賦一字得鲜', '4991a3e0-b225-45fb-9e67-bce2d1bd1bc5', '唐', '["解襟遊勝地，披雲促宴筵。","清文振筆妙，高論寫言泉。","凍柳含風落，寒梅照日鮮。","驪歌雖欲奏，歸駕且留連。"]', '["解襟游勝地，披云促宴筵。","清文振笔妙，高論寫言泉。","凍柳含风落，寒梅照日鲜。","驪歌雖欲奏，归駕且留連。"]', '诗', 'shi', '', NULL, '冬日宴于庶子宅各賦一字得鮮 劉孝孫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74a21db3-2b30-4688-b9d9-bb604db9d956', '送劉散員同賦陳思王詩游人久不歸', '送劉散員同賦陳思王诗游人久不归', '4991a3e0-b225-45fb-9e67-bce2d1bd1bc5', '唐', '["鄉關渺天末，引領悵懷歸。","羈旅久淫滯，物色屢芳菲。","稍覺私意盡，行看蓬鬢衰。","如何千里外，佇立霑裳衣。"]', '["乡关渺天末，引領悵懷归。","羈旅久淫滯，物色屢芳菲。","稍覺私意尽，行看蓬鬢衰。","如何千里外，佇立霑裳衣。"]', '诗', 'shi', '', NULL, '送劉散員同賦陳思王詩游人久不歸 劉孝孫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('483d4cf0-c0f0-4df3-b145-098a121ba615', '詠笛', '詠笛', '4991a3e0-b225-45fb-9e67-bce2d1bd1bc5', '唐', '["涼秋夜笛鳴，流風韻九成。","調高時慷慨，曲變或淒清。","征客懷離緒，鄰人思舊情。","幸以知音顧，千載有奇聲。"]', '["涼秋夜笛鳴，流风韻九成。","調高时慷慨，曲变或淒清。","征客懷離緒，鄰人思旧情。","幸以知音顧，千載有奇声。"]', '诗', 'shi', '', NULL, '詠笛 劉孝孫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e904647d-47cc-42e7-9f6a-820b95e305bf', '賦得春鶯送友人', '賦得春鶯送友人', '4991a3e0-b225-45fb-9e67-bce2d1bd1bc5', '唐', '["流鶯拂繡羽，二月上林期。","待雪消金禁，銜花向玉墀。","翅掩飛燕舞，啼惱婕妤悲。","料取金閨意，因君問所思。"]', '["流鶯拂繡羽，二月上林期。","待雪消金禁，銜花向玉墀。","翅掩飞燕舞，啼惱婕妤悲。","料取金閨意，因君问所思。"]', '诗', 'shi', '', NULL, '賦得春鶯送友人 劉孝孫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ea9c7f4-fb9a-4f4d-89a8-6baa6e7639ee', '巫山高', '巫山高', '02891a09-fa39-425b-a9e0-b6c263c02f02', '唐', '["巫岫鬱岧嶤，高高入紫霄。","白雲抱危石，玄猨挂迥條。","懸崖激巨浪，脆葉隕驚飆。","別有陽臺處，風雨共飄颻。"]', '["巫岫鬱岧嶤，高高入紫霄。","白云抱危石，玄猨挂迥條。","懸崖激巨浪，脆葉隕驚飆。","別有陽台处，风雨共飄颻。"]', '诗', 'shi', '', NULL, '巫山高 陸敬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f850538-6564-463b-acb3-9c9566e01c07', '遊隋故都', '游隋故都', '02891a09-fa39-425b-a9e0-b6c263c02f02', '唐', '["洛城聊顧步，長想遂留連。","水鬬宮初毀，風變鼎將遷。","皐陶德不建，汾隅祀忽焉。","宗祊曠無象，聲朔緬誰傳。","枌榆何冷落，禾黍鬱芊緜。","悲歌盡商頌，太息憫周篇。","來蘇佇聖德，濡足乃乘乾。","正始淳風被，人勞用息肩。","舞象文思澤，偃伯武功宣。","則百昌厥後，於萬永斯年。","茲辰素商節，灰管變星躔。","平原悴秋草，喬木斂寒煙。","翻黃墜疎葉，凝翠積高天。","參差海曲鴈，寂寞柳門蟬。","興悼今如此，悲愁復在旃。","彷徨不忍去，杖策屢迴邅。"]', '["洛城聊顧步，长想遂留連。","水鬬宮初毀，风变鼎將遷。","皐陶德不建，汾隅祀忽焉。","宗祊曠無象，声朔緬誰傳。","枌榆何冷落，禾黍鬱芊緜。","悲歌尽商頌，太息憫周篇。","来蘇佇聖德，濡足乃乘乾。","正始淳风被，人勞用息肩。","舞象文思澤，偃伯武功宣。","則百昌厥後，於万永斯年。","茲辰素商節，灰管变星躔。","平原悴秋草，喬木斂寒煙。","翻黄墜疎葉，凝翠積高天。","參差海曲鴈，寂寞柳门蟬。","兴悼今如此，悲愁复在旃。","彷徨不忍去，杖策屢迴邅。"]', '诗', 'shi', '', NULL, '遊隋故都 陸敬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('706ffc71-758d-423a-b2af-f71864b4b506', '遊清都觀尋沈道士得都字', '游清都观尋沈道士得都字', '02891a09-fa39-425b-a9e0-b6c263c02f02', '唐', '["聊排靈瑣闥，徐步入清都。","青谿冥寂士，思玄徇道樞。","十芒生藥笥，七燄發丹爐。","縹袠桐君錄，朱書王母符。","宮槐散綠穗，日槿落青柎。","矯翰雷門鶴，飛來葉縣鳧。","凌風自可御，安事迫中區。","方追羽化侶，從此得玄珠。"]', '["聊排靈瑣闥，徐步入清都。","青谿冥寂士，思玄徇道樞。","十芒生藥笥，七燄發丹爐。","縹袠桐君錄，朱书王母符。","宮槐散綠穗，日槿落青柎。","矯翰雷门鹤，飞来葉縣鳧。","凌风自可御，安事迫中區。","方追羽化侶，從此得玄珠。"]', '诗', 'shi', '', NULL, '遊清都觀尋沈道士得都字 陸敬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f100fea-4315-4080-8697-036e1daef99b', '七夕賦詠成篇', '七夕賦詠成篇', '02891a09-fa39-425b-a9e0-b6c263c02f02', '唐', '["夙駕鳴鸞啓閶闔，霓裳遙裔儼天津。","五明霜紈開羽扇，百和香車動畫輪。","婉孌夜分能幾許，靚妝冶服爲誰新。","片時歡娛自有極，已復長望隔年人。"]', '["夙駕鳴鸾啓閶闔，霓裳遙裔儼天津。","五明霜紈开羽扇，百和香车动畫輪。","婉孌夜分能幾許，靚妝冶服爲誰新。","片时歡娛自有極，已复长望隔年人。"]', '诗', 'shi', '', NULL, '七夕賦詠成篇 陸敬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06f6c725-bf53-4a76-9bb3-4aea454900f0', '七夕賦詠成篇', '七夕賦詠成篇', 'ed391fa3-ea59-4c9c-aa80-ca6417b5f715', '唐', '["皎皎宵月麗秋光，耿耿天津橫復長。","停梭且復留殘緯，拂鏡及早更新妝。","彩鳳齊駕初成輦，雕鵲填河已作梁。","雖喜得同今夜枕，還愁重空明日牀。"]', '["皎皎宵月丽秋光，耿耿天津橫复长。","停梭且复留殘緯，拂镜及早更新妝。","彩鳳齊駕初成輦，雕鵲填河已作梁。","雖喜得同今夜枕，還愁重空明日牀。"]', '诗', 'shi', '', NULL, '七夕賦詠成篇 沈叔安 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32a56143-74fd-4375-97a4-148dee929cd1', '七夕賦詠成篇', '七夕賦詠成篇', '5781a36a-17a8-4450-ac86-ed86ccb6d770', '唐', '["日日思歸勤理鬢，朝朝佇望嬾調梭。","凌風寶扇遙臨月，映水仙車遠渡河。","歷歷珠星疑拖珮，冉冉雲衣似曳羅。","通宵道意終無盡，向曉離愁已復多。"]', '["日日思归勤理鬢，朝朝佇望嬾調梭。","凌风寶扇遙臨月，映水仙车远渡河。","歷歷珠星疑拖珮，冉冉云衣似曳羅。","通宵道意終無尽，向晓離愁已复多。"]', '诗', 'shi', '', NULL, '七夕賦詠成篇 何仲宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aea8bf82-2fa6-4242-9bbb-38ad78c180a4', '遊清都觀尋沈道士得芳字', '游清都观尋沈道士得芳字', '0a9659c6-0680-481e-b0ff-18e776d26a93', '唐', '["青谿阻千仞，姑射藐汾陽。","未若游茲境，探玄衆妙場。","鶴來疑羽客，雲泛似霓裳。","寓目雖靈宇，遊神乃帝鄉。","道存真理得，心灰俗累忘。","煙霞凝抗殿，松桂肅長廊。","早蟬清暮響，崇蘭散晚芳。","即此翔寥廓，非復控榆枋。"]', '["青谿阻千仞，姑射藐汾陽。","未若游茲境，探玄衆妙場。","鹤来疑羽客，云泛似霓裳。","寓目雖靈宇，游神乃帝乡。","道存真理得，心灰俗累忘。","煙霞凝抗殿，松桂肅长廊。","早蟬清暮响，崇蘭散晚芳。","即此翔寥廓，非复控榆枋。"]', '诗', 'shi', '', NULL, '遊清都觀尋沈道士得芳字 趙中虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73a55acf-cc0a-4b6f-aae1-24663b8b8fa4', '送劉散員賦得陳思王詩明月照高樓', '送劉散員賦得陳思王诗明月照高楼', 'f66b545e-39ed-4dd1-9401-5103b247b213', '唐', '["高樓一何綺，素月復流明。","重軒望不極，餘暉攬詎盈。","鏡華當牖照，鉤影隔簾生。","逆愁異尊酒，對此難爲情。"]', '["高楼一何綺，素月复流明。","重軒望不極，餘暉攬詎盈。","镜华當牖照，鉤影隔簾生。","逆愁異尊酒，对此难爲情。"]', '诗', 'shi', '', NULL, '送劉散員賦得陳思王詩明月照高樓 楊濬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1e9364b-9365-4302-a5d0-502cc14ff8fb', '隴頭水', '隴头水', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["隴頭秋月明，隴水帶關城。","笳添離別曲，風送斷腸聲。","映雪峰猶暗，乘冰馬屢驚。","霧中寒雁至，沙上轉蓬輕。","天山傳羽檄，漢地急徵兵。","陣開都護道，劒聚伏波營。","於茲覺無渡，方共濯胡纓。"]', '["隴头秋月明，隴水带关城。","笳添離別曲，风送斷腸声。","映雪峰猶暗，乘冰马屢驚。","霧中寒雁至，沙上轉蓬轻。","天山傳羽檄，漢地急徵兵。","陣开都護道，劒聚伏波營。","於茲覺無渡，方共濯胡纓。"]', '诗', 'shi', '', NULL, '隴頭水 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5997748-e6cf-4440-a06b-b5fa8ef41e1d', '中書寓直詠雨簡褚起居上官學士', '中书寓直詠雨簡褚起居上官学士', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["雲暗蒼龍闕，沈沈殊未開。","窗臨鳳凰沼，颯颯雨聲來。","電影入飛閣，風威凌吹臺。","長簷響奔溜，清簟肅浮埃。","早荷葉稍沒，新篁枝半摧。","茲晨悵多緒，懷友自難裁。","況復重城內，日暮獨裴回。","玉階良史筆，金馬掞天才。","高甍通散騎，複道駕蓬萊。","思君贈桃李，於此冀瓊瓌。"]', '["云暗蒼龙闕，沈沈殊未开。","窗臨鳳凰沼，颯颯雨声来。","電影入飞閣，风威凌吹台。","长簷响奔溜，清簟肅浮埃。","早荷葉稍沒，新篁枝半摧。","茲晨悵多緒，懷友自难裁。","況复重城內，日暮独裴回。","玉階良史笔，金马掞天才。","高甍通散騎，複道駕蓬萊。","思君贈桃李，於此冀瓊瓌。"]', '诗', 'shi', '', NULL, '中書寓直詠雨簡褚起居上官學士 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afbd2efb-1b67-406a-ad86-42794681ac7e', '闕題', '闕題', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["漢家伊洛九重城，御路浮橋萬里平。","桂戶雕梁連綺翼，虹梁繡柱映丹楹。","朝光欲動千門曙，麗日初照百花明。","燕趙蛾眉舊傾國，楚宮腰細本傳名。","二月桑津期結伴，三春淇水逐關情。","蘭叢有意飛雙蝶，柳葉無趣隱啼鶯。","扇裏細妝將夜並，風前獨舞共花榮。","兩鬟百萬誰論價，一笑千金判是輕。","不爲披圖來侍寢，非因主第奉身迎。","羊車詎畏青門閉，兔月今宵照後庭。"]', '["漢家伊洛九重城，御路浮橋万里平。","桂戶雕梁連綺翼，虹梁繡柱映丹楹。","朝光欲动千门曙，丽日初照百花明。","燕趙蛾眉旧傾国，楚宮腰細本傳名。","二月桑津期結伴，三春淇水逐关情。","蘭叢有意飞雙蝶，柳葉無趣隐啼鶯。","扇裏細妝將夜並，风前独舞共花榮。","兩鬟百万誰論價，一笑千金判是轻。","不爲披圖来侍寢，非因主第奉身迎。","羊车詎畏青门閉，兔月今宵照後庭。"]', '诗', 'shi', '', NULL, '闕題 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a69be821-9410-4710-bc7b-c63c48d3a6af', '初秋夜坐應詔', '初秋夜坐應詔', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["玉琯涼初應，金壺夜漸闌。","滄池流稍潔，仙掌露方漙。","雁聲風處斷，樹影月中寒。","爽氣長空淨，高吟覺思寬。"]', '["玉琯涼初應，金壺夜漸闌。","滄池流稍潔，仙掌露方漙。","雁声风处斷，樹影月中寒。","爽氣长空淨，高吟覺思寬。"]', '诗', 'shi', '', NULL, '初秋夜坐應詔 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5330d140-b84e-4b35-8e50-157998ac1ea8', '賦終南山用風字韻應詔', '賦終南山用风字韻應詔', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["眷言懷隱逸，輟駕踐幽叢。","白雲飛夏雨，碧嶺橫春虹。","草綠長楊路，花疎五柞宮。","登臨日將晚，蘭桂起香風。"]', '["眷言懷隐逸，輟駕踐幽叢。","白云飞夏雨，碧嶺橫春虹。","草綠长楊路，花疎五柞宮。","登臨日將晚，蘭桂起香风。"]', '诗', 'shi', '', NULL, '賦終南山用風字韻應詔 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a017cffc-4dbe-49b6-a6c4-bfaf65b91195', '詠飲馬應詔', '詠饮马應詔', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["清晨控龍馬，弄影出花林。","躞蹀依春澗，聯翩度碧潯。","苔流染絲絡，水潔寫雕簪。","一御瑤池駕，詎憶長城陰。"]', '["清晨控龙马，弄影出花林。","躞蹀依春澗，聯翩度碧潯。","苔流染絲絡，水潔寫雕簪。","一御瑤池駕，詎憶长城陰。"]', '诗', 'shi', '', NULL, '詠飲馬應詔 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adef4522-b5ab-4d44-9dae-28fd27113845', '初宵看婚', '初宵看婚', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["洛城花燭動，戚里畫新蛾。","隱扇羞應慣，含情愁已多。","輕啼濕紅粉，微睇轉橫波。","更笑巫山曲，空傳暮雨過。"]', '["洛城花燭动，戚里畫新蛾。","隐扇羞應慣，含情愁已多。","轻啼濕紅粉，微睇轉橫波。","更笑巫山曲，空傳暮雨過。"]', '诗', 'shi', '', NULL, '初宵看婚 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fc68858-9811-42be-b12a-b40f5ed05e71', '侍宴賦得起坐彈鳴琴二首 一', '侍宴賦得起坐彈鳴琴二首 一', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["北林鵲夜飛，南軒月初進。","調弦發清徵，蕩心祛褊吝。","變作離鴻聲，還入思歸引。","長歎未終極，秋風飄素鬢。"]', '["北林鵲夜飞，南軒月初進。","調弦發清徵，蕩心祛褊吝。","变作離鴻声，還入思归引。","长歎未終極，秋风飄素鬢。"]', '诗', 'shi', '', NULL, '侍宴賦得起坐彈鳴琴二首 一 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceaf311c-4af3-44a3-b0e5-16349e67c380', '侍宴賦得起坐彈鳴琴二首 二', '侍宴賦得起坐彈鳴琴二首 二', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["絲傳園客意，曲奏楚妃情。","罕有知音者，空勞流水聲。"]', '["絲傳园客意，曲奏楚妃情。","罕有知音者，空勞流水声。"]', '诗', 'shi', '', NULL, '侍宴賦得起坐彈鳴琴二首 二 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc13122c-7420-479d-8ffb-c3ad849367a1', '詠琴', '詠琴', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["久擅龍門質，孤竦嶧陽名。","齊娥初發弄，趙女正調聲。","嘉客勿遽反，繁弦曲未成。"]', '["久擅龙门質，孤竦嶧陽名。","齊娥初發弄，趙女正調声。","嘉客勿遽反，繁弦曲未成。"]', '诗', 'shi', '', NULL, '詠琴 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4761de38-b930-4792-9c25-b1dca1d9d312', '詠笙', '詠笙', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["短長插鳳翼，洪細摹鸞音。","能令楚妃歎，復使荆王吟。","切切孤竹管，來應雲和琴。"]', '["短长插鳳翼，洪細摹鸾音。","能令楚妃歎，复使荆王吟。","切切孤竹管，来應云和琴。"]', '诗', 'shi', '', NULL, '詠笙 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a42884a-9056-4996-bc6f-c0af99a18e0b', '應詔詠巢烏', '應詔詠巢烏', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["桂樹春暉滿，巢烏刷羽儀。","朝飛麗城上，夜宿碧林陲。","背風藏密葉，向日逐疎枝。","仰德還能哺，依仁遂可窺。","驚鳴雕輦側，王吉自相知。"]', '["桂樹春暉满，巢烏刷羽儀。","朝飞丽城上，夜宿碧林陲。","背风藏密葉，向日逐疎枝。","仰德還能哺，依仁遂可窺。","驚鳴雕輦側，王吉自相知。"]', '诗', 'shi', '', NULL, '應詔詠巢烏 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b046bdd-e970-4f89-b885-df6e1bc7e51c', '奉和夏日晚景應詔', '奉和夏日晚景應詔', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["輦路夾垂楊，離宮通建章。","日落橫峰影，雲歸起夕涼。","雕軒動流吹，羽蓋息迴塘。","薙草生還綠，殘花落尚香。","青巖類姑射，碧澗似汾陽。","幸屬無爲日，歡娛尚未央。"]', '["輦路夾垂楊，離宮通建章。","日落橫峰影，云归起夕涼。","雕軒动流吹，羽蓋息迴塘。","薙草生還綠，殘花落尚香。","青巖類姑射，碧澗似汾陽。","幸屬無爲日，歡娛尚未央。"]', '诗', 'shi', '', NULL, '奉和夏日晚景應詔 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cd3e298-4419-4d67-9f4e-1de0d5971d92', '奉和聖製春日望海', '奉和聖製春日望海', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["春山臨渤海，征旅輟晨裝。","回瞰盧龍塞，斜瞻肅慎鄉。","洪波迴地軸，孤嶼映雲光。","落日驚濤上，浮天駭浪長。","仙臺隱螭駕，水府汎黿梁。","碣石朝煙滅，之罘歸雁翔。","北巡非漢后，東幸異秦皇。","搴旗羽林客，跋距少年場。","龍擊驅遼水，鵬飛出帶方。","將舉青丘繳，安訪白霓裳。"]', '["春山臨渤海，征旅輟晨裝。","回瞰盧龙塞，斜瞻肅慎乡。","洪波迴地軸，孤嶼映云光。","落日驚濤上，浮天駭浪长。","仙台隐螭駕，水府汎黿梁。","碣石朝煙滅，之罘归雁翔。","北巡非漢后，东幸異秦皇。","搴旗羽林客，跋距少年場。","龙擊驱遼水，鵬飞出带方。","將舉青丘繳，安訪白霓裳。"]', '诗', 'shi', '', NULL, '奉和聖製春日望海 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48beb384-e597-45fc-ba0b-dcb2c18d6ac1', '春朝閑步', '春朝闲步', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["休沐乘閑豫，清晨步北林。","池塘藉芳草，蘭芷襲幽衿。","霧中分曉日，花裏弄春禽。","野逕香恆滿，山階筍屢侵。","何須命輕蓋，桃李自成陰。"]', '["休沐乘闲豫，清晨步北林。","池塘藉芳草，蘭芷襲幽衿。","霧中分晓日，花裏弄春禽。","野逕香恆满，山階筍屢侵。","何須命轻蓋，桃李自成陰。"]', '诗', 'shi', '', NULL, '春朝閑步 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8dcf4b1-b109-4681-8779-5106966740a5', '還山宅', '還山宅', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["暮春還舊嶺，徙倚翫年華。","芳草無行逕，空山正落花。","垂藤掃幽石，臥柳礙浮槎。","鳥散茅簷靜，雲披澗戶斜。","依然此泉路，猶是昔煙霞。"]', '["暮春還旧嶺，徙倚翫年华。","芳草無行逕，空山正落花。","垂藤掃幽石，臥柳礙浮槎。","鸟散茅簷静，云披澗戶斜。","依然此泉路，猶是昔煙霞。"]', '诗', 'shi', '', NULL, '還山宅 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4afbb6e-4d8b-4bcc-b361-a72fd04cc881', '詠馬', '詠马', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["寶馬權奇出未央，雕鞍照曜紫金裝。","春草初生馳上苑，秋風欲動戲長楊。","鳴珂屢度章臺側，細蹀經向濯龍傍。","徒令漢將連年去，宛城今已獻名王。"]', '["寶马權奇出未央，雕鞍照曜紫金裝。","春草初生驰上苑，秋风欲动戲长楊。","鳴珂屢度章台側，細蹀經向濯龙傍。","徒令漢將連年去，宛城今已獻名王。"]', '诗', 'shi', '', NULL, '詠馬 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5b98549-0aa4-46a7-a399-de2102b9fddb', '奉和詠弓', '奉和詠弓', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["霜重麟膠勁，風高月影圓。","烏飛隨帝輦，雁落逐鳴弦。"]', '["霜重麟膠勁，风高月影圓。","烏飞隨帝輦，雁落逐鳴弦。"]', '诗', 'shi', '', NULL, '奉和詠弓 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19a36191-b1c4-4aaf-ab6e-36f21f4c17fb', '詠硯', '詠硯', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["圓池類璧水，輕翰染煙華。","將軍欲定遠，見棄不應賒。"]', '["圓池類璧水，轻翰染煙华。","將軍欲定远，见棄不應賒。"]', '诗', 'shi', '', NULL, '詠硯 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbad568c-2beb-494a-bb1c-56db0c955b7e', '奉和正日臨朝應詔', '奉和正日臨朝應詔', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["皇猷被寰宇，端扆屬元辰。","九重麗天邑，千門臨上春。"]', '["皇猷被寰宇，端扆屬元辰。","九重丽天邑，千门臨上春。"]', '诗', 'shi', '', NULL, '奉和正日臨朝應詔 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da002bef-23f8-4c34-811f-65552c747baf', '詠舞', '詠舞', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["二八如回雪，三春類早花。","分行向燭轉，一種逐風斜。"]', '["二八如回雪，三春類早花。","分行向燭轉，一種逐风斜。"]', '诗', 'shi', '', NULL, '詠舞 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcdd8ee1-7e2d-455c-b288-9bc80d92d13b', '奉和執契靜三邊應詔', '奉和執契静三邊應詔', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["玄塞隔陰戎，朱光分昧谷。","地遊窮北際，雲崖盡西陸。","星次絕軒臺，風衢乖禹服。","寰區無所外，天覆今咸育。","竄苗猶有孽，戮負自貽辜。","疎網妖鯢漏，盤藪怪禽逋。","髯飛尚假息，乳視暫稽誅。","乾靈振玉弩，神略運璇樞。","日羽廓遊氣，天陣清華野。","升晅光西夜，馳恩溢東瀉。","揮袂靜崑炎，開關納流赭。","錦軺凌右地，華纓羇大夏。","清臺映羅葉，玄沚控瑤池。","駝鹿輸珍貺，樹羽饗來儀。","輟餚觀化宇，栖籞萃條支。","熏風交閬闕，就日泛濛漪。","充庭延飲至，絢簡敷春藻。","迎姜已創圖，命力方論道。","昔託遊河乘，再備商山皓。","欣逢德化流，思效登封草。"]', '["玄塞隔陰戎，朱光分昧谷。","地游窮北際，云崖尽西陸。","星次絕軒台，风衢乖禹服。","寰區無所外，天覆今咸育。","竄苗猶有孽，戮負自貽辜。","疎網妖鯢漏，盤藪怪禽逋。","髯飞尚假息，乳視暫稽誅。","乾靈振玉弩，神略運璇樞。","日羽廓游氣，天陣清华野。","升晅光西夜，驰恩溢东瀉。","揮袂静崑炎，开关納流赭。","錦軺凌右地，华纓羇大夏。","清台映羅葉，玄沚控瑤池。","駝鹿輸珍貺，樹羽饗来儀。","輟餚观化宇，栖籞萃條支。","熏风交閬闕，就日泛濛漪。","充庭延饮至，絢簡敷春藻。","迎姜已創圖，命力方論道。","昔託游河乘，再備商山皓。","欣逢德化流，思效登封草。"]', '诗', 'shi', '', NULL, '奉和執契靜三邊應詔 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c30f647e-39dc-4353-bbb3-379ae66155c6', '奉和行經破薛舉戰地應制', '奉和行經破薛舉戰地應制', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["混元分大象，長策挫修鯨。","於斯建宸極，由此創鴻名。","一戎乾宇泰，千祀德流清。","垂衣凝庶績，端拱鑄羣生。","復整瑤池駕，還臨官渡營。","周游尋曩跡，曠望動天情。","帷宮面丹浦，帳殿矚宛城。","虜場棲九穗，前歌被六英。","戰地甘泉涌，陣處景雲生。","普天霑凱澤，相攜欣頌平。"]', '["混元分大象，长策挫修鯨。","於斯建宸極，由此創鴻名。","一戎乾宇泰，千祀德流清。","垂衣凝庶績，端拱鑄羣生。","复整瑤池駕，還臨官渡營。","周游尋曩跡，曠望动天情。","帷宮面丹浦，帳殿矚宛城。","虜場棲九穗，前歌被六英。","戰地甘泉涌，陣处景云生。","普天霑凱澤，相携欣頌平。"]', '诗', 'shi', '', NULL, '奉和行經破薛舉戰地應制 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaf16564-4a01-4b21-9c54-9dc09ef65f13', '奉和入潼關', '奉和入潼关', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["曦馭循黃道，星陳引翠旗。","濟潼紆萬乘，臨河耀六師。","前旌彌陸海，後騎發通伊。","勢踰迴地軸，威盛轉天機。","是節歲窮紀，關樹蕩涼颸。","仙露含靈掌，瑞鼎照川湄。","沖襟賞臨睨，高詠入京畿。"]', '["曦馭循黄道，星陳引翠旗。","濟潼紆万乘，臨河耀六師。","前旌彌陸海，後騎發通伊。","勢踰迴地軸，威盛轉天機。","是節歲窮紀，关樹蕩涼颸。","仙露含靈掌，瑞鼎照川湄。","沖襟賞臨睨，高詠入京畿。"]', '诗', 'shi', '', NULL, '奉和入潼關 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bc74210-d744-41d2-a894-ae58f203514e', '奉和春日望海', '奉和春日望海', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["韓夷愆奉賮，憑險亂天常。","乃神弘廟畧，橫海剪吞航。","電野清玄菟，騰笳振白狼。","連雲飛巨艦，編石架浮梁。","周游臨大壑，降望極遐荒。","桃門通山抃，蓬渚降霓裳。","驚濤含蜃闕，駭浪掩晨光。","青丘絢春組，丹谷耀華桑。","長驅七萃卒，成功百戰場。","俄且旋戎路，飲至肅巖廊。"]', '["韓夷愆奉賮，憑險亂天常。","乃神弘廟畧，橫海剪吞航。","電野清玄菟，腾笳振白狼。","連云飞巨艦，編石架浮梁。","周游臨大壑，降望極遐荒。","桃门通山抃，蓬渚降霓裳。","驚濤含蜃闕，駭浪掩晨光。","青丘絢春組，丹谷耀华桑。","长驱七萃卒，成功百戰場。","俄且旋戎路，饮至肅巖廊。"]', '诗', 'shi', '', NULL, '奉和春日望海 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4622c56-5ce4-463d-a4a9-7417388eeb6c', '奉和元日應制', '奉和元日應制', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["天正開初節，日觀上重輪。","百靈滋景祚，萬玉慶惟新。","待旦敷玄造，韜旒御紫宸。","武帳臨光宅，文衛象鉤陳。","廣庭揚九奏，大帛麗三辰。","發生同化育，播物體陶鈞。","霜空澄曉氣，霞景瑩芳春。","德輝覃率[土]，相賀奉還淳。"]', '["天正开初節，日观上重輪。","百靈滋景祚，万玉慶惟新。","待旦敷玄造，韜旒御紫宸。","武帳臨光宅，文衛象鉤陳。","廣庭揚九奏，大帛丽三辰。","發生同化育，播物體陶鈞。","霜空澄晓氣，霞景瑩芳春。","德輝覃率[土]，相賀奉還淳。"]', '诗', 'shi', '', NULL, '奉和元日應制 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba13fe6f-d354-4b9d-ac1e-2f24f6b7ee02', '奉和初春登樓即目應詔', '奉和初春登楼即目應詔', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["旭日臨重壁，天眷極中京。","春暉發芳甸，佳氣滿層城。","去鳥隨看沒，來雲逐望生。","歌裏非煙颺，琴上凱風清。","文波浮鏤檻，摛景煥雕楹。","璇璣體寬政，隆棟象端衡。","創規雖有作，凝拱遂無營。","沐恩空改鬢，將何謝夏成。"]', '["旭日臨重壁，天眷極中京。","春暉發芳甸，佳氣满層城。","去鸟隨看沒，来云逐望生。","歌裏非煙颺，琴上凱风清。","文波浮鏤檻，摛景煥雕楹。","璇璣體寬政，隆棟象端衡。","創規雖有作，凝拱遂無營。","沐恩空改鬢，將何謝夏成。"]', '诗', 'shi', '', NULL, '奉和初春登樓即目應詔 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fa81a42-710b-4491-813a-257c6655e09a', '奉和秋日即目應制', '奉和秋日即目應制', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["玉露交珠網，金風度綺錢。","昆明秋景淡，岐岫落霞然。","辭燕歸寒海，來鴻出遠天。","葉動羅帷颺，花映繡裳鮮。","規空升闇魄，籠野散輕煙。","鵲度林光起，鳧沒水文圓。","無機絡秋緯，如管奏寒蟬。","乃睠情何極，宸襟豫有旃。"]', '["玉露交珠網，金风度綺錢。","昆明秋景淡，岐岫落霞然。","辞燕归寒海，来鴻出远天。","葉动羅帷颺，花映繡裳鲜。","規空升闇魄，籠野散轻煙。","鵲度林光起，鳧沒水文圓。","無機絡秋緯，如管奏寒蟬。","乃睠情何極，宸襟豫有旃。"]', '诗', 'shi', '', NULL, '奉和秋日即目應制 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1efdaee9-7b98-4c2f-a859-46d616ddb3a6', '奉和秋暮言志應制', '奉和秋暮言志應制', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["秋深桂初發，寒窗菊餘菲。","波擁羣鳧至，秋飄朔雁歸。","月莢生還落，雲枝似復非。","凝宸閱栖畝，觀文佇少微。","聖敬韜前哲，先天諒不違。"]', '["秋深桂初發，寒窗菊餘菲。","波擁羣鳧至，秋飄朔雁归。","月莢生還落，云枝似复非。","凝宸閱栖畝，观文佇少微。","聖敬韜前哲，先天諒不違。"]', '诗', 'shi', '', NULL, '奉和秋暮言志應制 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1484ed6f-9509-4b5f-b81e-cd7ac268154d', '奉和喜雪應制', '奉和喜雪應制', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["嵰州表奇貺，閟竹應遐巡。","何如御京洛，流霰下天津。","忽若瓊林曙，俄同李徑春。","姑峯映仙質，郢路雜歌塵。","伏檻觀花瑞，稱觴慶冬積。","飄河共瀉銀，委樹還重璧。","連山分掩翠，綿霄遠韜碧。","千里徧浮空，五軔咸淪跡。","機前輝裂素，池上伴凌波。","騰華承玉宇，凝照混金娥。","是日松筠性，欣奉柏梁歌。"]', '["嵰州表奇貺，閟竹應遐巡。","何如御京洛，流霰下天津。","忽若瓊林曙，俄同李徑春。","姑峯映仙質，郢路杂歌塵。","伏檻观花瑞，稱觴慶冬積。","飄河共瀉銀，委樹還重璧。","連山分掩翠，綿霄远韜碧。","千里徧浮空，五軔咸淪跡。","機前輝裂素，池上伴凌波。","腾华承玉宇，凝照混金娥。","是日松筠性，欣奉柏梁歌。"]', '诗', 'shi', '', NULL, '奉和喜雪應制 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('195b47b5-84e3-427a-84a1-cb4eca36d7d6', '奉和登陝州城樓應制', '奉和登陝州城楼應制', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["挹河澂綠宇，御溝映朱宮。","辰旂翻麗景，星蓋曳雕虹。","學嚬齊柳嫩，妍笑發春藂。","錦鱗文碧浪，繡羽絢青空。","眷念三階靜，遙想二南風。"]', '["挹河澂綠宇，御溝映朱宮。","辰旂翻丽景，星蓋曳雕虹。","学嚬齊柳嫩，妍笑發春藂。","錦鱗文碧浪，繡羽絢青空。","眷念三階静，遙想二南风。"]', '诗', 'shi', '', NULL, '奉和登陝州城樓應制 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc061549-ee44-4ddc-88ab-56fa4e3c4e71', '遊清都觀尋沈道士得清字', '游清都观尋沈道士得清字', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["幽人蹈箕潁，方士訪蓬瀛。","豈若逢真氣，齊契體無名。","既詮衆妙理，聊暢遠遊情。","縱心馳貝闕，怡神想玉京。","或命餘杭酒，時聽洛濱笙。","風衢通閬苑，星使下層城。","蕙帳晨飆動，芝房夕露清。","方叶棲遲趣，於此聽鐘聲。"]', '["幽人蹈箕潁，方士訪蓬瀛。","豈若逢真氣，齊契體無名。","既詮衆妙理，聊暢远游情。","縱心驰貝闕，怡神想玉京。","或命餘杭酒，时听洛濱笙。","风衢通閬苑，星使下層城。","蕙帳晨飆动，芝房夕露清。","方叶棲遲趣，於此听鐘声。"]', '诗', 'shi', '', NULL, '遊清都觀尋沈道士得清字 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('494db3da-3155-4b47-8a6a-82691a2f0ed4', '奉和七夕宴懸圃應制二首 一', '奉和七夕宴懸圃應制二首 一', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["牛閨臨淺漢，鸞駟涉秋河。","兩懷縈別緒，一宿慶停梭。","星模鉛裏靨，月寫黛中蛾。","奈許今宵度，長嬰離恨多。"]', '["牛閨臨淺漢，鸾駟涉秋河。","兩懷縈別緒，一宿慶停梭。","星模鉛裏靨，月寫黛中蛾。","奈許今宵度，长嬰離恨多。"]', '诗', 'shi', '', NULL, '奉和七夕宴懸圃應制二首 一 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ef10f56-c14a-40e7-bf35-c91dc8c61f89', '奉和七夕宴懸圃應制二首 二', '奉和七夕宴懸圃應制二首 二', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["婺閨期今夕，娥輪泛淺潢。","迎秋伴暮雨，待暝合神光。","薦寢低雲鬢，呈態解霓裳。","喜中愁漏促，別後怨天長。"]', '["婺閨期今夕，娥輪泛淺潢。","迎秋伴暮雨，待暝合神光。","薦寢低云鬢，呈態解霓裳。","喜中愁漏促，別後怨天长。"]', '诗', 'shi', '', NULL, '奉和七夕宴懸圃應制二首 二 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e67fc4d1-58e1-4d0d-8a37-0a5355dde663', '奉和儀鸞殿早秋應制', '奉和儀鸾殿早秋應制', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["睿想追嘉豫，臨軒御早秋。","斜暉麗粉壁，清吹肅朱樓。","高殿凝陰滿，雕窗豔曲流。","小臣參廣宴，大造諒難酬。"]', '["睿想追嘉豫，臨軒御早秋。","斜暉丽粉壁，清吹肅朱楼。","高殿凝陰满，雕窗豔曲流。","小臣參廣宴，大造諒难酬。"]', '诗', 'shi', '', NULL, '奉和儀鸞殿早秋應制 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b5f6c74-6b56-42e4-ba49-6805e2b99708', '奉和詠雨應詔', '奉和詠雨應詔', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["舞商初赴節，湘燕遠迎秋。","飄絲交殿網，亂滴起池漚。","激溜分龍闕，斜飛灑鳳樓。","崇朝方浹宇，宸盼俯凝旒。"]', '["舞商初赴節，湘燕远迎秋。","飄絲交殿網，亂滴起池漚。","激溜分龙闕，斜飞灑鳳楼。","崇朝方浹宇，宸盼俯凝旒。"]', '诗', 'shi', '', NULL, '奉和詠雨應詔 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5824960d-99b8-4863-a4e5-e03a0fc60576', '奉和過慈恩寺應制', '奉和過慈恩寺應制', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["鳳闕隣金地，龍旂拂寶臺。","雲楣將葉並，風牖送花來。","月宮清晚桂，虹梁絢早梅。","梵境留宸矚，掞發麗天才。"]', '["鳳闕隣金地，龙旂拂寶台。","云楣將葉並，风牖送花来。","月宮清晚桂，虹梁絢早梅。","梵境留宸矚，掞發丽天才。"]', '诗', 'shi', '', NULL, '奉和過慈恩寺應制 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9424bdf9-8373-4e63-a8e8-370f2ae71af5', '冬日宴于庶子宅各賦一字得歸', '冬日宴于庶子宅各賦一字得归', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["倦游嗟落拓，短翮慕追飛。","周醪忽同醉，牙弦乃共揮。","油雲澹寒色，落景靄霜霏。","累日方投分，茲夕諒無歸。"]', '["倦游嗟落拓，短翮慕追飞。","周醪忽同醉，牙弦乃共揮。","油云澹寒色，落景靄霜霏。","累日方投分，茲夕諒無归。"]', '诗', 'shi', '', NULL, '冬日宴于庶子宅各賦一字得歸 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9718208f-558b-4d41-a552-f99f9f5fb5bf', '送劉散員同賦得陳思王詩山樹鬱蒼蒼', '送劉散員同賦得陳思王诗山樹鬱蒼蒼', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["喬木託危岫，積翠繞連岡。","葉疎猶漏影，花少未流芳。","風來聞肅肅，霧罷見蒼蒼。","此中餞行邁，不異上河梁。"]', '["喬木託危岫，積翠繞連岡。","葉疎猶漏影，花少未流芳。","风来闻肅肅，霧罷见蒼蒼。","此中餞行邁，不異上河梁。"]', '诗', 'shi', '', NULL, '送劉散員同賦得陳思王詩山樹鬱蒼蒼 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b3b46bf-198f-4cfe-ad1f-3084e44e62f1', '侍宴莎冊宮應制得情字', '侍宴莎冊宮應制得情字', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["三星希曙景，萬騎翊天行。","葆羽翻風隊，騰吹掩山楹。","暖日晨光淺，飛煙旦彩輕。","塞寒桃變色，冰斷箭流聲。","漸奏長安道，神皐動睿情。"]', '["三星希曙景，万騎翊天行。","葆羽翻风隊，腾吹掩山楹。","暖日晨光淺，飞煙旦彩轻。","塞寒桃变色，冰斷箭流声。","漸奏长安道，神皐动睿情。"]', '诗', 'shi', '', NULL, '侍宴莎冊宮應制得情字 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ed6a9c1-f021-47c3-a43e-d83bf0156aa9', '奉和過舊宅應制', '奉和過旧宅應制', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["飛雲臨紫極，出震表青光。","自爾家寰海，今茲返帝鄉。","情深感代國，樂甚讌譙方。","白水浮佳氣，黃星聚太常。","岐鳳鳴層閣，酆雀賀雕梁。","桂山猶總翠，蘅薄尚流芳。","攀鱗有遺皓，沐德抃稱觴。"]', '["飞云臨紫極，出震表青光。","自爾家寰海，今茲返帝乡。","情深感代国，乐甚讌譙方。","白水浮佳氣，黄星聚太常。","岐鳳鳴層閣，酆雀賀雕梁。","桂山猶總翠，蘅薄尚流芳。","攀鱗有遺皓，沐德抃稱觴。"]', '诗', 'shi', '', NULL, '奉和過舊宅應制 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5a427fb-66e9-416b-8d7b-b10c5244ef58', '奉和宴中山應制', '奉和宴中山應制', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["飛雲旋碧海，解網宥青丘。","養賢停八駿，觀風駐五牛。","張樂臨堯野，揚麾歷舜州。","中山獻仙酤，趙媛發清謳。","塞門朱鴈入，郊藪紫麟遊。","一舉氛霓靜，千齡德化流。"]', '["飞云旋碧海，解網宥青丘。","養賢停八駿，观风駐五牛。","張乐臨堯野，揚麾歷舜州。","中山獻仙酤，趙媛發清謳。","塞门朱鴈入，郊藪紫麟游。","一舉氛霓静，千齡德化流。"]', '诗', 'shi', '', NULL, '奉和宴中山應制 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8e13a9b-d59d-4bd7-936c-f8acf5d85999', '奉和聖製登三臺言志應制', '奉和聖製登三台言志應制', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["中天表雲榭，載極聳崑樓。","聖作規玄造，軒阿復聿修。","高門符令節，形勝總神州。","企翼摶禽萃，飛甍燕雀遊。","綴星羅百拱，緣漢轉三休。","旦雲生玉舃，初月上銀鉤。","妙管含秦鳳，仙姿麗斗牛。","形言防處逸，粹藻發嘉猷。","荷生無以謝，盡瘁竟何酬。"]', '["中天表云榭，載極聳崑楼。","聖作規玄造，軒阿复聿修。","高门符令節，形勝總神州。","企翼摶禽萃，飞甍燕雀游。","綴星羅百拱，緣漢轉三休。","旦云生玉舃，初月上銀鉤。","妙管含秦鳳，仙姿丽斗牛。","形言防处逸，粹藻發嘉猷。","荷生無以謝，尽瘁竟何酬。"]', '诗', 'shi', '', NULL, '奉和聖製登三臺言志應制 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bcf7cd7-5edd-40cb-9df7-8d2a346bb002', '安德山池宴集', '安德山池宴集', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["戚里歡娛地，園林矚望新。","山庭帶芳杜，歌吹叶陽春。","臺榭疑巫峽，荷蕖似洛濱。","風花縈少女，虹梁聚美人。","宴遊窮至樂，談笑畢良辰。","獨歎高陽晚，歸路不知津。"]', '["戚里歡娛地，园林矚望新。","山庭带芳杜，歌吹叶陽春。","台榭疑巫峽，荷蕖似洛濱。","风花縈少女，虹梁聚美人。","宴游窮至乐，談笑畢良辰。","独歎高陽晚，归路不知津。"]', '诗', 'shi', '', NULL, '安德山池宴集 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('524e17ad-8a7c-4d8d-b9d9-d587a4a9c49f', '奉和聖製送來濟應制', '奉和聖製送来濟應制', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["萬乘騰鑣警岐路，百壺供帳餞離宮。","御溝分水聲難絕，廣宴當歌曲易終。","興言共傷千里道，俯跡聊示五情同。","良哉既深留帝念，沃化方有贊天聰。"]', '["万乘腾鑣警岐路，百壺供帳餞離宮。","御溝分水声难絕，廣宴當歌曲易終。","兴言共傷千里道，俯跡聊示五情同。","良哉既深留帝念，沃化方有贊天聰。"]', '诗', 'shi', '', NULL, '奉和聖製送來濟應制 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38342568-93bc-4db0-a7b6-a1608f1d2f1d', '七夕賦詠成篇', '七夕賦詠成篇', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["一年抱怨嗟長別，七夕含態始言歸。","飄飄羅襪光天步，灼灼新妝鑒月輝。","情催巧笑開星靨，不惜呈露解雲衣。","所歎却隨更漏盡，掩泣還弄昨宵機。"]', '["一年抱怨嗟长別，七夕含態始言归。","飄飄羅襪光天步，灼灼新妝鑒月輝。","情催巧笑开星靨，不惜呈露解云衣。","所歎却隨更漏尽，掩泣還弄昨宵機。"]', '诗', 'shi', '', NULL, '七夕賦詠成篇 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aa4f8e1-26ad-42e7-a486-86b0ea35f14c', '擬江令於長安歸揚州九日賦', '擬江令於长安归揚州九日賦', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["本逐征鴻去，還隨落葉來。","菊花應未滿，請待詩人開。"]', '["本逐征鴻去，還隨落葉来。","菊花應未满，請待诗人开。"]', '诗', 'shi', '', NULL, '擬江令於長安歸揚州九日賦 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d8da919-c890-41e1-a680-aecc9ca70f43', '擬江令於長安歸揚州九日賦', '擬江令於长安归揚州九日賦', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["遊人倦蓬轉，鄉思逐雁來。","偏想臨潭菊，芳蘂對誰開。"]', '["游人倦蓬轉，乡思逐雁来。","偏想臨潭菊，芳蘂对誰开。"]', '诗', 'shi', '', NULL, '擬江令於長安歸揚州九日賦 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('099e75cf-5728-437b-b6a5-1b1d6114752d', '和邊城秋氣早', '和邊城秋氣早', 'c5b421d5-4fcf-4983-afbc-50189c7a6749', '唐', '["金微凝素節，玉律應清葭。","邊馬秋聲急，征鴻曉陣斜。","關樹凋涼葉，塞草落寒花。","霧暗長川景，雲昏大漠沙。","谿深路難越，川平望超忽。","極望斷煙飄，遙落驚蓬沒。","霜結龍城吹，水照龜林月。","日色夏猶冷，霜華春未歇。","睿作高紫宸，分明映玄闕。"]', '["金微凝素節，玉律應清葭。","邊马秋声急，征鴻晓陣斜。","关樹凋涼葉，塞草落寒花。","霧暗长川景，云昏大漠沙。","谿深路难越，川平望超忽。","極望斷煙飄，遙落驚蓬沒。","霜結龙城吹，水照龟林月。","日色夏猶冷，霜华春未歇。","睿作高紫宸，分明映玄闕。"]', '诗', 'shi', '', NULL, '和邊城秋氣早 李義府 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ccef6d7-57b4-457b-9db4-b29cff54ec4c', '招諭有懷贈同行人', '招諭有懷贈同行人', 'c5b421d5-4fcf-4983-afbc-50189c7a6749', '唐', '["遠遊冒艱阻，深入勞存諭。","春去辭國門，秋還在邊戍。","軒車行未返，節序催難駐。","陌上悲轉蓬，園中想芳樹。","蜀山自紛糾，岷水恆奔注。","臨汎多苦懷，登攀寡歡趣。","永夕飛淫雨，崇朝蒸毒霧。","不求綏嶺桃，寧美邛鄉蒟。","白狼行欲靜，驄馬何常驅。","願接軺斾塵，聯翩東北騖。"]', '["远游冒艱阻，深入勞存諭。","春去辞国门，秋還在邊戍。","軒车行未返，節序催难駐。","陌上悲轉蓬，园中想芳樹。","蜀山自紛糾，岷水恆奔注。","臨汎多苦懷，登攀寡歡趣。","永夕飞淫雨，崇朝蒸毒霧。","不求綏嶺桃，寧美邛乡蒟。","白狼行欲静，驄马何常驱。","願接軺斾塵，聯翩东北騖。"]', '诗', 'shi', '', NULL, '招諭有懷贈同行人 李義府 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('652ec4c7-b4e7-462f-8ab7-80180baaa44b', '宣正殿芝草', '宣正殿芝草', 'c5b421d5-4fcf-4983-afbc-50189c7a6749', '唐', '["明王敦孝感，寶殿秀靈芝。","色帶朝陽淨，光涵雨露滋。","且標宣德重，更引國恩施。","聖祚今無限，微臣樂未移。"]', '["明王敦孝感，寶殿秀靈芝。","色带朝陽淨，光涵雨露滋。","且標宣德重，更引国恩施。","聖祚今無限，微臣乐未移。"]', '诗', 'shi', '', NULL, '宣正殿芝草 李義府 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01b2ea71-d9bf-4200-abb4-6ff233e05913', '詠鸚鵡', '詠鸚鵡', 'c5b421d5-4fcf-4983-afbc-50189c7a6749', '唐', '["牽弋辭重海，觸網去層巒。","戢翼雕籠際，延思彩霞端。","慕侶朝聲切，離羣夜影寒。","能言殊可貴，相助憶長安。"]', '["牽弋辞重海，觸網去層巒。","戢翼雕籠際，延思彩霞端。","慕侶朝声切，離羣夜影寒。","能言殊可貴，相助憶长安。"]', '诗', 'shi', '', NULL, '詠鸚鵡 李義府 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e0b0608-9117-4935-8e7e-8d63a2be4578', '在巂州遙敍封禪', '在巂州遙敍封禪', 'c5b421d5-4fcf-4983-afbc-50189c7a6749', '唐', '["天齊標巨鎮，日觀啓崇朝。","岧嶤臨渤澥，隱嶙控河沂。","眺迥分吳乘，凌高屬漢祠。","建岳誠爲長，升功諒在茲。","帝猷符廣運，玄範暢文思。","飛聲總地絡，騰化撫乾維。","瑞策開珍鳳，禎圖薦寶龜。","創封超昔夏，修禪掩前姬。","東后方肆覲，西都導六師。","肅駕移星苑，揚罕馭風司。","沸鼓喧平陸，凝蹕靜通逵。","汶陽馳月羽，蒙陰警電麾。","巖花飄曙輦，峰葉蕩春旗。","石閭環藻衛，金壇映黼帷。","仙階溢祕秬，靈檢燿祥芝。","張樂分韶濩，觀禮縱華夷。","佳氣浮丹谷，榮光泛綠坻。","三始貽遐貺，萬歲受重釐。","菲質陶恩獎，趨迹奉軒墀。","觸網淪幽裔，乘徼限明時。","周南昔已歎，邛西今復悲。"]', '["天齊標巨鎮，日观啓崇朝。","岧嶤臨渤澥，隐嶙控河沂。","眺迥分吳乘，凌高屬漢祠。","建岳誠爲长，升功諒在茲。","帝猷符廣運，玄範暢文思。","飞声總地絡，腾化撫乾維。","瑞策开珍鳳，禎圖薦寶龟。","創封超昔夏，修禪掩前姬。","东后方肆覲，西都導六師。","肅駕移星苑，揚罕馭风司。","沸鼓喧平陸，凝蹕静通逵。","汶陽驰月羽，蒙陰警電麾。","巖花飄曙輦，峰葉蕩春旗。","石閭环藻衛，金壇映黼帷。","仙階溢祕秬，靈檢燿祥芝。","張乐分韶濩，观禮縱华夷。","佳氣浮丹谷，榮光泛綠坻。","三始貽遐貺，万歲受重釐。","菲質陶恩獎，趨迹奉軒墀。","觸網淪幽裔，乘徼限明时。","周南昔已歎，邛西今复悲。"]', '诗', 'shi', '', NULL, '在巂州遙敍封禪 李義府 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e759e7de-95bf-4284-a859-d91992c5eba9', '堂堂詞二首 一', '堂堂词二首 一', 'c5b421d5-4fcf-4983-afbc-50189c7a6749', '唐', '["鏤月成歌扇，裁雲作舞衣。","自憐迴雪影，好取洛川歸。"]', '["鏤月成歌扇，裁云作舞衣。","自怜迴雪影，好取洛川归。"]', '诗', 'shi', '', NULL, '堂堂詞二首 一 李義府 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('566d66ff-32e9-4339-8914-6525f5bda71d', '堂堂詞二首 二', '堂堂词二首 二', 'c5b421d5-4fcf-4983-afbc-50189c7a6749', '唐', '["嬾整鴛鴦被，羞褰玳瑁牀。","春風別有意，密處也尋香。"]', '["嬾整鴛鴦被，羞褰玳瑁牀。","春风別有意，密处也尋香。"]', '诗', 'shi', '', NULL, '堂堂詞二首 二 李義府 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c51aed8e-f8e8-4416-9307-2008ea86785b', '詠烏', '詠烏', 'c5b421d5-4fcf-4983-afbc-50189c7a6749', '唐', '["日裏颺朝彩，琴中伴夜啼。","上林如許樹，不借一枝栖。"]', '["日裏颺朝彩，琴中伴夜啼。","上林如許樹，不借一枝栖。"]', '诗', 'shi', '', NULL, '詠烏 李義府 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1804f164-cdc0-4e4d-bd04-3b35f4df7eba', '從軍行二首 一', '從軍行二首 一', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["塗山烽候驚，弭節度龍城。","冀馬樓蘭將，燕犀上谷兵。","劒寒花不落，弓曉月逾明。","凜凜嚴霜節，冰壯黃河絕。","蔽日卷征蓬，浮天散飛雪。","全兵值月滿，精騎乘膠折。","結髮早驅馳，辛苦事旌麾。","馬凍重關冷，輪摧九折危。","獨有西山將，年年屬數奇。"]', '["塗山烽候驚，弭節度龙城。","冀马楼蘭將，燕犀上谷兵。","劒寒花不落，弓晓月逾明。","凜凜嚴霜節，冰壯黄河絕。","蔽日卷征蓬，浮天散飞雪。","全兵值月满，精騎乘膠折。","結髮早驱驰，辛苦事旌麾。","马凍重关冷，輪摧九折危。","独有西山將，年年屬數奇。"]', '诗', 'shi', '', NULL, '從軍行二首 一 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fab37680-5df4-4a52-9346-3fc5f0024abb', '從軍行二首 二', '從軍行二首 二', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["烽火發金微，連營出武威。","孤城塞雲起，絕陣虜塵飛。","俠客吸龍劒，惡少縵胡衣。","朝摩骨都壘，夜解谷蠡圍。","蕭關遠無極，蒲海廣難依。","沙磴離旌斷，晴川候馬歸。","交河梁已畢，燕山斾欲揮。","方知萬里相，侯服見光輝。"]', '["烽火發金微，連營出武威。","孤城塞云起，絕陣虜塵飞。","俠客吸龙劒，惡少縵胡衣。","朝摩骨都壘，夜解谷蠡圍。","蕭关远無極，蒲海廣难依。","沙磴離旌斷，晴川候马归。","交河梁已畢，燕山斾欲揮。","方知万里相，侯服见光輝。"]', '诗', 'shi', '', NULL, '從軍行二首 二 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41b76620-4668-4173-a790-6fcc55193f4a', '擬飲馬長城窟', '擬饮马长城窟', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["馳馬渡河干，流深馬渡難。","前逢錦車使，都護在樓蘭。","輕騎猶銜勒，疑兵尚解鞍。","溫池下絕澗，棧道接危巒。","拓地勛未賞，亡城律豈寬。","有月關猶暗，經春隴尚寒。","雲昏無復影，冰合不聞湍。","懷君不可遇，聊持報一飱。"]', '["驰马渡河干，流深马渡难。","前逢錦车使，都護在楼蘭。","轻騎猶銜勒，疑兵尚解鞍。","溫池下絕澗，棧道接危巒。","拓地勛未賞，亡城律豈寬。","有月关猶暗，經春隴尚寒。","云昏無复影，冰合不闻湍。","懷君不可遇，聊持報一飱。"]', '诗', 'shi', '', NULL, '擬飲馬長城窟 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a0fe0ce-a9d7-47c7-b348-c5798c181d14', '出塞', '出塞', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["上將三略遠，元戎九命尊。","緬懷古人節，思酬明主恩。","山西多勇氣，塞北有遊魂。","揚桴上隴坂，勒騎下平原。","誓將絕沙漠，悠然去玉門。","輕齎不遑舍，驚策騖戎軒。","凜凜邊風急，蕭蕭征馬煩。","雪暗天山道，冰塞交河源。","霧鋒黯無色，霜旗凍不翻。","耿介倚長劒，日落風塵昏。"]', '["上將三略远，元戎九命尊。","緬懷古人節，思酬明主恩。","山西多勇氣，塞北有游魂。","揚桴上隴坂，勒騎下平原。","誓將絕沙漠，悠然去玉门。","轻齎不遑舍，驚策騖戎軒。","凜凜邊风急，蕭蕭征马煩。","雪暗天山道，冰塞交河源。","霧鋒黯無色，霜旗凍不翻。","耿介倚长劒，日落风塵昏。"]', '诗', 'shi', '', NULL, '出塞 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('171ea258-6b15-4d74-98e3-e0e66539c640', '結客少年場行', '結客少年場行', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["韓魏多奇節，倜儻遺聲利。","共矜然諾心，各負縱橫志。","結交一言重，相期千里至。","綠沈明月弦，金絡浮雲轡。","吹簫入吳市，擊筑遊燕肆。","尋源博望侯，結客遠相求。","少年懷一顧，長驅背隴頭。","燄燄戈霜動，耿耿劒虹浮。","天山冬夏雪，交河南北流。","雲起龍沙暗，木落鴈門秋。","輕生殉知己，非是爲身謀。"]', '["韓魏多奇節，倜儻遺声利。","共矜然諾心，各負縱橫志。","結交一言重，相期千里至。","綠沈明月弦，金絡浮云轡。","吹簫入吳市，擊筑游燕肆。","尋源博望侯，結客远相求。","少年懷一顧，长驱背隴头。","燄燄戈霜动，耿耿劒虹浮。","天山冬夏雪，交河南北流。","云起龙沙暗，木落鴈门秋。","轻生殉知己，非是爲身謀。"]', '诗', 'shi', '', NULL, '結客少年場行 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cf3501c-d491-4764-bf7e-71030a4cfe1a', '怨歌行', '怨歌行', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["紫殿秋風冷，雕甍落日沈。","裁紈悽斷曲，織素別離心。","掖庭羞改畫，長門不惜金。","寵移恩稍薄，情疎恨轉深。","香銷翠羽帳，弦斷鳳皇琴。","鏡前紅粉歇，階上綠苔侵。","誰言掩歌扇，翻作白頭吟。"]', '["紫殿秋风冷，雕甍落日沈。","裁紈悽斷曲，织素別離心。","掖庭羞改畫，长门不惜金。","寵移恩稍薄，情疎恨轉深。","香銷翠羽帳，弦斷鳳皇琴。","镜前紅粉歇，階上綠苔侵。","誰言掩歌扇，翻作白头吟。"]', '诗', 'shi', '', NULL, '怨歌行 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('979c5ba2-7c47-4bf4-aa3f-d803055f4a43', '中婦織流黃', '中婦织流黄', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["寒閨織素錦，含怨斂雙蛾。","綜新交縷澁，經脆斷絲多。","衣香逐舉袖，釧動應鳴梭。","還恐裁縫罷，無信達交河。"]', '["寒閨织素錦，含怨斂雙蛾。","綜新交縷澁，經脆斷絲多。","衣香逐舉袖，釧动應鳴梭。","還恐裁縫罷，無信達交河。"]', '诗', 'shi', '', NULL, '中婦織流黃 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0cd3f37-c4fb-4cde-827e-744e2bd8d3d5', '門有車馬客', '门有车马客', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["陳遵重交結，田蚡擅豪華。","曲臺臨上路，高軒抵狹斜。","赭汗千金馬，繡軸五香車。","白鶴隨飛蓋，朱鷺入鳴笳。","夏蓮開劒水，春桃發綬花。","高談辯飛兔，摛藻握靈蛇。","逢恩出毛羽，失路委泥沙。","曖曖風煙晚，路長歸騎遠。","日斜青瑣第，塵飛金谷苑。","危弦促柱奏巴渝，遺簪墮珥解羅襦。","如何守直道，翻使谷名愚。"]', '["陳遵重交結，田蚡擅豪华。","曲台臨上路，高軒抵狹斜。","赭汗千金马，繡軸五香车。","白鹤隨飞蓋，朱鷺入鳴笳。","夏蓮开劒水，春桃發綬花。","高談辯飞兔，摛藻握靈蛇。","逢恩出毛羽，失路委泥沙。","曖曖风煙晚，路长归騎远。","日斜青瑣第，塵飞金谷苑。","危弦促柱奏巴渝，遺簪墮珥解羅襦。","如何守直道，翻使谷名愚。"]', '诗', 'shi', '', NULL, '門有車馬客 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a088863e-2ee6-4be9-a8ea-1af19ae06605', '飛來雙白鶴', '飞来雙白鹤', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["飛來雙白鶴，奮翼遠凌煙。","俱棲集紫蓋，一舉背青田。","颺影過伊洛，流聲入管弦。","鳴羣倒景外，刷羽閬風前。","暎海疑浮雪，拂澗瀉飛泉。","燕雀寧知去，蜉蝣不識還。","何言別儔侶，從此間山川。","顧步已相失，裴回各自憐。","危心猶警露，哀響詎聞天。","無因振六翮，輕舉復隨仙。"]', '["飞来雙白鹤，奮翼远凌煙。","俱棲集紫蓋，一舉背青田。","颺影過伊洛，流声入管弦。","鳴羣倒景外，刷羽閬风前。","暎海疑浮雪，拂澗瀉飞泉。","燕雀寧知去，蜉蝣不識還。","何言別儔侶，從此间山川。","顧步已相失，裴回各自怜。","危心猶警露，哀响詎闻天。","無因振六翮，轻舉复隨仙。"]', '诗', 'shi', '', NULL, '飛來雙白鶴 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13d43a14-988d-48a8-86f5-c1b6fa3baced', '奉和幽山雨後應令', '奉和幽山雨後應令', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["肅城鄰上苑，黃山邇桂宮。","雨歇連峰翠，煙開竟野通。","排虛翔戲鳥，跨水落長虹。","日下林全暗，雲收嶺半空。","山泉鳴石澗，地籟響巖風。"]', '["肅城鄰上苑，黄山邇桂宮。","雨歇連峰翠，煙开竟野通。","排虛翔戲鸟，跨水落长虹。","日下林全暗，云收嶺半空。","山泉鳴石澗，地籟响巖风。"]', '诗', 'shi', '', NULL, '奉和幽山雨後應令 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3baa6533-bc54-4764-b5fd-676af37251ad', '賦得吳都', '賦得吳都', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["畫野通淮泗，星躔應斗牛。","玉牒宏圖表，黃旗美氣浮。","三分開霸業，萬里宅神州。","高臺臨茂苑，飛閣跨澄流。","江濤如素蓋，海氣似朱樓。","吳趨自有樂，還似鏡中遊。"]', '["畫野通淮泗，星躔應斗牛。","玉牒宏圖表，黄旗美氣浮。","三分开霸業，万里宅神州。","高台臨茂苑，飞閣跨澄流。","江濤如素蓋，海氣似朱楼。","吳趨自有乐，還似镜中游。"]', '诗', 'shi', '', NULL, '賦得吳都 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2de16c9f-78be-47d6-80f1-1cb47b9a1a59', '賦得慎罰', '賦得慎罰', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["帝圖光往冊，上德表鴻名。","道冠二儀始，風高三代英。","樂和知化洽，訟息表刑清。","罰輕猶在念，忽喜尚留情。","明慎全無枉，哀矜在好生。","五疵過亦察，二辟理彌精。","幪巾示廉恥，嘉石務詳平。","每削繁苛性，常深惻隱誠。","政寬思濟猛，疑罪必從輕。","于張懲不濫，陳郭憲無傾。","刑措諒斯在，歡然仰頌聲。"]', '["帝圖光往冊，上德表鴻名。","道冠二儀始，风高三代英。","乐和知化洽，訟息表刑清。","罰轻猶在念，忽喜尚留情。","明慎全無枉，哀矜在好生。","五疵過亦察，二辟理彌精。","幪巾示廉恥，嘉石務詳平。","每削繁苛性，常深惻隐誠。","政寬思濟猛，疑罪必從轻。","于張懲不濫，陳郭憲無傾。","刑措諒斯在，歡然仰頌声。"]', '诗', 'shi', '', NULL, '賦得慎罰 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42a6bb0b-f307-4d77-a524-25ef78162f5e', '奉和詠日午', '奉和詠日午', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["高天淨秋色，長漢轉曦車。","玉樹陰初正，桐圭影未斜。","翠蓋飛圓彩，明鏡發輕花。","再中良表瑞，共仰璧暉賒。"]', '["高天淨秋色，长漢轉曦车。","玉樹陰初正，桐圭影未斜。","翠蓋飞圓彩，明镜發轻花。","再中良表瑞，共仰璧暉賒。"]', '诗', 'shi', '', NULL, '奉和詠日午 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c876207a-080d-401c-a2b5-2f3392777069', '發營逢雨應詔', '發營逢雨應詔', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["豫遊欣勝地，皇澤乃先天。","油雲陰御道，膏雨潤公田。","隴麥霑逾翠，山花濕更然。","稼穡良所重，方復悅豐年。"]', '["豫游欣勝地，皇澤乃先天。","油云陰御道，膏雨潤公田。","隴麦霑逾翠，山花濕更然。","稼穡良所重，方复悅豐年。"]', '诗', 'shi', '', NULL, '發營逢雨應詔 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03ae3687-4641-491d-b7bb-d6aa58f980d0', '賦得臨池竹應制', '賦得臨池竹應制', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["蔥翠梢雲質，垂彩暎清池。","波泛含風影，流搖防露枝。","龍鱗漾嶰谷，鳳翅拂漣漪。","欲識凌冬性，唯有歲寒知。"]', '["蔥翠梢云質，垂彩暎清池。","波泛含风影，流搖防露枝。","龙鱗漾嶰谷，鳳翅拂漣漪。","欲識凌冬性，唯有歲寒知。"]', '诗', 'shi', '', NULL, '賦得臨池竹應制 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5416790-1c68-4ab1-ba7f-147999ebb6ab', '侍宴應詔賦韻得前字', '侍宴應詔賦韻得前字', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["芬芳禁林晚，容與桂丹前。","橫空一鳥度，照水百花然。","綠野明斜日，青山澹晚煙。","濫陪終宴賞，握管類窺天。"]', '["芬芳禁林晚，容與桂丹前。","橫空一鸟度，照水百花然。","綠野明斜日，青山澹晚煙。","濫陪終宴賞，握管類窺天。"]', '诗', 'shi', '', NULL, '侍宴應詔賦韻得前字 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d94daa5d-f90b-403e-a054-4b784599a4d1', '侍宴歸鴈堂', '侍宴归鴈堂', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["歌堂面淥水，舞館接金塘。","竹開霜後翠，梅動雪前香。","鳧歸初命侶，鴈起欲分行。","刷羽同棲集，懷恩愧稻粱。"]', '["歌堂面淥水，舞館接金塘。","竹开霜後翠，梅动雪前香。","鳧归初命侶，鴈起欲分行。","刷羽同棲集，懷恩愧稻粱。"]', '诗', 'shi', '', NULL, '侍宴歸鴈堂 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ee293f0-5404-4cbf-b845-e0c378c41e04', '凌晨早朝', '凌晨早朝', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["萬瓦宵光曙，重簷夕霧收。","玉花停夜燭，金壺送曉籌。","日暉青瑣殿，霞生結綺樓。","重門應啓路，通籍引王侯。"]', '["万瓦宵光曙，重簷夕霧收。","玉花停夜燭，金壺送晓籌。","日暉青瑣殿，霞生結綺楼。","重门應啓路，通籍引王侯。"]', '诗', 'shi', '', NULL, '凌晨早朝 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14f8c2fc-39be-4d6e-b5e5-a9f802d99333', '奉和詠風應魏王教', '奉和詠风應魏王教', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["逐舞飄輕袖，傳歌共繞梁。","動枝生亂影，吹花送遠香。"]', '["逐舞飄轻袖，傳歌共繞梁。","动枝生亂影，吹花送远香。"]', '诗', 'shi', '', NULL, '奉和詠風應魏王教 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ae90371-da09-4531-b003-0a731f20fba0', '初晴應教', '初晴應教', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["初日明燕館，新溜滿梁池。","歸雲半入嶺，殘滴尚懸枝。"]', '["初日明燕館，新溜满梁池。","归云半入嶺，殘滴尚懸枝。"]', '诗', 'shi', '', NULL, '初晴應教 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8570cd7c-4475-4ecf-b65a-5a5d60802288', '春夜', '春夜', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["春苑月裴回，竹堂侵夜開。","驚鳥排林度，風花隔水來。"]', '["春苑月裴回，竹堂侵夜开。","驚鸟排林度，风花隔水来。"]', '诗', 'shi', '', NULL, '春夜 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05a713f6-13c8-403d-91ac-4c0341bbd9ee', '詠舞', '詠舞', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["繁弦奏淥水，長袖轉回鸞。","一雙俱應節，還似鏡中看。"]', '["繁弦奏淥水，长袖轉回鸾。","一雙俱應節，還似镜中看。"]', '诗', 'shi', '', NULL, '詠舞 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a62e6592-862c-46e1-b7c0-788f917783ef', '詠螢', '詠螢', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["的歷流光小，飄颻弱翅輕。","恐畏無人識，獨自暗中明。"]', '["的歷流光小，飄颻弱翅轻。","恐畏無人識，独自暗中明。"]', '诗', 'shi', '', NULL, '詠螢 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8998cfc-470f-45e6-a06c-5e30c18c0645', '蟬', '蟬', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["垂緌飲清露，流響出疎桐。","居高聲自遠，非是藉秋風。"]', '["垂緌饮清露，流响出疎桐。","居高声自远，非是藉秋风。"]', '诗', 'shi', '', NULL, '蟬 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c391ef18-f80a-4816-859b-44b1bf804250', '秋鴈', '秋鴈', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["日暮霜風急，羽翮轉難任。","爲有傳書意，聯翩入上林。"]', '["日暮霜风急，羽翮轉难任。","爲有傳书意，聯翩入上林。"]', '诗', 'shi', '', NULL, '秋鴈 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46b17890-4fbe-4d78-9fae-35ad3bad08e2', '奉和月夜觀星應令', '奉和月夜观星應令', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["早秋炎景暮，初弦月彩新。","清風滌暑氣，零露淨囂塵。","薄霧銷輕縠，鮮雲卷夕鱗。","休光灼前曜，瑞彩接重輪。","緣情摛聖藻，並作命徐陳。","宿草誠渝濫，吹噓偶搢紳。","天文豈易述，徒知仰北辰。"]', '["早秋炎景暮，初弦月彩新。","清风滌暑氣，零露淨囂塵。","薄霧銷轻縠，鲜云卷夕鱗。","休光灼前曜，瑞彩接重輪。","緣情摛聖藻，並作命徐陳。","宿草誠渝濫，吹噓偶搢紳。","天文豈易述，徒知仰北辰。"]', '诗', 'shi', '', NULL, '奉和月夜觀星應令 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b1d200a-d81e-4a4e-8a5e-419b82acd786', '和鑾輿頓戲下', '和鑾輿頓戲下', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["重輪依紫極，前耀奉丹霄。","天經戀宸扆，帝命扈仙鑣。","乘[星]開鶴禁，帶月下虹橋。","銀書含曉色，金輅轉晨飆。","霧澈軒營近，塵暗苑城遙。","蓮花分秀蕚，竹箭下驚潮。","撫己慙龍幹，承恩集鳳條。","瑤山盛風樂，抽簡薦徒謠。"]', '["重輪依紫極，前耀奉丹霄。","天經戀宸扆，帝命扈仙鑣。","乘[星]开鹤禁，带月下虹橋。","銀书含晓色，金輅轉晨飆。","霧澈軒營近，塵暗苑城遙。","蓮花分秀蕚，竹箭下驚潮。","撫己慙龙幹，承恩集鳳條。","瑤山盛风乐，抽簡薦徒謠。"]', '诗', 'shi', '', NULL, '和鑾輿頓戲下 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a84dc5de-b783-4022-aa4f-d971d60e9c73', '奉和至壽春應令', '奉和至壽春應令', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["瑤山盛風樂，南巡務逸遊。","如何事巡撫，民瘼諒斯求。","文鶴揚輕蓋，蒼龍飾桂舟。","泛沫縈沙嶼，寒澌擁急流。","路指八仙館，途經百尺樓。","眷言昔遊踐，廻駕且淹留。","後車喧鳳吹，前旌暎綵旒。","龍驂駐六馬，飛閣上三休。","調諧金石奏，歡洽羽觴浮。","天文徒可仰，何以廁琳球。"]', '["瑤山盛风乐，南巡務逸游。","如何事巡撫，民瘼諒斯求。","文鹤揚轻蓋，蒼龙飾桂舟。","泛沫縈沙嶼，寒澌擁急流。","路指八仙館，途經百尺楼。","眷言昔游踐，廻駕且淹留。","後车喧鳳吹，前旌暎綵旒。","龙驂駐六马，飞閣上三休。","調諧金石奏，歡洽羽觴浮。","天文徒可仰，何以廁琳球。"]', '诗', 'shi', '', NULL, '奉和至壽春應令 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ad57948-bcb6-4fa1-86f4-0901414386c8', '奉和幸江都應詔', '奉和幸江都應詔', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["南國行周化，稽山秘夏圖。","百王豈殊軌，千載協前謨。","肆覲遵時豫，順動悅來蘇。","安流進玉軸，戒道翼金吾。","龍旂煥辰象，鳳吹溢川塗。","封唐昔敷錫，分陝被荆吳。","沐道咸知讓，慕義久成都。","冬律初飛管，陽鳥正銜蘆。","嚴飆肅林薄，曖景澹江湖。","鴻私浹幽遠，厚澤潤凋枯。","虞琴起歌詠，漢筑動巴歈。","多幸霑行葦，無庸類散樗。"]', '["南国行周化，稽山秘夏圖。","百王豈殊軌，千載協前謨。","肆覲遵时豫，順动悅来蘇。","安流進玉軸，戒道翼金吾。","龙旂煥辰象，鳳吹溢川塗。","封唐昔敷錫，分陝被荆吳。","沐道咸知讓，慕義久成都。","冬律初飞管，陽鸟正銜蘆。","嚴飆肅林薄，曖景澹江湖。","鴻私浹幽远，厚澤潤凋枯。","虞琴起歌詠，漢筑动巴歈。","多幸霑行葦，無庸類散樗。"]', '诗', 'shi', '', NULL, '奉和幸江都應詔 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c53a74b3-e54a-47af-aba1-eb775a5e4c5a', '奉和獻歲讌宮臣', '奉和獻歲讌宮臣', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["履端初起節，長苑命高筵。","肆夏喧金奏，重潤響朱弦。","春光催柳色，日彩泛槐煙。","微臣同濫吹，謬得仰鈞天。"]', '["履端初起節，长苑命高筵。","肆夏喧金奏，重潤响朱弦。","春光催柳色，日彩泛槐煙。","微臣同濫吹，謬得仰鈞天。"]', '诗', 'shi', '', NULL, '奉和獻歲讌宮臣 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4425fe97-a66c-4f48-bd16-6f506aa20197', '奉和出潁至淮應令', '奉和出潁至淮應令', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["良晨喜利涉，解纜入淮潯。","寒流泛鷁首，霜吹響哀吟。","潛鱗波裏躍，水鳥浪前沈。","邗溝非復遠，悵望悅宸襟。"]', '["良晨喜利涉，解纜入淮潯。","寒流泛鷁首，霜吹响哀吟。","潛鱗波裏躍，水鸟浪前沈。","邗溝非复远，悵望悅宸襟。"]', '诗', 'shi', '', NULL, '奉和出潁至淮應令 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf919565-500a-420f-9350-da5f76c488c5', '應詔嘲司花女', '應詔嘲司花女', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["學畫鴉黃半未成，垂肩軃嚲袖太憨生。","緣憨却得君王惜，長把花枝傍輦行。"]', '["学畫鴉黄半未成，垂肩軃嚲袖太憨生。","緣憨却得君王惜，长把花枝傍輦行。"]', '诗', 'shi', '', NULL, '應詔嘲司花女 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c0166ce-92a9-4c70-adf9-6f9855355f18', '古意六首 一', '古意六首 一', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["幽人在何所？紫巖有仙躅。","月下橫寶琴，此外將安欲。","材抽嶧山榦，徽點崑丘玉。","漆抱蛟龍脣，絲纏鳳凰足。","前彈廣陵罷，後以明光續。","百金買一聲，千金傳一曲。","世無鍾子期，誰知心所屬。"]', '["幽人在何所？紫巖有仙躅。","月下橫寶琴，此外將安欲。","材抽嶧山榦，徽点崑丘玉。","漆抱蛟龙脣，絲纏鳳凰足。","前彈廣陵罷，後以明光續。","百金買一声，千金傳一曲。","世無鍾子期，誰知心所屬。"]', '诗', 'shi', '', NULL, '古意六首 一 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7db0317c-07dd-4ce1-a73b-b767e5a19f38', '古意六首 二', '古意六首 二', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["竹生大夏谿，蒼蒼富奇質。","綠葉吟風勁，翠莖犯霄密。","霜霰封其柯，鵷鸞食其實。","寧知軒轅後，更有伶倫出。","刀斧俄見尋，根株坐相失。","裁爲十二管，吹作雄雌律。","有用雖自傷，無心復招疾。","不如山上草，離離保終吉。"]', '["竹生大夏谿，蒼蒼富奇質。","綠葉吟风勁，翠莖犯霄密。","霜霰封其柯，鵷鸾食其實。","寧知軒轅後，更有伶倫出。","刀斧俄见尋，根株坐相失。","裁爲十二管，吹作雄雌律。","有用雖自傷，無心复招疾。","不如山上草，離離保終吉。"]', '诗', 'shi', '', NULL, '古意六首 二 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e06d2cb-be89-4c66-8e62-1eddd4ef0369', '古意六首 三', '古意六首 三', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["寶龜尺二寸，由來宅深水。","浮遊五湖內，宛轉三江裏。","何不深復深，輕然至溱洧。","溱洧源流狹，春秋不濡軌。","漁人遞往還，網罟相縈藟。","一朝失運會，刳腸血流死。","豐骨輸廟堂，鮮腴籍籩簋。","棄置誰怨尤，自我招此否。","餘靈寄明卜，復來欽所履。"]', '["寶龟尺二寸，由来宅深水。","浮游五湖內，宛轉三江裏。","何不深复深，轻然至溱洧。","溱洧源流狹，春秋不濡軌。","漁人遞往還，網罟相縈藟。","一朝失運會，刳腸血流死。","豐骨輸廟堂，鲜腴籍籩簋。","棄置誰怨尤，自我招此否。","餘靈寄明卜，复来欽所履。"]', '诗', 'shi', '', NULL, '古意六首 三 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8604b82d-92f4-4ed1-89a4-77e082c776c8', '古意六首 四', '古意六首 四', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["松生北巖下，由來人徑絕。","布葉捎雲煙，插根擁巖穴。","自言生得地，獨負凌雲潔。","何時畏斤斧，幾度經霜雪。","風驚西北枝，雹隕東南節。","不知歲月久，稍覺枝榦折。","藤蘿上下碎，枝榦縱橫裂。","行當糜爛盡，坐共灰塵滅。","寧關匠石顧，豈爲王孫折。","盛衰自有時，聖賢未嘗屑。","寄言悠悠者，無爲嗟大耋。"]', '["松生北巖下，由来人徑絕。","布葉捎云煙，插根擁巖穴。","自言生得地，独負凌云潔。","何时畏斤斧，幾度經霜雪。","风驚西北枝，雹隕东南節。","不知歲月久，稍覺枝榦折。","藤蘿上下碎，枝榦縱橫裂。","行當糜爛尽，坐共灰塵滅。","寧关匠石顧，豈爲王孫折。","盛衰自有时，聖賢未嘗屑。","寄言悠悠者，無爲嗟大耋。"]', '诗', 'shi', '', NULL, '古意六首 四 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0307c2ec-224c-4967-aac7-4b84cf4de02a', '古意六首 五', '古意六首 五', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["桂樹何蒼蒼，秋來花更芳。","自言歲寒性，不知露與霜。","幽人重其德，徙植臨前堂。","連拳八九樹，偃蹇二三行。","枝枝自相糾，葉葉還相當。","去來雙鴻鵠，栖息兩鴛鴦。","榮蔭誠不厚，斤斧亦勿傷。","赤心許君時，此意那可忘。"]', '["桂樹何蒼蒼，秋来花更芳。","自言歲寒性，不知露與霜。","幽人重其德，徙植臨前堂。","連拳八九樹，偃蹇二三行。","枝枝自相糾，葉葉還相當。","去来雙鴻鵠，栖息兩鴛鴦。","榮蔭誠不厚，斤斧亦勿傷。","赤心許君时，此意那可忘。"]', '诗', 'shi', '', NULL, '古意六首 五 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61ad3ac9-11f4-4d59-a516-a9a18d31fef0', '古意六首 六', '古意六首 六', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["彩鳳欲將歸，提羅出郊訪。","羅張大澤已，鳳入重雲颺。","朝栖崑閬木，夕飲蓬壺漲。","問鳳那遠飛，賢君坐相望。","鳳言荷深德，微禽安足尚。","但使雛卵全，無令[矰]繳放。","皇臣力牧舉，帝樂簫韶暢。","自有來巢時，明年阿閣上。"]', '["彩鳳欲將归，提羅出郊訪。","羅張大澤已，鳳入重云颺。","朝栖崑閬木，夕饮蓬壺漲。","问鳳那远飞，賢君坐相望。","鳳言荷深德，微禽安足尚。","但使雛卵全，無令[矰]繳放。","皇臣力牧舉，帝乐簫韶暢。","自有来巢时，明年阿閣上。"]', '诗', 'shi', '', NULL, '古意六首 六 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d8669b3-2295-4fe8-9308-de8f863c488c', '石竹詠', '石竹詠', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["萋萋結綠枝，曄曄垂朱英。","常恐零露降，不得全其生。","歎息聊自思，此生豈我情。","昔我未生時，誰者令我萌。","棄置勿重陳，委化何足驚。"]', '["萋萋結綠枝，曄曄垂朱英。","常恐零露降，不得全其生。","歎息聊自思，此生豈我情。","昔我未生时，誰者令我萌。","棄置勿重陳，委化何足驚。"]', '诗', 'shi', '', NULL, '石竹詠 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90016a03-6bc5-4d06-b055-7ad10977c73c', '田家三首 一', '田家三首 一', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["阮籍生涯懶，嵇康意氣疎。","相逢一醉飽，獨坐數行書。","小池聊養鶴，閑田且牧豬。","草生元亮徑，花暗子雲居。","倚牀看婦織，登壠課兒鋤。","迴頭尋仙事，併是一空虛。"]', '["阮籍生涯懶，嵇康意氣疎。","相逢一醉飽，独坐數行书。","小池聊養鹤，闲田且牧豬。","草生元亮徑，花暗子云居。","倚牀看婦织，登壠課兒鋤。","迴头尋仙事，併是一空虛。"]', '诗', 'shi', '', NULL, '田家三首 一 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac3d0f67-39fd-4b49-9bf7-626d08eb5e4d', '田家三首 二', '田家三首 二', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["家住箕山下，門枕潁川濱。","不知今有漢，唯言昔避秦。","琴伴前庭月，酒勸後園春。","自得中林士，何忝上皇人。"]', '["家住箕山下，门枕潁川濱。","不知今有漢，唯言昔避秦。","琴伴前庭月，酒勸後园春。","自得中林士，何忝上皇人。"]', '诗', 'shi', '', NULL, '田家三首 二 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3723534b-dbdd-415b-81d6-3143a13ee5e5', '田家三首 三', '田家三首 三', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["平生唯酒樂，作性不能無。","朝朝訪鄉里，夜夜遣人酤。","家貧留客久，不暇道精麤。","抽簾持益炬，拔簀更燃爐。","恆聞飲不足，何見有殘壺。"]', '["平生唯酒乐，作性不能無。","朝朝訪乡里，夜夜遣人酤。","家貧留客久，不暇道精麤。","抽簾持益炬，拔簀更燃爐。","恆闻饮不足，何见有殘壺。"]', '诗', 'shi', '', NULL, '田家三首 三 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9532dec6-d0e9-415d-88ee-58ff440c31ac', '贈李徵君大壽', '贈李徵君大壽', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["孔淳辭散騎，陸昶謝中郎。","幅巾朝帝罷，杖策去官忙。","附車還趙郡，乘船向武昌。","九徵書未已，十辟譽彌彰。","副君迎綺季，天子送嚴光。","灞陵幽徑近，磻谿隱路長。","編蓬還作室，績草更爲裳。","會稽置樵處，蘭陵賣藥行。","看書惟道德，開教止農桑。","別有幽懷侶，由來高讓王。","前年辭厚幣，今歲返寒鄉。","有書橫石架，無氈坐土牀。","蘭英猶足釀，竹實本無糧。","澗松寒轉直，山菊秋自香。","管寧存祭禮，王霸重朝章。","去去相隨去，披裘驕盛唐。"]', '["孔淳辞散騎，陸昶謝中郎。","幅巾朝帝罷，杖策去官忙。","附车還趙郡，乘船向武昌。","九徵书未已，十辟譽彌彰。","副君迎綺季，天子送嚴光。","灞陵幽徑近，磻谿隐路长。","編蓬還作室，績草更爲裳。","會稽置樵处，蘭陵賣藥行。","看书惟道德，开教止農桑。","別有幽懷侶，由来高讓王。","前年辞厚幣，今歲返寒乡。","有书橫石架，無氈坐土牀。","蘭英猶足釀，竹實本無糧。","澗松寒轉直，山菊秋自香。","管寧存祭禮，王霸重朝章。","去去相隨去，披裘驕盛唐。"]', '诗', 'shi', '', NULL, '贈李徵君大壽 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9dfe173-a9c6-4f9f-82b1-d7bcceb77ce2', '山中敍志', '山中敍志', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["物外知何事，山中無所有。","風鳴靜夜琴，月照芳春酒。","直置百年內，誰論千載後。","張奉娉賢妻，老萊籍嘉偶。","孟光儻未嫁，梁鴻正須婦。"]', '["物外知何事，山中無所有。","风鳴静夜琴，月照芳春酒。","直置百年內，誰論千載後。","張奉娉賢妻，老萊籍嘉偶。","孟光儻未嫁，梁鴻正須婦。"]', '诗', 'shi', '', NULL, '山中敍志 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0aceead-b9c4-4755-95a1-441f4e0927be', '贈梁公', '贈梁公', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["我欲圖世樂，斯樂難可常。","位大招譏嫌，祿極生禍殃。","聖莫若周公，忠豈踰霍光。","成王已興誚，宣帝如負芒。","范蠡何智哉，單舟戒輕裝。","疏廣豈不懷，策杖還故鄉。","朱門雖足悅，赤族亦可傷。","履霜成堅冰，知足勝不祥。","我今窮家子，自言此見長。","功成皆能退，在昔誰滅亡。"]', '["我欲圖世乐，斯乐难可常。","位大招譏嫌，祿極生禍殃。","聖莫若周公，忠豈踰霍光。","成王已兴誚，宣帝如負芒。","范蠡何智哉，單舟戒轻裝。","疏廣豈不懷，策杖還故乡。","朱门雖足悅，赤族亦可傷。","履霜成堅冰，知足勝不祥。","我今窮家子，自言此见长。","功成皆能退，在昔誰滅亡。"]', '诗', 'shi', '', NULL, '贈梁公 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ea4f2bf-c628-44f9-a29b-523071390e61', '薛記室收過莊見尋率題古意以贈', '薛記室收過莊见尋率題古意以贈', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["伊昔逢喪亂，曆數閏當餘。","豺狼塞衢路，桑梓成丘墟。","余及爾皆亡，東西各異居。","爾爲背風鳥，我爲涸轍魚。","逮承雲雷後，欣逢天地初。","東川聊下釣，南畝試揮鋤。","資稅幸不及，伏臘常有儲。","散誕時須酒，蕭條嬾向書。","朽木不可雕，短翮將焉攄。","故人有深契，過我蓬高廬。","曳裾出門迎，握手登前除。","相看非舊顏，忽若形骸疎。","追道宿昔事，切切心相於。","憶我少年時，攜手遊東渠。","梅李夾兩岸，花枝何扶疏。","同志亦不多，西莊有姚徐。","嘗愛陶淵明，酌醴焚枯魚。","嘗學公孫弘，策杖牧羣豬。","追念甫如昨，奄忽成空虛。","人生詎能幾，歲歲常不舒。","賴有北山僧，教我以真如。","使我視聽遣，自覺塵累祛。","何事須筌蹄，今已得兔魚。","舊遊儻多暇，同此釋紛拏。"]', '["伊昔逢喪亂，曆數閏當餘。","豺狼塞衢路，桑梓成丘墟。","余及爾皆亡，东西各異居。","爾爲背风鸟，我爲涸轍鱼。","逮承云雷後，欣逢天地初。","东川聊下釣，南畝試揮鋤。","資稅幸不及，伏臘常有儲。","散誕时須酒，蕭條嬾向书。","朽木不可雕，短翮將焉攄。","故人有深契，過我蓬高廬。","曳裾出门迎，握手登前除。","相看非旧顏，忽若形骸疎。","追道宿昔事，切切心相於。","憶我少年时，携手游东渠。","梅李夾兩岸，花枝何扶疏。","同志亦不多，西莊有姚徐。","嘗愛陶淵明，酌醴焚枯鱼。","嘗学公孫弘，策杖牧羣豬。","追念甫如昨，奄忽成空虛。","人生詎能幾，歲歲常不舒。","賴有北山僧，教我以真如。","使我視听遣，自覺塵累祛。","何事須筌蹄，今已得兔鱼。","旧游儻多暇，同此釋紛拏。"]', '诗', 'shi', '', NULL, '薛記室收過莊見尋率題古意以贈 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6514d6a-a16f-4288-b7f8-fbea9b88bd08', '晚年敍志示翟處士', '晚年敍志示翟处士', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["弱齡慕奇調，無事不兼修。","望氣登重閣，占星上小樓。","明經思待詔，學劍覓封侯。","棄繻頻北上，懷刺幾西遊。","中年逢喪亂，非復昔追求。","失路青門隱，藏名白社遊。","風雲私所愛，屠博暗爲儔。","解紛曾霸越，釋難頗存周。","晚歲聊長想，生涯太若浮。","歸來南畝上，更坐北溪頭。","古岸多磐石，春泉足細流。","東隅誠已謝，西景懼難收。","無謂退耕近，伏念已經秋。","庚桑逢處跪，陶潛見人羞。","三晨寧舉火，五月鎮披裘。","自有居常樂，誰知身世憂。"]', '["弱齡慕奇調，無事不兼修。","望氣登重閣，占星上小楼。","明經思待詔，学劍覓封侯。","棄繻頻北上，懷刺幾西游。","中年逢喪亂，非复昔追求。","失路青门隐，藏名白社游。","风云私所愛，屠博暗爲儔。","解紛曾霸越，釋难頗存周。","晚歲聊长想，生涯太若浮。","归来南畝上，更坐北溪头。","古岸多磐石，春泉足細流。","东隅誠已謝，西景懼难收。","無謂退耕近，伏念已經秋。","庚桑逢处跪，陶潛见人羞。","三晨寧舉火，五月鎮披裘。","自有居常乐，誰知身世憂。"]', '诗', 'shi', '', NULL, '晚年敍志示翟處士 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5ba72fa-ea85-4baa-b84c-fbd823fb2a97', '春日', '春日', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["前旦出園遊，林華都未有。","今朝下堂來，池冰開已久。","雪被南軒梅，風催北庭柳。","遙呼竈前妾，却報機中婦。","年光恰恰來，滿甕營春酒。"]', '["前旦出园游，林华都未有。","今朝下堂来，池冰开已久。","雪被南軒梅，风催北庭柳。","遙呼竈前妾，却報機中婦。","年光恰恰来，满甕營春酒。"]', '诗', 'shi', '', NULL, '春日 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03067213-a3e3-4adc-b5a0-4afdbdb41c54', '採藥', '採藥', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["野情貪藥餌，郊居倦蓬蓽。","青龍護道符，白犬遊仙術。","腰鎌戊己月，負鍤庚辛日。","時時斷嶂遮，往往孤峰出。","行披葛仙經，坐檢神農帙。","龜蛇採二苓，赤白尋雙朮。","地凍根難盡，藂枯苗易失。","從容肉作名，薯蕷高成質。","家豐松葉酒，器貯參花蜜。","且復歸去來，刀圭輔衰疾。"]', '["野情貪藥餌，郊居倦蓬蓽。","青龙護道符，白犬游仙術。","腰鎌戊己月，負鍤庚辛日。","时时斷嶂遮，往往孤峰出。","行披葛仙經，坐檢神農帙。","龟蛇採二苓，赤白尋雙朮。","地凍根难尽，藂枯苗易失。","從容肉作名，薯蕷高成質。","家豐松葉酒，器貯參花蜜。","且复归去来，刀圭輔衰疾。"]', '诗', 'shi', '', NULL, '採藥 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fe0a96a-722c-46fc-89ea-e0c64415d0c6', '在京思故園見鄉人問', '在京思故园见乡人问', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["旅泊多年歲，老去不知迴。","忽逢門前客，道發故鄉來。","斂眉俱握手，破涕共銜杯。","殷勤訪朋舊，屈曲問童孩。","衰宗多弟姪，若箇賞池臺。","舊園今在否，新樹也應栽。","柳行疎密布，茅齋寬窄裁。","經移何處竹？別種幾株梅。","渠當無絕水，石計總生苔。","院果誰先熟，林花那後開。","羇心祗欲問，爲報不須猜。","行當驅下澤，去剪故園萊。"]', '["旅泊多年歲，老去不知迴。","忽逢门前客，道發故乡来。","斂眉俱握手，破涕共銜杯。","殷勤訪朋旧，屈曲问童孩。","衰宗多弟姪，若箇賞池台。","旧园今在否，新樹也應栽。","柳行疎密布，茅斋寬窄裁。","經移何处竹？別種幾株梅。","渠當無絕水，石計總生苔。","院果誰先熟，林花那後开。","羇心祗欲问，爲報不須猜。","行當驱下澤，去剪故园萊。"]', '诗', 'shi', '', NULL, '在京思故園見鄉人問 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63add5cf-ea56-40b1-8a8e-3ddd6c1ab87c', '春桂問荅二首 一', '春桂问荅二首 一', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["問春桂：桃李正芬華，年光隨處滿，何事獨無花。"]', '["问春桂：桃李正芬华，年光隨处满，何事独無花。"]', '诗', 'shi', '', NULL, '春桂問荅二首 一 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a02c16d-2702-42b3-b9eb-e44f1c658b87', '春桂問荅二首 二', '春桂问荅二首 二', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["春桂荅：春華詎能久，風霜搖落時，獨秀君知不。"]', '["春桂荅：春华詎能久，风霜搖落时，独秀君知不。"]', '诗', 'shi', '', NULL, '春桂問荅二首 二 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90982e3f-e8f1-4a18-8e06-bb5d3446c180', '北山', '北山', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["舊知山裏絕氛埃，登高日暮心悠哉。","子平一去何時返？仲叔長遊遂不來。","幽蘭獨夜清琴曲，桂樹凌雲濁酒杯。","槁項同枯木，丹心等死灰。"]', '["旧知山裏絕氛埃，登高日暮心悠哉。","子平一去何时返？仲叔长游遂不来。","幽蘭独夜清琴曲，桂樹凌云濁酒杯。","槁項同枯木，丹心等死灰。"]', '诗', 'shi', '', NULL, '北山 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('597f5187-ba3e-4094-ae34-52884eb01c84', '野望', '野望', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["東皐薄暮望，徙倚欲何依。","樹樹皆秋色，山山唯落暉。","牧人驅犢返，獵馬帶禽歸。","相顧無相識，長歌懷采薇。"]', '["东皐薄暮望，徙倚欲何依。","樹樹皆秋色，山山唯落暉。","牧人驱犢返，獵马带禽归。","相顧無相識，长歌懷采薇。"]', '诗', 'shi', '', NULL, '野望 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08e63631-dccf-4c60-806a-9b3bd39a0822', '贈程處士', '贈程处士', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["百年長擾擾，萬事悉悠悠。","日光隨意落，河水任情流。","禮樂囚姬旦，詩書縛孔丘。","不如高枕枕，時取醉消愁。"]', '["百年长擾擾，万事悉悠悠。","日光隨意落，河水任情流。","禮乐囚姬旦，诗书縛孔丘。","不如高枕枕，时取醉消愁。"]', '诗', 'shi', '', NULL, '贈程處士 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57ef45ef-afdf-4ede-ab7b-865b64a8eb36', '九月九日贈崔使君善爲', '九月九日贈崔使君善爲', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["野人迷節候，端坐隔塵埃。","忽見黃花吐，方知素節回。","映巖千段發，臨浦萬株開。","香氣徒盈把，無人送酒來。"]', '["野人迷節候，端坐隔塵埃。","忽见黄花吐，方知素節回。","映巖千段發，臨浦万株开。","香氣徒盈把，無人送酒来。"]', '诗', 'shi', '', NULL, '九月九日贈崔使君善爲 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4df36d17-eddd-468a-a3c4-9cd3b3b96ecb', '獨坐', '独坐', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["問君樽酒外，獨坐更何須。","有客談名理，無人索地租。","三男婚令族，五女嫁賢夫。","百年隨分了，未羨陟方壺。"]', '["问君樽酒外，独坐更何須。","有客談名理，無人索地租。","三男婚令族，五女嫁賢夫。","百年隨分了，未羨陟方壺。"]', '诗', 'shi', '', NULL, '獨坐 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87073c74-778d-44e7-9a0a-40d9c0cefbad', '遊仙四首 一', '游仙四首 一', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["暫出東陂路，過訪北巖前。","蔡經新學道，王烈舊成仙。","駕鶴來無日，乘龍去幾年。","三山銀作地，八洞玉爲天。","金精飛欲盡，石髓溜應堅。","自悲生世促，無暇待桑田。"]', '["暫出东陂路，過訪北巖前。","蔡經新学道，王烈旧成仙。","駕鹤来無日，乘龙去幾年。","三山銀作地，八洞玉爲天。","金精飞欲尽，石髓溜應堅。","自悲生世促，無暇待桑田。"]', '诗', 'shi', '', NULL, '遊仙四首 一 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fadef9d-25b5-4a8c-9eb6-ddd7da1fc012', '遊仙四首 二', '游仙四首 二', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["上月芝蘭徑，中巖紫翠房。","金壺新練乳，玉釜始煎香。","六局黃公術，三門赤帝方。","吹沙聊作鳥，動石試爲羊。","緱氏還程促，瀛洲會日長。","誰知北巖下，延首詠霓裳。"]', '["上月芝蘭徑，中巖紫翠房。","金壺新練乳，玉釜始煎香。","六局黄公術，三门赤帝方。","吹沙聊作鸟，动石試爲羊。","緱氏還程促，瀛洲會日长。","誰知北巖下，延首詠霓裳。"]', '诗', 'shi', '', NULL, '遊仙四首 二 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e2a91c9-fa75-4ae3-a354-96221ee3d1ce', '遊仙四首 三', '游仙四首 三', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["結衣尋野路，負杖入山門。","道士言無宅，仙人更有村。","斜溪橫桂渚，小徑入桃源。","玉牀塵稍冷，金爐火尚溫。","心疑遊北極，望似陟西崑。","逆愁歸舊里，蕭條訪子孫。"]', '["結衣尋野路，負杖入山门。","道士言無宅，仙人更有村。","斜溪橫桂渚，小徑入桃源。","玉牀塵稍冷，金爐火尚溫。","心疑游北極，望似陟西崑。","逆愁归旧里，蕭條訪子孫。"]', '诗', 'shi', '', NULL, '遊仙四首 三 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21cfae19-abd6-4249-817a-50a9cecb0bc2', '遊仙四首 四', '游仙四首 四', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["真經知那是，仙骨定何爲。","許邁心長切，嵇康命似奇。","桑疎金闕迥，苔重石梁危。","照水然犀角，遊山費虎皮。","鴨桃聞已種，龍竹未經騎。","爲向天仙道，棲遑君詎知。"]', '["真經知那是，仙骨定何爲。","許邁心长切，嵇康命似奇。","桑疎金闕迥，苔重石梁危。","照水然犀角，游山費虎皮。","鴨桃闻已種，龙竹未經騎。","爲向天仙道，棲遑君詎知。"]', '诗', 'shi', '', NULL, '遊仙四首 四 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85e13219-6895-4025-a559-c90285851565', '策杖尋隱士', '策杖尋隐士', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["策杖尋隱士，行行路漸賒。","石梁橫澗斷，土室映山斜。","孝然縱有舍，威輦遂無家。","置酒燒枯葉，披書坐落花。","新垂滋水釣，舊結茂陵罝。","歲歲長如此，方知輕世華。"]', '["策杖尋隐士，行行路漸賒。","石梁橫澗斷，土室映山斜。","孝然縱有舍，威輦遂無家。","置酒燒枯葉，披书坐落花。","新垂滋水釣，旧結茂陵罝。","歲歲长如此，方知轻世华。"]', '诗', 'shi', '', NULL, '策杖尋隱士 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('479cacba-b602-45dc-bcd2-410f781e13e7', '贈學仙者', '贈学仙者', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["採藥層城遠，尋師海路賒。","玉壺橫日月，金闕斷煙霞。","仙人何處在？道士未還家。","誰知彭澤意，更覔步兵那。","春釀煎松葉，秋杯浸菊花。","相逢寧可醉，定不學丹砂。"]', '["採藥層城远，尋師海路賒。","玉壺橫日月，金闕斷煙霞。","仙人何处在？道士未還家。","誰知彭澤意，更覔步兵那。","春釀煎松葉，秋杯浸菊花。","相逢寧可醉，定不学丹砂。"]', '诗', 'shi', '', NULL, '贈學仙者 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b84e99c8-0865-4a1e-829b-e391a3201075', '黃頰山', '黄頰山', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["別有青溪道，斜亙碧巖隈。","崩榛橫古蔓，荒石擁寒苔。","野心長寂寞，山徑本幽迴。","步步攀藤上，朝朝負藥來。","幾看松葉秀，頻值菊花開。","無人堪作伴，歲晚獨悠哉。"]', '["別有青溪道，斜亙碧巖隈。","崩榛橫古蔓，荒石擁寒苔。","野心长寂寞，山徑本幽迴。","步步攀藤上，朝朝負藥来。","幾看松葉秀，頻值菊花开。","無人堪作伴，歲晚独悠哉。"]', '诗', 'shi', '', NULL, '黃頰山 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95ceeb80-774c-471f-b021-e9c444659bee', '建德破後入長安詠秋蓬示辛學士', '建德破後入长安詠秋蓬示辛学士', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["遇坎聊知止，逢風或未歸。","孤根何處斷？輕葉強能飛。"]', '["遇坎聊知止，逢风或未归。","孤根何处斷？轻葉強能飞。"]', '诗', 'shi', '', NULL, '建德破後入長安詠秋蓬示辛學士 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06f7fd5b-bc4e-4676-9dee-6c30993fdc35', '過酒家五首 一', '過酒家五首 一', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["洛陽無大宅，長安乏主人。","黃金銷未盡，祗爲酒家貧。"]', '["洛陽無大宅，长安乏主人。","黄金銷未尽，祗爲酒家貧。"]', '诗', 'shi', '', NULL, '過酒家五首 一 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('433ff654-db7e-4cc0-97e8-5ea94d6ff6a0', '過酒家五首 二', '過酒家五首 二', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["此日長昏飲，非關養性靈。","眼看人盡醉，何忍獨爲醒。"]', '["此日长昏饮，非关養性靈。","眼看人尽醉，何忍独爲醒。"]', '诗', 'shi', '', NULL, '過酒家五首 二 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af74ff82-6382-4346-a173-c2b995fe6a56', '過酒家五首 三', '過酒家五首 三', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["竹葉連糟翠，蒲萄帶麴紅。","相逢不令盡，別後爲誰空。"]', '["竹葉連糟翠，蒲萄带麴紅。","相逢不令尽，別後爲誰空。"]', '诗', 'shi', '', NULL, '過酒家五首 三 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6714140f-8da2-40e7-aeeb-94611a956b9a', '過酒家五首 四', '過酒家五首 四', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["對酒但知飲，逢人莫強牽。","倚鑪便得睡，橫甕足堪眠。"]', '["对酒但知饮，逢人莫強牽。","倚鑪便得睡，橫甕足堪眠。"]', '诗', 'shi', '', NULL, '過酒家五首 四 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8491c2cf-79a3-4709-b6d9-5e186c7bdc45', '過酒家五首 五', '過酒家五首 五', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["有客須教飲，無錢可別沽。","來時長道貰，慙媿酒家胡。"]', '["有客須教饮，無錢可別沽。","来时长道貰，慙媿酒家胡。"]', '诗', 'shi', '', NULL, '過酒家五首 五 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dc5b969-4894-402f-b42a-b54e9af2f8a3', '夜還東溪', '夜還东溪', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["石苔應可踐，叢枝幸易攀。","青溪歸路直，乘月夜歌還。"]', '["石苔應可踐，叢枝幸易攀。","青溪归路直，乘月夜歌還。"]', '诗', 'shi', '', NULL, '夜還東溪 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29921223-ef30-4e53-8a3f-cd195743e9bf', '山中別李處士', '山中別李处士', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["爲向東溪道，人來路漸賒。","山中春酒熟，何處得停家。"]', '["爲向东溪道，人来路漸賒。","山中春酒熟，何处得停家。"]', '诗', 'shi', '', NULL, '山中別李處士 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96b4547f-7fee-486c-a402-06409ec5e9eb', '初春', '初春', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["春來日漸長，醉客喜年光。","稍覺池亭好，偏宜酒甕香。"]', '["春来日漸长，醉客喜年光。","稍覺池亭好，偏宜酒甕香。"]', '诗', 'shi', '', NULL, '初春 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa0e6280-db9d-4188-8dc5-b3d9a9497e84', '醉後', '醉後', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["阮籍醒時少，陶潛醉日多。","百年何足度，乘興且長歌。"]', '["阮籍醒时少，陶潛醉日多。","百年何足度，乘兴且长歌。"]', '诗', 'shi', '', NULL, '醉後 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6dce4e7-eb20-4dd0-8ecd-54a7eff6d5dc', '題酒店壁', '題酒店壁', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["昨夜缾始盡，今朝甕即開。","夢中占夢罷，還向酒家來。"]', '["昨夜缾始尽，今朝甕即开。","梦中占梦罷，還向酒家来。"]', '诗', 'shi', '', NULL, '題酒店壁 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8aefaea-ce55-4d2c-98f1-0187e355231c', '戲題卜鋪壁', '戲題卜鋪壁', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["旦逐劉伶去，宵隨畢卓眠。","不應長賣卜，須得杖頭錢。"]', '["旦逐劉伶去，宵隨畢卓眠。","不應长賣卜，須得杖头錢。"]', '诗', 'shi', '', NULL, '戲題卜鋪壁 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('663f19ee-dcbf-4a1b-8f52-3763b4bdd13a', '嘗春酒', '嘗春酒', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["野觴浮鄭酌，山酒漉陶巾。","但令千日醉，何惜兩三春。"]', '["野觴浮鄭酌，山酒漉陶巾。","但令千日醉，何惜兩三春。"]', '诗', 'shi', '', NULL, '嘗春酒 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('523a39e5-0934-4336-aed8-3b2c7566522c', '獨酌', '独酌', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["浮生知幾日，無狀逐空名。","不知多釀酒，時向竹林傾。"]', '["浮生知幾日，無狀逐空名。","不知多釀酒，时向竹林傾。"]', '诗', 'shi', '', NULL, '獨酌 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ace4d5a4-1992-4f3c-a3d8-6955925fa0f6', '秋夜喜遇王處士', '秋夜喜遇王处士', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["北場芸藿罷，東皐刈黍歸。","相逢秋月滿，更值夜螢飛。"]', '["北場芸藿罷，东皐刈黍归。","相逢秋月满，更值夜螢飞。"]', '诗', 'shi', '', NULL, '秋夜喜遇王處士 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2efca7a-92fe-4205-93b5-65713fd9c0e8', '山夜調琴', '山夜調琴', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["促軫乘明月，抽弦對白雲。","從來山水韻，不使俗人聞。"]', '["促軫乘明月，抽弦对白云。","從来山水韻，不使俗人闻。"]', '诗', 'shi', '', NULL, '山夜調琴 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('957e7785-b62e-4c6d-b0c2-a455e5ff6ab2', '看釀酒', '看釀酒', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["六月調神麴，正朝汲美泉。","從來作春酒，未省不經年。"]', '["六月調神麴，正朝汲美泉。","從来作春酒，未省不經年。"]', '诗', 'shi', '', NULL, '看釀酒 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33b6e6d5-6f25-421f-b47b-b4d880bf2ad1', '食後', '食後', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["田家無所有，晚食遂爲常。","菜剪三秋綠，飧炊百日黃。","胡麻山麨樣，楚豆野麋方。","始暴松皮脯，新添杜若漿。","葛花消酒毒，萸蔕發羹香。","鼓腹聊乘興，寧知逢世昌。"]', '["田家無所有，晚食遂爲常。","菜剪三秋綠，飧炊百日黄。","胡麻山麨樣，楚豆野麋方。","始暴松皮脯，新添杜若漿。","葛花消酒毒，萸蔕發羹香。","鼓腹聊乘兴，寧知逢世昌。"]', '诗', 'shi', '', NULL, '食後 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7462c264-4cfe-4bfc-93e5-39a10307d0dd', '過漢故城', '過漢故城', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["大漢昔未定，強秦猶擅場。","中原逐鹿罷，高祖鬱龍驤。","經始謀帝坐，茲焉壯未央。","規模窮棟宇，表裏浚城隍。","羣后崇長樂，中朝增建章。","鉤陳被蘭錡，樂府奏芝房。","翡翠明珠帳，鴛鴦白玉堂。","清晨寶鼎食，閑夜鬱金香。","天馬來東道，佳人傾北方。","何其赫隆盛，自謂保靈長。","歷數有時盡，哀平嗟不昌。","冰堅成巨猾，火德遂頹綱。","奧位匪虛校，貪天竟速亡。","魂神吁社稷，豺虎鬬巖廊。","金狄移灞岸，銅盤向洛陽。","君王無處所，年代幾荒涼。","宮闕誰家域，蓁蕪罥我裳。","井田唯有草，海水變爲桑。","在昔高門內，於今岐路傍。","餘基不可識，古墓列成行。","狐兔驚魍魎，鴟鴞嚇獝狂。","空城寒日晚，平野暮雲黃。","烈烈焚青棘，蕭蕭吹白楊。","千秋幷萬歲，空使詠歌傷。"]', '["大漢昔未定，強秦猶擅場。","中原逐鹿罷，高祖鬱龙驤。","經始謀帝坐，茲焉壯未央。","規模窮棟宇，表裏浚城隍。","羣后崇长乐，中朝增建章。","鉤陳被蘭錡，乐府奏芝房。","翡翠明珠帳，鴛鴦白玉堂。","清晨寶鼎食，闲夜鬱金香。","天马来东道，佳人傾北方。","何其赫隆盛，自謂保靈长。","歷數有时尽，哀平嗟不昌。","冰堅成巨猾，火德遂頹綱。","奧位匪虛校，貪天竟速亡。","魂神吁社稷，豺虎鬬巖廊。","金狄移灞岸，銅盤向洛陽。","君王無处所，年代幾荒涼。","宮闕誰家域，蓁蕪罥我裳。","井田唯有草，海水变爲桑。","在昔高门內，於今岐路傍。","餘基不可識，古墓列成行。","狐兔驚魍魎，鴟鴞嚇獝狂。","空城寒日晚，平野暮云黄。","烈烈焚青棘，蕭蕭吹白楊。","千秋幷万歲，空使詠歌傷。"]', '诗', 'shi', '', NULL, '過漢故城 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfad4c25-27e0-45bb-8045-e46d92418046', '益州城西張超亭觀妓', '益州城西張超亭观妓', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["落日明歌席，行雲逐舞人。","江南飛暮雨，梁上下輕塵。","冶服看疑畫，粧臺望似春。","高車勿遽返，長袖欲相親。"]', '["落日明歌席，行云逐舞人。","江南飞暮雨，梁上下轻塵。","冶服看疑畫，粧台望似春。","高车勿遽返，长袖欲相親。"]', '诗', 'shi', '', NULL, '益州城西張超亭觀妓 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c842d6e-dc6e-4e5f-b2a4-a913366efed1', '詠妓', '詠妓', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["妖姬飾靚妝，窈窕出蘭房。","日照當軒影，風吹滿路香。","早時歌扇薄，今日舞衫長。","不應令曲誤，持此試周郎。"]', '["妖姬飾靚妝，窈窕出蘭房。","日照當軒影，风吹满路香。","早时歌扇薄，今日舞衫长。","不應令曲誤，持此試周郎。"]', '诗', 'shi', '', NULL, '詠妓 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bb3e42f-c375-417b-b40f-c818807c10ef', '辛司法宅觀妓', '辛司法宅观妓', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["南國佳人至，北堂羅薦開。","長裙隨鳳管，促柱送鸞杯。","雲光身後蕩，雪態掌中回。","到愁金谷晚，不怪玉山頹。"]', '["南国佳人至，北堂羅薦开。","长裙隨鳳管，促柱送鸾杯。","云光身後蕩，雪態掌中回。","到愁金谷晚，不怪玉山頹。"]', '诗', 'shi', '', NULL, '辛司法宅觀妓 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6635317-8c13-4fc9-a144-35a7c126c42c', '詠巫山', '詠巫山', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["電影江前落，雷聲峽外長。","霽雲無處所，臺館曉蒼蒼。"]', '["電影江前落，雷声峽外长。","霽云無处所，台館晓蒼蒼。"]', '诗', 'shi', '', NULL, '詠巫山 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e3f5f37-c25d-4c30-a5bb-d77b405b3aad', '詠懷', '詠懷', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["故鄉行雲是，虛室坐間同。","日落西山暮，方知天下空。"]', '["故乡行云是，虛室坐间同。","日落西山暮，方知天下空。"]', '诗', 'shi', '', NULL, '詠懷 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b02e97b-54ea-43f6-b3d8-abb7b6106c13', '句', '句', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["琴曲唯留古，書多半是經。","橫裁桑節杖，直剪竹皮巾。","鶴警琴亭夜，鶯啼酒甕春。","顏回唯樂道，原憲豈傷貧。","寄身千載下，聊遊萬物初。","欲令無作有，翻覺實成虛。","雙關防易斷，隻眼畏難全。","魚鱗張九拒，鶴翅擁三邊。"]', '["琴曲唯留古，书多半是經。","橫裁桑節杖，直剪竹皮巾。","鹤警琴亭夜，鶯啼酒甕春。","顏回唯乐道，原憲豈傷貧。","寄身千載下，聊游万物初。","欲令無作有，翻覺實成虛。","雙关防易斷，隻眼畏难全。","鱼鱗張九拒，鹤翅擁三邊。"]', '诗', 'shi', '', NULL, '句 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('494648d9-b5b0-44c7-bba2-0c0e4e6c9c36', '詠舞', '詠舞', '7475fe30-9d8a-4ec8-a1ee-b40aeaf60aa3', '唐', '["低身鏘玉珮，舉袖拂羅衣。","對簷疑燕起，映雪似花飛。"]', '["低身鏘玉珮，舉袖拂羅衣。","对簷疑燕起，映雪似花飞。"]', '诗', 'shi', '', NULL, '詠舞 蕭德言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a87be94b-e983-40ff-8350-48a16dbfc585', '過嚴君平古井', '過嚴君平古井', '490de3dd-2114-40b0-ab8b-bc8b444dfa1d', '唐', '["嚴平本高尚，遠蹈古人風。","賣卜成都市，流名大漢中。","舊井改人世，寒泉久不通。","多年既罷汲，無禽乃遂空。","如何屬秋氣，唯見落雙桐。"]', '["嚴平本高尚，远蹈古人风。","賣卜成都市，流名大漢中。","旧井改人世，寒泉久不通。","多年既罷汲，無禽乃遂空。","如何屬秋氣，唯见落雙桐。"]', '诗', 'shi', '', NULL, '過嚴君平古井 鄭世翼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e5d1e50-6035-4034-807c-f51359bd70d7', '登北邙還望京洛', '登北邙還望京洛', '490de3dd-2114-40b0-ab8b-bc8b444dfa1d', '唐', '["步登北邙坂，踟躕聊寫望。","宛洛盛皇居，規模窮大壯。","三河分設險，兩崤資巨防。","飛觀紫煙中，層臺碧雲上。","青槐夾馳道，迢迢修且曠。","左右多第宅，參差居將相。","清晨謁帝返，車馬相追訪。","胥徒各異流，文物紛殊狀。","囂塵暗天起，簫管從風颺。","伊余孤且直，生平獨淪喪。","山幽有桂叢，何爲坐惆悵。"]', '["步登北邙坂，踟躕聊寫望。","宛洛盛皇居，規模窮大壯。","三河分設險，兩崤資巨防。","飞观紫煙中，層台碧云上。","青槐夾驰道，迢迢修且曠。","左右多第宅，參差居將相。","清晨謁帝返，车马相追訪。","胥徒各異流，文物紛殊狀。","囂塵暗天起，簫管從风颺。","伊余孤且直，生平独淪喪。","山幽有桂叢，何爲坐惆悵。"]', '诗', 'shi', '', NULL, '登北邙還望京洛 鄭世翼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dbe2d50-899d-4bcb-a236-6c77004f49a7', '巫山高', '巫山高', '490de3dd-2114-40b0-ab8b-bc8b444dfa1d', '唐', '["巫山凌太清，岧嶤類削成。","霏霏暮雨合，靄靄朝雲生。","危峯入鳥道，深谷寫猨聲。","別有幽棲客，淹留攀桂情。"]', '["巫山凌太清，岧嶤類削成。","霏霏暮雨合，靄靄朝云生。","危峯入鸟道，深谷寫猨声。","別有幽棲客，淹留攀桂情。"]', '诗', 'shi', '', NULL, '巫山高 鄭世翼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a9599e4-7bb3-426f-a570-38b887e247c9', '看新婚', '看新婚', '490de3dd-2114-40b0-ab8b-bc8b444dfa1d', '唐', '["初筓夢桃李，新妝應摽梅。","疑逐朝雲去，翻隨暮雨來。","雜珮含風響，叢花隔扇開。","姮娥對此夕，何用久裴回。"]', '["初筓梦桃李，新妝應摽梅。","疑逐朝云去，翻隨暮雨来。","杂珮含风响，叢花隔扇开。","姮娥对此夕，何用久裴回。"]', '诗', 'shi', '', NULL, '看新婚 鄭世翼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6fc26d8-b28e-4e9d-bbfe-0e425ada0623', '見佳人負錢出路', '见佳人負錢出路', '490de3dd-2114-40b0-ab8b-bc8b444dfa1d', '唐', '["獨負千金價，應從買笑來。","秖持難發口，經爲幾人開。"]', '["独負千金價，應從買笑来。","秖持难發口，經爲幾人开。"]', '诗', 'shi', '', NULL, '見佳人負錢出路 鄭世翼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6ac5aec-9c94-4ded-b87a-4ee99998ac91', '送金竟陵入蜀', '送金竟陵入蜀', '5ae8a2c4-8c5e-4dfa-b9b0-7b95d346cf37', '唐', '["金門去蜀道，玉壘望長安。","豈言千里遠，方尋九折難。","西上君飛葢，東歸我挂冠。","猨聲出峽斷，月彩落江寒。","從今與君別，花月幾新殘。"]', '["金门去蜀道，玉壘望长安。","豈言千里远，方尋九折难。","西上君飞葢，东归我挂冠。","猨声出峽斷，月彩落江寒。","從今與君別，花月幾新殘。"]', '诗', 'shi', '', NULL, '送金竟陵入蜀 崔信明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dc40981-1d73-460e-a7cd-f819bec7761c', '句', '句', '5ae8a2c4-8c5e-4dfa-b9b0-7b95d346cf37', '唐', '["楓落吳江冷。"]', '["楓落吳江冷。"]', '诗', 'shi', '', NULL, '句 崔信明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d70ae348-3a98-4ff2-b91a-574320631372', '侍宴詠石榴', '侍宴詠石榴', '45adcdb6-0424-4e9b-967d-eff16773029f', '唐', '["可惜庭中樹，移根逐漢臣。","只爲來時晚，花開不及春。"]', '["可惜庭中樹，移根逐漢臣。","只爲来时晚，花开不及春。"]', '诗', 'shi', '', NULL, '侍宴詠石榴 孔紹安 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f496ac0-4e6d-4f42-9c57-0ee55664afdb', '詠夭桃', '詠夭桃', '45adcdb6-0424-4e9b-967d-eff16773029f', '唐', '["結葉還臨影，飛香欲徧空。","不意餘花落，翻沈露井中。"]', '["結葉還臨影，飞香欲徧空。","不意餘花落，翻沈露井中。"]', '诗', 'shi', '', NULL, '詠夭桃 孔紹安 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b8e56f2-6005-4d74-b162-210836b049fd', '贈蔡君', '贈蔡君', '45adcdb6-0424-4e9b-967d-eff16773029f', '唐', '["疇昔同幽谷，伊爾遷喬木。","赫奕盛青紫，討論窮簡牘。"]', '["疇昔同幽谷，伊爾遷喬木。","赫奕盛青紫，討論窮簡牘。"]', '诗', 'shi', '', NULL, '贈蔡君 孔紹安 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74a013db-5343-43ec-b371-0dd4a97fffa9', '結客少年場行', '結客少年場行', '45adcdb6-0424-4e9b-967d-eff16773029f', '唐', '["結客佩吳鉤，橫行度隴頭。","鴈在弓前落，雲從陣後浮。","吳師驚燧象，燕將警奔牛。","轉蓬飛不息，冰河結未流。","若使三邊定，當封萬戶侯。"]', '["結客佩吳鉤，橫行度隴头。","鴈在弓前落，云從陣後浮。","吳師驚燧象，燕將警奔牛。","轉蓬飞不息，冰河結未流。","若使三邊定，當封万戶侯。"]', '诗', 'shi', '', NULL, '結客少年場行 孔紹安 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb3da941-ce1c-444d-821d-932325687947', '傷顧學士', '傷顧学士', '45adcdb6-0424-4e9b-967d-eff16773029f', '唐', '["迢遰雙崤道，超忽三川湄。","此中俱失路，思君不可思。","遊人行變橘，逝者遽焚芝。","憶昔江湖上，同詠子衿詩。","何言陵谷徙，翻驚鄰笛悲。","陳根非席卉，穗帳異書帷。","與善成空說，殲良信在茲。","今日嚴夫子，哀命不哀時。"]', '["迢遰雙崤道，超忽三川湄。","此中俱失路，思君不可思。","游人行变橘，逝者遽焚芝。","憶昔江湖上，同詠子衿诗。","何言陵谷徙，翻驚鄰笛悲。","陳根非席卉，穗帳異书帷。","與善成空说，殲良信在茲。","今日嚴夫子，哀命不哀时。"]', '诗', 'shi', '', NULL, '傷顧學士 孔紹安 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6722c6d-f5cc-42ac-9d22-9ad59e34d136', '別徐永元秀才', '別徐永元秀才', '45adcdb6-0424-4e9b-967d-eff16773029f', '唐', '["金湯既失險，玉石乃同焚。","墜葉還相覆，落羽更爲羣。","豈謂三秋節，重傷千里分。","遠離弦易轉，幽咽水難聞。","欲識相思處，山川間白雲。"]', '["金湯既失險，玉石乃同焚。","墜葉還相覆，落羽更爲羣。","豈謂三秋節，重傷千里分。","远離弦易轉，幽咽水难闻。","欲識相思处，山川间白云。"]', '诗', 'shi', '', NULL, '別徐永元秀才 孔紹安 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33f9ccb9-1b90-41cf-9ce3-e9394b68c4a3', '落葉', '落葉', '45adcdb6-0424-4e9b-967d-eff16773029f', '唐', '["早秋驚落葉，飄零似客心。","翻飛未肯下，猶言惜故林。"]', '["早秋驚落葉，飄零似客心。","翻飞未肯下，猶言惜故林。"]', '诗', 'shi', '', NULL, '落葉 孔紹安 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2be5a24-9ff3-44c0-a507-a9bca2a228e0', '踏歌詞三首 一', '踏歌词三首 一', 'faa6b30a-a174-4330-9d64-fae124ad6c88', '唐', '["春景嬌春臺，新露泣新梅。","春葉參差吐，新花重疊開。","花影飛鶯去，歌聲度鳥來。","倩看飄颻雪，何如舞袖迴。"]', '["春景嬌春台，新露泣新梅。","春葉參差吐，新花重叠开。","花影飞鶯去，歌声度鸟来。","倩看飄颻雪，何如舞袖迴。"]', '诗', 'shi', '', NULL, '踏歌詞三首 一 謝偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28a1faca-a893-4602-972d-dd049e8a7bf4', '踏歌詞三首 二', '踏歌词三首 二', 'faa6b30a-a174-4330-9d64-fae124ad6c88', '唐', '["逶迤度香閤，顧步出蘭閨。","欲繞鴛鴦殿，先過桃李蹊。","風帶舒還卷，簪花舉復低。","欲問今宵樂，但聽歌聲齊。"]', '["逶迤度香閤，顧步出蘭閨。","欲繞鴛鴦殿，先過桃李蹊。","风带舒還卷，簪花舉复低。","欲问今宵乐，但听歌声齊。"]', '诗', 'shi', '', NULL, '踏歌詞三首 二 謝偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e64c0c87-3e98-4dc7-bf2e-0c10e294c763', '踏歌詞三首 三', '踏歌词三首 三', 'faa6b30a-a174-4330-9d64-fae124ad6c88', '唐', '["夜久星沈沒，更深月影斜。","裙輕纔動珮，鬟薄不勝花。","細風吹寶袂，輕露濕紅紗。","相看樂未已，蘭燈照九華。"]', '["夜久星沈沒，更深月影斜。","裙轻纔动珮，鬟薄不勝花。","細风吹寶袂，轻露濕紅紗。","相看乐未已，蘭灯照九华。"]', '诗', 'shi', '', NULL, '踏歌詞三首 三 謝偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba2a0966-6561-40d5-af93-d6a74b890222', '樂府新歌應教', '乐府新歌應教', 'faa6b30a-a174-4330-9d64-fae124ad6c88', '唐', '["青樓綺閣已含春，凝妝豔粉復如神。","細細輕裙全漏影，離離薄扇詎障塵。","樽中酒色恆宜滿，曲裏歌聲不厭新。","紫燕欲飛先遶棟，黃鶯始哢即嬌人。","撩亂垂絲昏柳陌，參差濃葉暗桑津。","上客莫畏斜光晚，自有西園明月輪。"]', '["青楼綺閣已含春，凝妝豔粉复如神。","細細轻裙全漏影，離離薄扇詎障塵。","樽中酒色恆宜满，曲裏歌声不厭新。","紫燕欲飞先遶棟，黄鶯始哢即嬌人。","撩亂垂絲昏柳陌，參差濃葉暗桑津。","上客莫畏斜光晚，自有西园明月輪。"]', '诗', 'shi', '', NULL, '樂府新歌應教 謝偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c5ac99b-8c21-4569-ac94-6565b5ed8e82', '奉和出穎至淮應令', '奉和出穎至淮應令', 'ed1e9599-bf7d-45b2-bf21-da85b98a3c7b', '唐', '["久倦川塗曲，忽此望淮圻。","波長泛淼淼，眺迥情依依。","稍覺金烏轉，漸見錦帆稀。","欲知仁化洽，謳歌滿路歸。"]', '["久倦川塗曲，忽此望淮圻。","波长泛淼淼，眺迥情依依。","稍覺金烏轉，漸见錦帆稀。","欲知仁化洽，謳歌满路归。"]', '诗', 'shi', '', NULL, '奉和出穎至淮應令 蔡允恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1712cdd4-1f15-41c6-a291-c99d8560f520', '和衛尉寺柳', '和衛尉寺柳', '566c2a88-9300-431c-b39d-302b00c5b64b', '唐', '["漢將本屯營，遼河有戍城。","大夫曾取姓，先生亦得名。","高枝拂遠鴈，疎影度遙星。","不辭攀折苦，爲入管弦聲。"]', '["漢將本屯營，遼河有戍城。","大夫曾取姓，先生亦得名。","高枝拂远鴈，疎影度遙星。","不辞攀折苦，爲入管弦声。"]', '诗', 'shi', '', NULL, '和衛尉寺柳 杜之松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce66605b-05a1-442f-80b6-82c7534a651b', '荅王無功冬夜載酒鄉館', '荅王無功冬夜載酒乡館', '3dd1f8dc-a616-412a-8f4f-a1a3b96d28f6', '唐', '["頒條忝貴郡，懸榻久相望。","處士同楊鄭，邦君謝李疆。","詎知方擁篲，逢子敬惟桑。","明朝蓬戶側，會自謁任棠。"]', '["頒條忝貴郡，懸榻久相望。","处士同楊鄭，邦君謝李疆。","詎知方擁篲，逢子敬惟桑。","明朝蓬戶側，會自謁任棠。"]', '诗', 'shi', '', NULL, '荅王無功冬夜載酒鄉館 崔善爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('689ae8ea-708d-48fe-b260-d31526030fca', '荅王無功九日', '荅王無功九日', '3dd1f8dc-a616-412a-8f4f-a1a3b96d28f6', '唐', '["秋來菊花氣，深山客重尋。","露葉疑涵玉，風花似散金。","摘來還泛酒，獨坐即徐斟。","王弘貪自醉，無復覓楊林。"]', '["秋来菊花氣，深山客重尋。","露葉疑涵玉，风花似散金。","摘来還泛酒，独坐即徐斟。","王弘貪自醉，無复覓楊林。"]', '诗', 'shi', '', NULL, '荅王無功九日 崔善爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f0ecec7-ab64-4251-8b38-f0be571c48ad', '荅王無功問故園', '荅王無功问故园', 'a5a0000d-231f-48c8-bdc4-5586e2877522', '唐', '["我從銅州來，見子上京客。","問我故鄉事，慰子羈旅色。","子問我所知，我對子應識。","朋遊總強健，童稚各長成。","華宗盛文史，連牆富池亭。","獨子園最古，舊林間新坰。","柳行隨堤勢，茅齋看地形。","竹從去年移，梅是今年榮。","渠水經夏響，石苔終歲青。","院果早晚熟，林花先後明。","語罷相歎息，浩然起深情。","歸哉且五斗，餉子東皐耕。"]', '["我從銅州来，见子上京客。","问我故乡事，慰子羈旅色。","子问我所知，我对子應識。","朋游總強健，童稚各长成。","华宗盛文史，連牆富池亭。","独子园最古，旧林间新坰。","柳行隨堤勢，茅斋看地形。","竹從去年移，梅是今年榮。","渠水經夏响，石苔終歲青。","院果早晚熟，林花先後明。","語罷相歎息，浩然起深情。","归哉且五斗，餉子东皐耕。"]', '诗', 'shi', '', NULL, '荅王無功問故園 朱仲晦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb73f12a-2079-431e-a770-bd1281d5e335', '從軍行', '從軍行', '5857f16b-1269-4af1-be95-72ab6b01bdaa', '唐', '["兒生三日掌上珠，燕頷猨肱穠李膚。","十五學劒北擊胡，羌歌燕筑送城隅。","城隅路接伊川驛，河陽渡頭邯鄲陌。","可憐少年把手時，黃鳥雙飛梨花白。","秦王築城三千里，西自臨洮東遼水。","山邊疊疊黑雲飛，海畔莓莓青草死。","從來戰鬬不求勳，殺身爲君君不聞。","鳳皇樓上吹急管，落日裴回腸先斷。"]', '["兒生三日掌上珠，燕頷猨肱穠李膚。","十五学劒北擊胡，羌歌燕筑送城隅。","城隅路接伊川驛，河陽渡头邯鄲陌。","可怜少年把手时，黄鸟雙飞梨花白。","秦王築城三千里，西自臨洮东遼水。","山邊叠叠黑云飞，海畔莓莓青草死。","從来戰鬬不求勳，殺身爲君君不闻。","鳳皇楼上吹急管，落日裴回腸先斷。"]', '诗', 'shi', '', NULL, '從軍行 王宏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2d0a6f4-112a-440d-bf55-a30627223421', '文德皇后挽歌', '文德皇后挽歌', '3e12d0d8-6ab9-4a80-af41-e39873622c67', '唐', '["神京背紫陌，縞駟結行輈。","北去橫橋道，西分清渭流。","寒光向壟沒，霜氣入松楸。","今日泉臺路，非是濯龍遊。"]', '["神京背紫陌，縞駟結行輈。","北去橫橋道，西分清渭流。","寒光向壟沒，霜氣入松楸。","今日泉台路，非是濯龙游。"]', '诗', 'shi', '', NULL, '文德皇后挽歌 朱子奢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('423e6b74-a70d-4bda-a909-50ad6cae07d9', '大酺樂', '大酺乐', 'b8bae891-dd7b-48f9-aa2d-bc39a0231e4c', '唐', '["淚滴珠難盡，容殘玉易銷。","倘隨明月去，莫道夢魂遙。"]', '["泪滴珠难尽，容殘玉易銷。","倘隨明月去，莫道梦魂遙。"]', '诗', 'shi', '', NULL, '大酺樂 張文收 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('277d3d6f-42e6-4203-b9c4-d0663528e6d6', '與琳法師', '與琳法師', '218c68ba-42e8-4dc8-ad39-df1938677331', '唐', '["冶長倦縲紲，韓安歎死灰。","始驗山中木，方知貴不材。"]', '["冶长倦縲紲，韓安歎死灰。","始驗山中木，方知貴不材。"]', '诗', 'shi', '', NULL, '與琳法師 毛明素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ef0d070-f7ef-4f1c-9fb3-03d6fbbf3327', '上之回', '上之回', 'fec84ee4-afe1-4c0e-a4c8-ea6deafbe1ac', '唐', '["承平重遊樂，詔蹕上之回。","屬車響流水，清笳轉落梅。","嶺雲蓋道轉，巖花映綬開。","下輦便高宴，何如在瑤臺。"]', '["承平重游乐，詔蹕上之回。","屬车响流水，清笳轉落梅。","嶺云蓋道轉，巖花映綬开。","下輦便高宴，何如在瑤台。"]', '诗', 'shi', '', NULL, '上之回 陳子良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d26d70e1-4c7d-4269-90fb-e40ac12cd575', '新成安樂宮', '新成安乐宮', 'fec84ee4-afe1-4c0e-a4c8-ea6deafbe1ac', '唐', '["春色照蘭宮，秦女坐牕中。","柳葉來眉上，桃花落臉紅。","拂塵開扇匣，卷帳却薰籠。","衫薄偏憎日，裙輕更畏風。"]', '["春色照蘭宮，秦女坐牕中。","柳葉来眉上，桃花落臉紅。","拂塵开扇匣，卷帳却薰籠。","衫薄偏憎日，裙轻更畏风。"]', '诗', 'shi', '', NULL, '新成安樂宮 陳子良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('040ef541-1341-4471-a55e-22a60c0eccc6', '夏晚尋于政世置酒賦韻', '夏晚尋于政世置酒賦韻', 'fec84ee4-afe1-4c0e-a4c8-ea6deafbe1ac', '唐', '["聊從嘉遯所，酌醴共抽簪。","以茲山水地，留連風月心。","長榆落照盡，高柳暮蟬吟。","一返桃源路，別後難追尋。"]', '["聊從嘉遯所，酌醴共抽簪。","以茲山水地，留連风月心。","长榆落照尽，高柳暮蟬吟。","一返桃源路，別後难追尋。"]', '诗', 'shi', '', NULL, '夏晚尋于政世置酒賦韻 陳子良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('803c0af2-e196-41c0-aea7-2e8f6eb9b4ca', '入蜀秋夜宿江渚', '入蜀秋夜宿江渚', 'fec84ee4-afe1-4c0e-a4c8-ea6deafbe1ac', '唐', '["我行逢日暮，弭櫂獨維舟。","水霧一邊起，風林兩岸秋。","山陰黑斷磧，月影素寒流。","故鄉千里外，何以慰羈愁。"]', '["我行逢日暮，弭櫂独維舟。","水霧一邊起，风林兩岸秋。","山陰黑斷磧，月影素寒流。","故乡千里外，何以慰羈愁。"]', '诗', 'shi', '', NULL, '入蜀秋夜宿江渚 陳子良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35417355-7ddf-41c3-a3ec-0bbbb197664f', '賦得妓', '賦得妓', 'fec84ee4-afe1-4c0e-a4c8-ea6deafbe1ac', '唐', '["金谷多歡宴，佳麗正芳菲。","流霞席上滿，回雪掌中飛。","明月臨歌扇，行雲接舞衣。","何必桃將李，別有待春暉。"]', '["金谷多歡宴，佳丽正芳菲。","流霞席上满，回雪掌中飞。","明月臨歌扇，行云接舞衣。","何必桃將李，別有待春暉。"]', '诗', 'shi', '', NULL, '賦得妓 陳子良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1886abf2-2150-4e6a-97e2-cadac52961b3', '詶蕭侍中春園聽妓', '詶蕭侍中春园听妓', 'fec84ee4-afe1-4c0e-a4c8-ea6deafbe1ac', '唐', '["微雨散芳菲，中園照落暉。","紅樹搖歌扇，綠珠飄舞衣。","繁弦調對酒，雜引動思歸。","愁人當此夕，羞見落花飛。"]', '["微雨散芳菲，中园照落暉。","紅樹搖歌扇，綠珠飄舞衣。","繁弦調对酒，杂引动思归。","愁人當此夕，羞见落花飞。"]', '诗', 'shi', '', NULL, '詶蕭侍中春園聽妓 陳子良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0ef48e1-e418-47d8-9cda-09cc906bdf54', '遊俠篇', '游俠篇', 'fec84ee4-afe1-4c0e-a4c8-ea6deafbe1ac', '唐', '["洛陽麗春色，遊俠騁輕肥。","水逐車輪轉，塵隨馬足飛。","雲影遙臨蓋，花氣近薰衣。","東郊鬬雞罷，南皮射雉歸。","日暮河橋上，揚鞭惜晚暉。"]', '["洛陽丽春色，游俠騁轻肥。","水逐车輪轉，塵隨马足飞。","云影遙臨蓋，花氣近薰衣。","东郊鬬雞罷，南皮射雉归。","日暮河橋上，揚鞭惜晚暉。"]', '诗', 'shi', '', NULL, '遊俠篇 陳子良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cb29f78-fb3f-4cb2-b2a5-764cfac93e72', '春晚看羣公朝還人爲八韻', '春晚看羣公朝還人爲八韻', 'fec84ee4-afe1-4c0e-a4c8-ea6deafbe1ac', '唐', '["遊子惜春暮，策杖出蒿萊。","正直康莊晚，羣公謁帝迴。","履度南宮至，車從北闕來。","珂影傍明月，笳聲動落梅。","迎風采旄轉，照日綬花開。","紅塵掩鶴蓋，翠柳拂龍媒。","綺雲臨舞閣，丹霞薄吹臺。","輕肥寧所羨，未若反山隈。"]', '["游子惜春暮，策杖出蒿萊。","正直康莊晚，羣公謁帝迴。","履度南宮至，车從北闕来。","珂影傍明月，笳声动落梅。","迎风采旄轉，照日綬花开。","紅塵掩鹤蓋，翠柳拂龙媒。","綺云臨舞閣，丹霞薄吹台。","轻肥寧所羨，未若反山隈。"]', '诗', 'shi', '', NULL, '春晚看羣公朝還人爲八韻 陳子良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e9d0cbe-2a72-4395-babc-4fbeb5707d2d', '讚德上越國公楊素', '讚德上越国公楊素', 'fec84ee4-afe1-4c0e-a4c8-ea6deafbe1ac', '唐', '["君侯稱上宰，命世挺才英。","本超騏驥足，復蘊風雲情。","攄藻掞錦綺，育德潤瑤瓊。","已踵四知舉，非無三傑名。","濟世同舟檝，匡政本阿衡。","雍容入青鎖，肅穆侍丹楹。","桂宮擅鳴珮，槐路獨飛纓。","高門羅虎戟，綺閣麗彫甍。","金罇酌湛湛，歌扇掩盈盈。","匈奴軼燕薊，烽火照幽幷。","天子名薄伐，受脤事專征。","七德播雄略，十萬騁行兵。","鴈行蔽虜甸，魚貫出長城。","交河方飲馬，瀚海盛揚旌。","拔劒倚天外，蒙犀輝日精。","彎弧穿伏石，揮戈斬大鯨。","鼓鼙朝作氣，刁斗夜偏鳴。","六郡多壯士，三邊豈足平。","嶺雲朝合陣，山月夜臨營。","胡塵暗馬色，芳樹動笳聲。","關雲未盡散，塞霧常自生。","川長蔓草綠，峯逈雜花明。","小人愧王氏，雕文慙馬卿。","濫此叨書記，何以謝過榮。","高山徒仰止，終是恨才輕。"]', '["君侯稱上宰，命世挺才英。","本超騏驥足，复蘊风云情。","攄藻掞錦綺，育德潤瑤瓊。","已踵四知舉，非無三傑名。","濟世同舟檝，匡政本阿衡。","雍容入青鎖，肅穆侍丹楹。","桂宮擅鳴珮，槐路独飞纓。","高门羅虎戟，綺閣丽彫甍。","金罇酌湛湛，歌扇掩盈盈。","匈奴軼燕薊，烽火照幽幷。","天子名薄伐，受脤事專征。","七德播雄略，十万騁行兵。","鴈行蔽虜甸，鱼貫出长城。","交河方饮马，瀚海盛揚旌。","拔劒倚天外，蒙犀輝日精。","彎弧穿伏石，揮戈斬大鯨。","鼓鼙朝作氣，刁斗夜偏鳴。","六郡多壯士，三邊豈足平。","嶺云朝合陣，山月夜臨營。","胡塵暗马色，芳樹动笳声。","关云未尽散，塞霧常自生。","川长蔓草綠，峯逈杂花明。","小人愧王氏，雕文慙马卿。","濫此叨书記，何以謝過榮。","高山徒仰止，終是恨才轻。"]', '诗', 'shi', '', NULL, '讚德上越國公楊素 陳子良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bd38801-104e-46a4-ad08-16c68a0cf091', '於塞北春日思歸', '於塞北春日思归', 'fec84ee4-afe1-4c0e-a4c8-ea6deafbe1ac', '唐', '["我家吳會青山遠，他鄉關塞白雲深。","爲許羈愁長下淚，那堪春色更傷心。","驚鳥屢飛恆失侶，落花一去不歸林。","如何此日嗟遲暮，悲來還作白頭吟。"]', '["我家吳會青山远，他乡关塞白云深。","爲許羈愁长下泪，那堪春色更傷心。","驚鸟屢飞恆失侶，落花一去不归林。","如何此日嗟遲暮，悲来還作白头吟。"]', '诗', 'shi', '', NULL, '於塞北春日思歸 陳子良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6afd4887-a00f-4b5f-95cf-434c3c3ca46c', '送別', '送別', 'fec84ee4-afe1-4c0e-a4c8-ea6deafbe1ac', '唐', '["落葉聚還散，征禽去不歸。","以我窮途泣，沾君出塞衣。"]', '["落葉聚還散，征禽去不归。","以我窮途泣，沾君出塞衣。"]', '诗', 'shi', '', NULL, '送別 陳子良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8c73b57-fd84-4fb9-94ef-68dcfe360df0', '七夕看新婦隔巷停車', '七夕看新婦隔巷停车', 'fec84ee4-afe1-4c0e-a4c8-ea6deafbe1ac', '唐', '["隔巷遙停幰，非復爲來遲。","只言更尚淺，未是渡河時。"]', '["隔巷遙停幰，非复爲来遲。","只言更尚淺，未是渡河时。"]', '诗', 'shi', '', NULL, '七夕看新婦隔巷停車 陳子良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b3297b7-407a-442b-a37a-914c5908e660', '詠春雪', '詠春雪', 'fec84ee4-afe1-4c0e-a4c8-ea6deafbe1ac', '唐', '["光映妝樓月，花承歌扇風。","欲妬梅將柳，故落早春中。"]', '["光映妝楼月，花承歌扇风。","欲妬梅將柳，故落早春中。"]', '诗', 'shi', '', NULL, '詠春雪 陳子良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f89b9007-3906-4a9e-9234-de9c776109c8', '驄馬', '驄马', 'f9ee3838-9bd4-4c5f-bd2f-159a308241af', '唐', '["櫪上浮雲驄，本出吳門中。","發跡來東道，長鳴起北風。","迴鞍拂桂白，赬汗類塵紅。","滅沒徒留影，無因圖漢宮。"]', '["櫪上浮云驄，本出吳门中。","發跡来东道，长鳴起北风。","迴鞍拂桂白，赬汗類塵紅。","滅沒徒留影，無因圖漢宮。"]', '诗', 'shi', '', NULL, '驄馬 庾抱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7e25710-4c42-4dce-80a3-844e779e0896', '別蔡參軍', '別蔡參軍', 'f9ee3838-9bd4-4c5f-bd2f-159a308241af', '唐', '["人世多飄忽，溝水易西東。","今日歡娛盡，何年風月同？","悲生萬里外，恨起一杯中。","性靈如未失，南北有征鴻。"]', '["人世多飄忽，溝水易西东。","今日歡娛尽，何年风月同？","悲生万里外，恨起一杯中。","性靈如未失，南北有征鴻。"]', '诗', 'shi', '', NULL, '別蔡參軍 庾抱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e502c1ae-0ea2-403e-9d0c-d533aa2a5cb2', '賦得胥臺露', '賦得胥台露', 'f9ee3838-9bd4-4c5f-bd2f-159a308241af', '唐', '["胥臺既落構，荆棘稍侵扉。","棟拆連雲影，梁摧照日暉。","翔鶤逐不及，巢燕[反]無歸。","唯有團階露，承曉共沾衣。"]', '["胥台既落構，荆棘稍侵扉。","棟拆連云影，梁摧照日暉。","翔鶤逐不及，巢燕[反]無归。","唯有團階露，承晓共沾衣。"]', '诗', 'shi', '', NULL, '賦得胥臺露 庾抱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baa4e7e2-9ba0-478e-8d84-79bdc508b477', '臥痾喜霽開扉望月簡宮內知友', '臥痾喜霽开扉望月簡宮內知友', 'f9ee3838-9bd4-4c5f-bd2f-159a308241af', '唐', '["秋雨移弦望，疲痾倦苦辛。","忽對荆山璧，委照越吟人。","高高侵地鏡，皎皎徹天津。","色麗班姬篋，光潤洛川神。","輪輝池上動，桂影隙中新。","懷賢雖不見，忽似暫參辰。"]', '["秋雨移弦望，疲痾倦苦辛。","忽对荆山璧，委照越吟人。","高高侵地镜，皎皎徹天津。","色丽班姬篋，光潤洛川神。","輪輝池上动，桂影隙中新。","懷賢雖不见，忽似暫參辰。"]', '诗', 'shi', '', NULL, '臥痾喜霽開扉望月簡宮內知友 庾抱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eae56b9d-994b-4231-bc31-a9e7bf761a37', '和樂記室憶江水', '和乐記室憶江水', 'f9ee3838-9bd4-4c5f-bd2f-159a308241af', '唐', '["遙想觀濤處，猶意採蓮歌。","無因關塞葉，共下洞庭波。"]', '["遙想观濤处，猶意採蓮歌。","無因关塞葉，共下洞庭波。"]', '诗', 'shi', '', NULL, '和樂記室憶江水 庾抱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45610463-fdcb-4e71-ab2d-e20dd596351d', '凌朝浮江旅思', '凌朝浮江旅思', '7ccfb085-08db-4bf9-b5d3-f2ad10c0dcf3', '唐', '["太清上初日，春水送孤舟。","山遠疑無樹，潮平似不流。","岸花開且落，江鳥沒還浮。","羈望傷千里，長歌遣四愁。"]', '["太清上初日，春水送孤舟。","山远疑無樹，潮平似不流。","岸花开且落，江鸟沒還浮。","羈望傷千里，长歌遣四愁。"]', '诗', 'shi', '', NULL, '凌朝浮江旅思 馬周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f784e66e-81e1-4c69-a1f1-2d820aa49744', '句', '句', '7ccfb085-08db-4bf9-b5d3-f2ad10c0dcf3', '唐', '["何惜鄧林樹，不借一枝棲。"]', '["何惜鄧林樹，不借一枝棲。"]', '诗', 'shi', '', NULL, '句 馬周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b908117-31ca-49d2-a26c-5f506cc2918e', '出玉關', '出玉关', '366daf86-bafe-4462-a22a-1dac45411220', '唐', '["歛轡遵龍漢，銜悽渡玉關。","今日流沙外，垂涕念生還。"]', '["歛轡遵龙漢，銜悽渡玉关。","今日流沙外，垂涕念生還。"]', '诗', 'shi', '', NULL, '出玉關 來濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af84c796-64c8-4c7c-9e57-ef9340202749', '七夕', '七夕', 'd2a9ce9c-e5a0-48d3-ae96-3a02fb44e1c5', '唐', '["鳳律驚秋氣，龍梭靜夜機。","星橋百枝動，雲路七香飛。","映月迴雕扇，凌霞曳綺衣。","含情向華幄，流態入重闈。","歡餘夕漏盡，怨結曉驂歸。","誰念分河漢，還憶兩心違。"]', '["鳳律驚秋氣，龙梭静夜機。","星橋百枝动，云路七香飞。","映月迴雕扇，凌霞曳綺衣。","含情向华幄，流態入重闈。","歡餘夕漏尽，怨結晓驂归。","誰念分河漢，還憶兩心違。"]', '诗', 'shi', '', NULL, '七夕 張文恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ffa6826-9a72-4b19-a6ab-07063bf69b0e', '佳人照鏡', '佳人照镜', 'd2a9ce9c-e5a0-48d3-ae96-3a02fb44e1c5', '唐', '["倦采蘼蕪葉，貪憐照膽明。","兩邊俱拭淚，一處有啼聲。"]', '["倦采蘼蕪葉，貪怜照膽明。","兩邊俱拭泪，一处有啼声。"]', '诗', 'shi', '', NULL, '佳人照鏡 張文恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d449fe2f-b14b-4439-a787-4f48f819517e', '奉和同太子監守違戀', '奉和同太子監守違戀', 'efbf18f9-0e1e-4ef1-86d8-c947ae853919', '唐', '["儲禁銅扉啓，宸行玉軑遙。","空懷壽街吏，尚隔寢門朝。","北首瞻龍戟，塵外想鸞鑣。","飛文映仙榜，瀝思叶神飆。","帝念紆蒼璧，乾文煥紫霄。","歸塘橫筆海，平圃振詞條。","欲應重輪曲，鏘洋韻九韶。"]', '["儲禁銅扉啓，宸行玉軑遙。","空懷壽街吏，尚隔寢门朝。","北首瞻龙戟，塵外想鸾鑣。","飞文映仙榜，瀝思叶神飆。","帝念紆蒼璧，乾文煥紫霄。","归塘橫笔海，平圃振词條。","欲應重輪曲，鏘洋韻九韶。"]', '诗', 'shi', '', NULL, '奉和同太子監守違戀 薛元超 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4198e31-5fe9-42f1-94a6-42fdfa352ca1', '荅辨才探得招字', '荅辨才探得招字', '51f3758c-8031-4cec-9eb5-430cc4fb59a6', '唐', '["邂逅欵良宵，殷勤荷勝招。","彌天俄若舊，初地豈成遙。","酒蟻傾還泛，心猨躁似調。","誰憐失羣鴈，長苦業風飄。"]', '["邂逅欵良宵，殷勤荷勝招。","彌天俄若旧，初地豈成遙。","酒蟻傾還泛，心猨躁似調。","誰怜失羣鴈，长苦業风飄。"]', '诗', 'shi', '', NULL, '荅辨才探得招字 蕭翼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7da8b393-f6b9-4fa0-9fcf-f062e1960fb8', '道失', '道失', '34606369-a7ad-400f-aefc-c6b12375ac82', '唐', '["已惑孔貴嬪，又被辭人侮。","花牋一何榮，七字誰曾許。","不下結綺閣，空迷江令語。","琱戈動地來，悞殺陳後主。"]', '["已惑孔貴嬪，又被辞人侮。","花牋一何榮，七字誰曾許。","不下結綺閣，空迷江令語。","琱戈动地来，悞殺陳後主。"]', '诗', 'shi', '', NULL, '道失 歐陽詢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10c85f05-ed25-4824-8c9e-e01e587d7466', '巫山高', '巫山高', 'ffeeafb6-3f13-45a5-aede-6d16c92cfe45', '唐', '["君不見巫山高高半天起，絕壁千尋盡相似。","君不見巫山磕匝翠屏開，湘江碧水遶山來。","綠樹春嬌明月峽，紅花朝覆白雲臺。","臺上朝雲無定所，此中窕窈神仙女。","仙女盈盈仙骨飛，清容出沒有光輝。","欲暮高唐行雨送，今宵定入荆王夢。","荆王夢里愛穠華，枕席初開紅帳遮。","可憐欲曉啼猨處，說道巫山是妾家。"]', '["君不见巫山高高半天起，絕壁千尋尽相似。","君不见巫山磕匝翠屏开，湘江碧水遶山来。","綠樹春嬌明月峽，紅花朝覆白云台。","台上朝云無定所，此中窕窈神仙女。","仙女盈盈仙骨飞，清容出沒有光輝。","欲暮高唐行雨送，今宵定入荆王梦。","荆王梦里愛穠华，枕席初开紅帳遮。","可怜欲晓啼猨处，说道巫山是妾家。"]', '诗', 'shi', '', NULL, '巫山高 閻立本 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da7ba66c-93a2-4b7b-8eed-e6d95efae807', '同潘屯田冬日早朝', '同潘屯田冬日早朝', '49ac4a83-cdcf-498b-9963-7c60457963b0', '唐', '["假寐懷古人，夙興瞻曉月。","通晨禁門啓，冠蓋趨朝謁。","霜靄清九衢，霞光照雙闕。","紛綸文物紀，煥爛聲明發。","腰劒動陸離，鳴玉和清越。"]', '["假寐懷古人，夙兴瞻晓月。","通晨禁门啓，冠蓋趨朝謁。","霜靄清九衢，霞光照雙闕。","紛綸文物紀，煥爛声明發。","腰劒动陸離，鳴玉和清越。"]', '诗', 'shi', '', NULL, '同潘屯田冬日早朝 張文琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b780554-3dbe-4dd4-b917-842da9fd972a', '蜀道難', '蜀道难', '49ac4a83-cdcf-498b-9963-7c60457963b0', '唐', '["梁山鎮地險，積石阻雲端。","深谷下寥廓，層巖上鬱盤。","飛梁駕絕嶺，棧道接危巒。","攬轡獨長息，方知斯路難。"]', '["梁山鎮地險，積石阻云端。","深谷下寥廓，層巖上鬱盤。","飞梁駕絕嶺，棧道接危巒。","攬轡独长息，方知斯路难。"]', '诗', 'shi', '', NULL, '蜀道難 張文琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b87c3027-1311-485f-bcf6-a00424ee55ba', '昭君怨', '昭君怨', '49ac4a83-cdcf-498b-9963-7c60457963b0', '唐', '["戒途飛萬里，迴首望三秦。","忽見天山雪，還疑上苑春。","玉痕垂粉淚，羅袂拂胡塵。","爲得胡中曲，還悲遠嫁人。"]', '["戒途飞万里，迴首望三秦。","忽见天山雪，還疑上苑春。","玉痕垂粉泪，羅袂拂胡塵。","爲得胡中曲，還悲远嫁人。"]', '诗', 'shi', '', NULL, '昭君怨 張文琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bde8f84-73f7-41ab-ab1f-dd501a4bdf86', '詠水', '詠水', '49ac4a83-cdcf-498b-9963-7c60457963b0', '唐', '["標名資上善，流派表靈長。","地圖羅四瀆，天文載五潢。","方流涵玉潤，圓折動珠光。","獨有蒙園吏，棲偃翫濠梁。"]', '["標名資上善，流派表靈长。","地圖羅四瀆，天文載五潢。","方流涵玉潤，圓折动珠光。","独有蒙园吏，棲偃翫濠梁。"]', '诗', 'shi', '', NULL, '詠水 張文琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84284fb0-a075-46c2-8579-0006c50a6685', '賦橋', '賦橋', '49ac4a83-cdcf-498b-9963-7c60457963b0', '唐', '["造舟浮渭日，鞭石表秦初。","星文遙寫漢，虹勢尚凌虛。","已授文成履，空題武騎書。","別有臨濠上，棲偃獨觀魚。"]', '["造舟浮渭日，鞭石表秦初。","星文遙寫漢，虹勢尚凌虛。","已授文成履，空題武騎书。","別有臨濠上，棲偃独观鱼。"]', '诗', 'shi', '', NULL, '賦橋 張文琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c70263d8-fbda-4e30-8a47-99d2f997e1f0', '和楊舍人詠中書省花樹', '和楊舍人詠中书省花樹', '49ac4a83-cdcf-498b-9963-7c60457963b0', '唐', '["花萼映芳叢，參差間早紅。","因風時落砌，雜雨乍浮空。","影照鳳池水，香飄雞樹風。","豈不愛攀折，希君懷袖中。"]', '["花萼映芳叢，參差间早紅。","因风时落砌，杂雨乍浮空。","影照鳳池水，香飄雞樹风。","豈不愛攀折，希君懷袖中。"]', '诗', 'shi', '', NULL, '和楊舍人詠中書省花樹 張文琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f889634b-508b-4a3a-9557-b64733de3b45', '奉和過舊宅應制', '奉和過旧宅應制', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["石關清晚夏，璇輿御早秋。","神麾颺珠雨，仙吹響飛流。","沛水祥雲泛，宛郊瑞氣浮。","大風迎漢筑，藂煙入舜球。","翠梧臨鳳邸，滋蘭帶鶴舟。","偃伯歌玄化，扈蹕頌王遊。","遺簪謬昭獎，珥筆荷恩休。"]', '["石关清晚夏，璇輿御早秋。","神麾颺珠雨，仙吹响飞流。","沛水祥云泛，宛郊瑞氣浮。","大风迎漢筑，藂煙入舜球。","翠梧臨鳳邸，滋蘭带鹤舟。","偃伯歌玄化，扈蹕頌王游。","遺簪謬昭獎，珥笔荷恩休。"]', '诗', 'shi', '', NULL, '奉和過舊宅應制 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27000328-2a05-45c4-af69-5c8b6b6e772d', '早春桂林殿應詔', '早春桂林殿應詔', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["步輦出披香，清歌臨太液。","曉樹流鶯滿，春堤芳草積。","風光翻露文，雪華上空碧。","花蝶來未已，山光曖將夕。"]', '["步輦出披香，清歌臨太液。","晓樹流鶯满，春堤芳草積。","风光翻露文，雪华上空碧。","花蝶来未已，山光曖將夕。"]', '诗', 'shi', '', NULL, '早春桂林殿應詔 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2f9387b-e35f-4d47-a92c-800c893356b6', '安德山池宴集', '安德山池宴集', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["上路抵平津，後堂羅薦陳。","締交開狎賞，麗席展芳辰。","密樹風煙積，迴塘荷芰新。","雨霽虹橋晚，花落鳳臺春。","翠釵低舞席，文杏散歌塵。","方惜流觴滿，夕鳥已城闉。"]', '["上路抵平津，後堂羅薦陳。","締交开狎賞，丽席展芳辰。","密樹风煙積，迴塘荷芰新。","雨霽虹橋晚，花落鳳台春。","翠釵低舞席，文杏散歌塵。","方惜流觴满，夕鸟已城闉。"]', '诗', 'shi', '', NULL, '安德山池宴集 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0561ee4c-2906-48e7-8b10-59c5f3119352', '酬薛舍人萬年宮晚景寓直懷友', '酬薛舍人万年宮晚景寓直懷友', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["奕奕九成臺，窈窕絕塵埃。","蒼蒼萬年樹，玲瓏下冥霧。","池色搖晚空，巖花歛餘煦。","清切丹禁靜，浩蕩文河注。","留連窮勝託，夙期暌善謔。","東望安仁省，西臨子雲閣。","長嘯披煙霞，高步尋蘭若。","金狄掩通門，雕鞍歸騎喧。","燕姝對明月，荆豔促芳尊。","別有青山路，策杖訪王孫。"]', '["奕奕九成台，窈窕絕塵埃。","蒼蒼万年樹，玲瓏下冥霧。","池色搖晚空，巖花歛餘煦。","清切丹禁静，浩蕩文河注。","留連窮勝託，夙期暌善謔。","东望安仁省，西臨子云閣。","长嘯披煙霞，高步尋蘭若。","金狄掩通门，雕鞍归騎喧。","燕姝对明月，荆豔促芳尊。","別有青山路，策杖訪王孫。"]', '诗', 'shi', '', NULL, '酬薛舍人萬年宮晚景寓直懷友 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9afab914-ceee-4ea1-b1e7-7a8b3494a5e5', '奉和潁川公秋夜', '奉和潁川公秋夜', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["泬寥空色遠，芸黃淒序變。","涸浦落遵鴻，長飆送巢燕。","千秋流夕景，萬籟含宵喚。","峻雉聆金柝，層臺切銀箭。"]', '["泬寥空色远，芸黄淒序变。","涸浦落遵鴻，长飆送巢燕。","千秋流夕景，万籟含宵喚。","峻雉聆金柝，層台切銀箭。"]', '诗', 'shi', '', NULL, '奉和潁川公秋夜 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('133342dd-08d3-4a83-8106-773f3575ea97', '謝都督挽歌', '謝都督挽歌', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["漠漠佳城幽，蒼蒼松檟暮。","魯幕飄欲卷，宛駟悲還顧。","楚挽繞盧山，胡笳臨武庫。","悵然郊原靜，煙生歸鳥度。"]', '["漠漠佳城幽，蒼蒼松檟暮。","魯幕飄欲卷，宛駟悲還顧。","楚挽繞盧山，胡笳臨武庫。","悵然郊原静，煙生归鸟度。"]', '诗', 'shi', '', NULL, '謝都督挽歌 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc66a919-0677-42c4-b8ad-c198e2e5d1f0', '八詠應制二首 一', '八詠應制二首 一', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["啓重帷，重帷照文杏。","翡翠藻輕花，流蘇媚浮影。","瑤笙燕始歸，金堂露初晞。","風隨少女至，虹共美人歸。","羅薦已擘鴛鴦被，綺衣復有蒲萄帶。","殘紅豔粉映簾中，戲蝶流鶯聚窗外。","洛濱春雪迴，巫峽暮雲來。","雪花飄玉輦，雲光上璧臺。","共待新妝出，清歌送落梅。"]', '["啓重帷，重帷照文杏。","翡翠藻轻花，流蘇媚浮影。","瑤笙燕始归，金堂露初晞。","风隨少女至，虹共美人归。","羅薦已擘鴛鴦被，綺衣复有蒲萄带。","殘紅豔粉映簾中，戲蝶流鶯聚窗外。","洛濱春雪迴，巫峽暮云来。","雪花飄玉輦，云光上璧台。","共待新妝出，清歌送落梅。"]', '诗', 'shi', '', NULL, '八詠應制二首 一 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0895a41-61f7-4cb9-bcff-f70474730891', '八詠應制二首 二', '八詠應制二首 二', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["入叢臺，叢臺裛春露。","滴瀝間深紅，參差散輕素。","妝蝶驚復聚，黃鸝飛且顧。","攀折殊未已，復值驚飛起。","送影舞衫前，飄香歌扇裏。","望望惜春暉，行行猶未歸。","暫得佳遊趣，更愁花鳥稀。","且學鳥聲調鳳管，方移花影入鴛機。"]', '["入叢台，叢台裛春露。","滴瀝间深紅，參差散轻素。","妝蝶驚复聚，黄鸝飞且顧。","攀折殊未已，复值驚飞起。","送影舞衫前，飄香歌扇裏。","望望惜春暉，行行猶未归。","暫得佳游趣，更愁花鸟稀。","且学鸟声調鳳管，方移花影入鴛機。"]', '诗', 'shi', '', NULL, '八詠應制二首 二 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54af578d-9ecd-4ac2-a051-5c0d15bdc63c', '和太尉戲贈高陽公', '和太尉戲贈高陽公', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["薰爐御史出神仙，雲鞍羽蓋下芝田。","紅塵正起浮橋路，青樓遙敞御溝前。","傾城比態芳菲節，絕世相嬌是六年。","慣是洛濱要解珮，本是河間好數錢。","翠釵照耀銜雲髮，玉步逶迤動羅袜。","石榴絞帶輕花轉，桃枝綠扇微風發。","無情拂袂欲留賓，詎恨深潭不可越。","天津一別九秋長，豈若隨聞三日香。","南國自然勝掌上，東家復是憶王昌。"]', '["薰爐御史出神仙，云鞍羽蓋下芝田。","紅塵正起浮橋路，青楼遙敞御溝前。","傾城比態芳菲節，絕世相嬌是六年。","慣是洛濱要解珮，本是河间好數錢。","翠釵照耀銜云髮，玉步逶迤动羅袜。","石榴絞带轻花轉，桃枝綠扇微风發。","無情拂袂欲留賓，詎恨深潭不可越。","天津一別九秋长，豈若隨闻三日香。","南国自然勝掌上，东家复是憶王昌。"]', '诗', 'shi', '', NULL, '和太尉戲贈高陽公 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98981c31-6093-4d92-8849-3380d2b64042', '王昭君', '王昭君', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["玉關春色晚，金河路幾千。","琴悲桂條上，笛怨柳花前。","霧掩臨妝月，風驚入鬢蟬。","緘書待還使，淚盡白雲天。"]', '["玉关春色晚，金河路幾千。","琴悲桂條上，笛怨柳花前。","霧掩臨妝月，风驚入鬢蟬。","緘书待還使，泪尽白云天。"]', '诗', 'shi', '', NULL, '王昭君 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f435f9a4-27c8-4847-9768-608abd737b4d', '詠雪應詔', '詠雪應詔', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["禁園凝朔氣，瑞雪掩晨曦。","花明棲鳳閣，珠散影娥池。","飄素迎歌上，翻光向舞移。","幸因千里映，還繞萬年枝。"]', '["禁园凝朔氣，瑞雪掩晨曦。","花明棲鳳閣，珠散影娥池。","飄素迎歌上，翻光向舞移。","幸因千里映，還繞万年枝。"]', '诗', 'shi', '', NULL, '詠雪應詔 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c789be77-2ccc-4842-801a-e23e86da659c', '奉和山夜臨秋', '奉和山夜臨秋', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["殿帳清炎氣，輦道含秋陰。","淒風移漢筑，流水入虞琴。","雲飛送斷雁，月上淨疎林。","滴瀝露枝響，空蒙煙壑深。"]', '["殿帳清炎氣，輦道含秋陰。","淒风移漢筑，流水入虞琴。","云飞送斷雁，月上淨疎林。","滴瀝露枝响，空蒙煙壑深。"]', '诗', 'shi', '', NULL, '奉和山夜臨秋 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('321efb3d-00fd-48cb-bb50-ec9ca0872662', '江王太妃挽歌', '江王太妃挽歌', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["黃鶴悲歌絕，椒花清頌餘。","埃凝寫鄰鏡，網結和扉魚。","銀消風燭盡，珠滅夜輪虛。","別有南陵路，幽叢臨葉疎。"]', '["黄鹤悲歌絕，椒花清頌餘。","埃凝寫鄰镜，網結和扉鱼。","銀消风燭尽，珠滅夜輪虛。","別有南陵路，幽叢臨葉疎。"]', '诗', 'shi', '', NULL, '江王太妃挽歌 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c33b0d82-de8c-4a99-add2-32e69029c53a', '故北平公挽歌', '故北平公挽歌', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["木落園林曠，庭虛風露寒。","北里清音絕，南陔芳草殘。","遠氣猶標劒，浮雲尚寫冠。","寂寂琴臺晚，秋陰入井榦。"]', '["木落园林曠，庭虛风露寒。","北里清音絕，南陔芳草殘。","远氣猶標劒，浮云尚寫冠。","寂寂琴台晚，秋陰入井榦。"]', '诗', 'shi', '', NULL, '故北平公挽歌 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d33a49d6-b3c2-45a4-bd82-ecf4ccdc7f56', '高密長公主挽歌', '高密长公主挽歌', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["湘渚韜靈跡，娥臺靜瑞音。","鳳逐清簫遠，鸞隨幽鏡沈。","霜處華芙落，風前銀燭侵。","寂寞平陽宅，月冷洞房深。"]', '["湘渚韜靈跡，娥台静瑞音。","鳳逐清簫远，鸾隨幽镜沈。","霜处华芙落，风前銀燭侵。","寂寞平陽宅，月冷洞房深。"]', '诗', 'shi', '', NULL, '高密長公主挽歌 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a2afca0-d72b-40f6-96f5-fbe3d0c1f7ea', '詠畫障', '詠畫障', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["芳晨麗日桃花浦，珠簾翠帳鳳凰樓。","蔡女菱歌移錦纜，燕姬春望上瓊鉤。","新妝漏影浮輕扇，冶袖飄香入淺流。","未減行雨荆臺下，自比凌波洛浦遊。"]', '["芳晨丽日桃花浦，珠簾翠帳鳳凰楼。","蔡女菱歌移錦纜，燕姬春望上瓊鉤。","新妝漏影浮轻扇，冶袖飄香入淺流。","未減行雨荆台下，自比凌波洛浦游。"]', '诗', 'shi', '', NULL, '詠畫障 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4413a74d-82b0-425c-9e34-0c9aeb8ac648', '奉和秋日即目應制', '奉和秋日即目應制', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["上苑通平樂，神池邇建章。","樓臺相掩映，城闕互相望。","緹油泛行幔，簫吹轉浮梁。","晚雲含朔氣，斜照蕩秋光。","落葉飄蟬影，平流寫雁行。","槿散凌風縟，荷銷裛露香。","仙歌臨枍詣，玄豫歷長楊。","歸路乘明月，千門開未央。"]', '["上苑通平乐，神池邇建章。","楼台相掩映，城闕互相望。","緹油泛行幔，簫吹轉浮梁。","晚云含朔氣，斜照蕩秋光。","落葉飄蟬影，平流寫雁行。","槿散凌风縟，荷銷裛露香。","仙歌臨枍詣，玄豫歷长楊。","归路乘明月，千门开未央。"]', '诗', 'shi', '', NULL, '奉和秋日即目應制 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3be8afbd-659c-4e16-b54d-a9d17b9d0e0c', '入朝洛堤步行', '入朝洛堤步行', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["脈脈廣川流，驅馬歷長洲。","鵲飛山月曙，蟬噪野風秋。"]', '["脈脈廣川流，驱马歷长洲。","鵲飞山月曙，蟬噪野风秋。"]', '诗', 'shi', '', NULL, '入朝洛堤步行 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3805b61-3371-4a92-aff5-82d83177cab0', '春日', '春日', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["花輕蝶亂仙人杏，葉密鶯啼帝女桑。","飛雲閣上春應至，明月樓中夜未央。"]', '["花轻蝶亂仙人杏，葉密鶯啼帝女桑。","飞云閣上春應至，明月楼中夜未央。"]', '诗', 'shi', '', NULL, '春日 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b2eea0c-48e0-42dd-a21d-8e13d489c060', '從駕閭山詠馬', '從駕閭山詠马', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["桂香塵處減，練影月前空。","定惑由關吏，徒嗟塞上翁。"]', '["桂香塵处減，練影月前空。","定惑由关吏，徒嗟塞上翁。"]', '诗', 'shi', '', NULL, '從駕閭山詠馬 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f9629a6-5d2c-40e9-a041-d147abeef542', '中和樂九章 歌登封第一', '中和乐九章 歌登封第一', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["炎圖喪寶，黃歷開璿。","祖武類帝，宗文配天。","玉鑾垂日，翠華陵煙。","東雲干呂，南風入弦。","山稱萬歲，河慶千年。","金繩永結，璧麗長懸。"]', '["炎圖喪寶，黄歷开璿。","祖武類帝，宗文配天。","玉鑾垂日，翠华陵煙。","东云干呂，南风入弦。","山稱万歲，河慶千年。","金繩永結，璧丽长懸。"]', '诗', 'shi', '', NULL, '中和樂九章 歌登封第一 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8eb92f8-053a-4c1a-a640-289d0d9ab816', '中和樂九章 歌明堂第二', '中和乐九章 歌明堂第二', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["穆穆聖皇，雍雍明堂。","左平右墄，上圓下方。","調均風雨，制度陰陽。","四牕八達，五室九房。","南通夏火，西瞰秋霜。","天子臨御，萬玉鏘鏘。"]', '["穆穆聖皇，雍雍明堂。","左平右墄，上圓下方。","調均风雨，制度陰陽。","四牕八達，五室九房。","南通夏火，西瞰秋霜。","天子臨御，万玉鏘鏘。"]', '诗', 'shi', '', NULL, '中和樂九章 歌明堂第二 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('216be46a-d387-41d5-a32d-be55eb8d7df3', '中和樂九章 歌東軍第三', '中和乐九章 歌东軍第三', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["遐哉廟畧，赫矣台臣。","橫戈碣石，倚劒浮津。","風丘拂籜，日域清塵。","島夷復祀，龍伯來賓。","休兵宇縣，獻馘天闉。","斾海凱入，耀輝震震。"]', '["遐哉廟畧，赫矣台臣。","橫戈碣石，倚劒浮津。","风丘拂籜，日域清塵。","島夷复祀，龙伯来賓。","休兵宇縣，獻馘天闉。","斾海凱入，耀輝震震。"]', '诗', 'shi', '', NULL, '中和樂九章 歌東軍第三 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a51eb3e2-275f-4a08-aa77-fe282f1d6e61', '中和樂九章 歌南郊第四', '中和乐九章 歌南郊第四', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["虔郊上帝，肅事圓丘。","龍駕四牡，鸞旗九斿。","鐘歌晚引，紫煬高浮。","日麗蒼璧，雲飛鳴球。","皇之慶矣，萬壽千秋。"]', '["虔郊上帝，肅事圓丘。","龙駕四牡，鸾旗九斿。","鐘歌晚引，紫煬高浮。","日丽蒼璧，云飞鳴球。","皇之慶矣，万壽千秋。"]', '诗', 'shi', '', NULL, '中和樂九章 歌南郊第四 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a65461a-e36b-4aea-89b4-76daa72b01f7', '中和樂九章 歌中宮第五', '中和乐九章 歌中宮第五', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["祥遊沙麓，慶洽瑤衣。","黃雲晝聚，白氣宵飛。","居中履正，稟和體微。","儀刑赤縣，演教椒闈。","陶鈞萬國，丹青四妃。","河洲在詠，風化攸歸。"]', '["祥游沙麓，慶洽瑤衣。","黄云晝聚，白氣宵飞。","居中履正，稟和體微。","儀刑赤縣，演教椒闈。","陶鈞万国，丹青四妃。","河洲在詠，风化攸归。"]', '诗', 'shi', '', NULL, '中和樂九章 歌中宮第五 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18ed2950-d4b7-41e5-b754-5ce5f5bf030f', '中和樂九章 歌儲宮第六', '中和乐九章 歌儲宮第六', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["波澄少海，景麗前星。","高禖誕聖，甲觀昇靈。","承規翠所，問寢瑤庭。","宗儒側席，問道橫經。","山賓皎皎，國胄青青。","黃裳元吉，邦家以寧。"]', '["波澄少海，景丽前星。","高禖誕聖，甲观昇靈。","承規翠所，问寢瑤庭。","宗儒側席，问道橫經。","山賓皎皎，国胄青青。","黄裳元吉，邦家以寧。"]', '诗', 'shi', '', NULL, '中和樂九章 歌儲宮第六 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff1d8ce6-94dc-420c-b43f-af8554fe8316', '中和樂九章 歌諸王第七', '中和乐九章 歌諸王第七', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["星陳帝子，嶽列天孫。","義光帶礪，象著乾坤。","我有明德，利建攸存。","苴以茅社，錫以犧尊。","藩屏王室，翼亮堯門。","八才兩獻，夫何足論。"]', '["星陳帝子，嶽列天孫。","義光带礪，象著乾坤。","我有明德，利建攸存。","苴以茅社，錫以犧尊。","藩屏王室，翼亮堯门。","八才兩獻，夫何足論。"]', '诗', 'shi', '', NULL, '中和樂九章 歌諸王第七 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e4bec93-76b7-4e2c-9d2b-819a4ef5afa0', '中和樂九章 歌公卿第八', '中和乐九章 歌公卿第八', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["蹇蹇三事，師師百僚。","羣龍在職，振鷺盈朝。","豐金輝首，珮玉鳴腰。","青蒲翼翼，丹地翹翹。","歌雲佐漢，捧日匡堯。","天工人代，邈邈昭昭。"]', '["蹇蹇三事，師師百僚。","羣龙在職，振鷺盈朝。","豐金輝首，珮玉鳴腰。","青蒲翼翼，丹地翹翹。","歌云佐漢，捧日匡堯。","天工人代，邈邈昭昭。"]', '诗', 'shi', '', NULL, '中和樂九章 歌公卿第八 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37f6d6e8-1009-47ae-93fe-371a7c13156d', '中和樂九章 總歌第九', '中和乐九章 總歌第九', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["明明天子兮聖德揚，穆穆皇后兮陰化康。","登若木兮坐明堂，池濛汜兮家扶桑。","武化偃兮文化昌，禮樂昭兮股肱良。","君臣已定兮君永無疆，顏子更生兮徒皇皇。","若有人兮天一方，忠爲衣兮信爲裳。","飡白玉兮飲瓊芳，心思荃兮路阻長。"]', '["明明天子兮聖德揚，穆穆皇后兮陰化康。","登若木兮坐明堂，池濛汜兮家扶桑。","武化偃兮文化昌，禮乐昭兮股肱良。","君臣已定兮君永無疆，顏子更生兮徒皇皇。","若有人兮天一方，忠爲衣兮信爲裳。","飡白玉兮饮瓊芳，心思荃兮路阻长。"]', '诗', 'shi', '', NULL, '中和樂九章 總歌第九 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e008c814-63b8-43d7-a6a9-5a3811f43bcf', '關山月', '关山月', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["塞垣通碣石，虜障抵[祁]連。","相思在萬里，明月正孤懸。","影移金岫北，光斷玉門前。","寄言閨中婦，時看鴻雁天。"]', '["塞垣通碣石，虜障抵[祁]連。","相思在万里，明月正孤懸。","影移金岫北，光斷玉门前。","寄言閨中婦，时看鴻雁天。"]', '诗', 'shi', '', NULL, '關山月 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe894df3-7104-4471-805e-e24902878c69', '上之回', '上之回', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["回中道路險，蕭關烽候多。","五營屯北地，萬乘出西河。","單于拜玉璽，天子按雕戈。","振旅汾川曲，秋風橫大歌。"]', '["回中道路險，蕭关烽候多。","五營屯北地，万乘出西河。","單于拜玉璽，天子按雕戈。","振旅汾川曲，秋风橫大歌。"]', '诗', 'shi', '', NULL, '上之回 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63a70f2f-c3ce-4a77-baa3-1285517fa6e7', '紫騮馬', '紫騮马', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["騮馬照金鞍，轉戰入皐蘭。","塞門風稍急，長城水正寒。","雪暗鳴珂重，山長噴玉難。","不辭橫絕漠，流血幾時乾。"]', '["騮马照金鞍，轉戰入皐蘭。","塞门风稍急，长城水正寒。","雪暗鳴珂重，山长噴玉难。","不辞橫絕漠，流血幾时乾。"]', '诗', 'shi', '', NULL, '紫騮馬 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a143f96-ed36-4fab-a412-73d4459e498e', '戰城南', '戰城南', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["將軍出紫塞，冒頓在烏貪。","笳喧雁門北，陣翼龍城南。","琱弓夜宛轉，鐵騎曉參驔。","應須駐白日，爲待戰方酣。"]', '["將軍出紫塞，冒頓在烏貪。","笳喧雁门北，陣翼龙城南。","琱弓夜宛轉，鐵騎晓參驔。","應須駐白日，爲待戰方酣。"]', '诗', 'shi', '', NULL, '戰城南 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd1fcb2e-9a07-4c07-b009-a26393c5ab2a', '梅花落', '梅花落', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["梅嶺花初發，天山雪未開。","雪處疑花落，花邊似雪迴。","因風入舞袖，雜粉向妝臺。","匈奴幾萬里，春至不知來。"]', '["梅嶺花初發，天山雪未开。","雪处疑花落，花邊似雪迴。","因风入舞袖，杂粉向妝台。","匈奴幾万里，春至不知来。"]', '诗', 'shi', '', NULL, '梅花落 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('899334f7-2f09-4409-b031-d7f8e0d038fe', '結客少年場行', '結客少年場行', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["長安重遊俠，洛陽富財雄。","玉劒浮雲騎，金鞭明月弓。","鬬雞過渭北，走馬向關東。","孫賓遙見待，郭解暗相通。","不受千金爵，誰論萬里功。","將軍下天上，虜騎入雲中。","烽火夜似月，兵氣曉成虹。","橫行徇知己，負羽遠從戎。","龍旌昏朔霧，鳥陣捲胡風。","追奔瀚海咽，戰罷陰山空。","歸來謝天子，何如馬上翁。"]', '["长安重游俠，洛陽富財雄。","玉劒浮云騎，金鞭明月弓。","鬬雞過渭北，走马向关东。","孫賓遙见待，郭解暗相通。","不受千金爵，誰論万里功。","將軍下天上，虜騎入云中。","烽火夜似月，兵氣晓成虹。","橫行徇知己，負羽远從戎。","龙旌昏朔霧，鸟陣捲胡风。","追奔瀚海咽，戰罷陰山空。","归来謝天子，何如马上翁。"]', '诗', 'shi', '', NULL, '結客少年場行 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98ed1ed0-947f-4518-8970-6bb48552eef5', '詠史四首 一', '詠史四首 一', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["季生昔未達，身辱功不成。","髠鉗爲臺隸，灌園變姓名。","幸逢滕將軍，兼遇曹丘生。","漢祖廣招納，一朝拜公卿。","百金孰云重，一諾良匪輕。","廷議斬樊噲，羣公寂無聲。","處身孤且直，遭時坦而平。","丈夫當如此，唯唯何足榮。"]', '["季生昔未達，身辱功不成。","髠鉗爲台隸，灌园变姓名。","幸逢滕將軍，兼遇曹丘生。","漢祖廣招納，一朝拜公卿。","百金孰云重，一諾良匪轻。","廷議斬樊噲，羣公寂無声。","处身孤且直，遭时坦而平。","丈夫當如此，唯唯何足榮。"]', '诗', 'shi', '', NULL, '詠史四首 一 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32fcd011-62ac-4e60-bb70-5e1dfb7bd024', '詠史四首 二', '詠史四首 二', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["大漢昔云季，小人道遂振。","玉帛委奄尹，斧鑕嬰縉紳。","邈哉郭先生，卷舒得其真。","雍容謝朝廷，談笑獎人倫。","在晦不絕俗，處亂不爲親。","諸侯不得友，天子不得臣。","沖情甄負甑，重價折角巾。","悠悠天下士，相送洛橋津。","誰知仙舟上寂寂無四鄰。"]', '["大漢昔云季，小人道遂振。","玉帛委奄尹，斧鑕嬰縉紳。","邈哉郭先生，卷舒得其真。","雍容謝朝廷，談笑獎人倫。","在晦不絕俗，处亂不爲親。","諸侯不得友，天子不得臣。","沖情甄負甑，重價折角巾。","悠悠天下士，相送洛橋津。","誰知仙舟上寂寂無四鄰。"]', '诗', 'shi', '', NULL, '詠史四首 二 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd4d47e1-211a-4c28-ba8d-f150b163eb2f', '詠史四首 三', '詠史四首 三', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["公業負奇志，交結盡才雄。","良田四百頃，所食常不充。","一爲侍御史，慷慨說何公。","何公何爲敗，吾謀適不同。","仲頴恣殘忍，廢興良在躬。","死人如亂麻，天子如轉蓬。","干戈及黃屋，荆棘生紫宮。","鄭生運其謀，將以清國戎。","時來命不遂，脫身歸山東。","凜凜千載下，穆然懷春風。"]', '["公業負奇志，交結尽才雄。","良田四百頃，所食常不充。","一爲侍御史，慷慨说何公。","何公何爲敗，吾謀適不同。","仲頴恣殘忍，廢兴良在躬。","死人如亂麻，天子如轉蓬。","干戈及黄屋，荆棘生紫宮。","鄭生運其謀，將以清国戎。","时来命不遂，脫身归山东。","凜凜千載下，穆然懷春风。"]', '诗', 'shi', '', NULL, '詠史四首 三 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1484c8f0-a418-491f-aa6f-6d82048973bc', '詠史四首 四', '詠史四首 四', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["昔有平陵男，姓朱名阿游。","直髮上衝冠，壯氣橫三秋。","願得斬馬劒，先斷佞臣頭。","天子玉檻折，將軍丹血流。","捐生不肯拜，視死其若休。","歸來教鄉里，童蒙遠相求。","弟子數百人，散在十二州。","三公不敢吏，五鹿何能酬。","名與日月懸，義與天壤儔。","何必疲執戟，區區在封侯。","偉哉曠達士，知命固不憂。"]', '["昔有平陵男，姓朱名阿游。","直髮上衝冠，壯氣橫三秋。","願得斬马劒，先斷佞臣头。","天子玉檻折，將軍丹血流。","捐生不肯拜，視死其若休。","归来教乡里，童蒙远相求。","弟子數百人，散在十二州。","三公不敢吏，五鹿何能酬。","名與日月懸，義與天壤儔。","何必疲執戟，區區在封侯。","偉哉曠達士，知命固不憂。"]', '诗', 'shi', '', NULL, '詠史四首 四 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('952912a1-abf3-4682-acec-26e87d18ccd2', '贈李榮道士', '贈李榮道士', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["錦節銜天使，瓊仙駕羽君。","投金翠山曲，奠璧清江濆。","圓洞開丹鼎，方壇聚絳雲。","寶貺幽難識，空歌迥易分。","風搖十洲影，日亂九江文。","敷誠歸上帝，應詔在明君。","獨有南冠客，耿耿泣離羣。","遙看八會所，真氣曉氤氳。"]', '["錦節銜天使，瓊仙駕羽君。","投金翠山曲，奠璧清江濆。","圓洞开丹鼎，方壇聚絳云。","寶貺幽难識，空歌迥易分。","风搖十洲影，日亂九江文。","敷誠归上帝，應詔在明君。","独有南冠客，耿耿泣離羣。","遙看八會所，真氣晓氤氳。"]', '诗', 'shi', '', NULL, '贈李榮道士 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8c8dbac-7eae-4dcb-90a8-0e3fed6ddf71', '贈李榮道士', '贈李榮道士', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["錦節銜天使，瓊仙駕羽君。","投金翠山曲，奠璧清江濆。","圓洞開丹鼎，方壇聚絳雲。","寶貺幽難識，空歌迥易分。"]', '["錦節銜天使，瓊仙駕羽君。","投金翠山曲，奠璧清江濆。","圓洞开丹鼎，方壇聚絳云。","寶貺幽难識，空歌迥易分。"]', '诗', 'shi', '', NULL, '贈李榮道士 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3205bd3f-23c0-4d1f-8c83-bcf561a72da9', '早度分水嶺', '早度分水嶺', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["丁年遊蜀道，班鬢向長安。","徒費周王粟，空彈漢吏冠。","馬蹄穿欲盡，貂裘敝轉寒。","層冰橫九折，積石凌七盤。","重溪既下漱，峻峰亦上干。","隴頭聞戍鼓，嶺外咽飛湍。","瑟瑟松風急，蒼蒼山月團。","傳語後來者，斯路誠獨難。"]', '["丁年游蜀道，班鬢向长安。","徒費周王粟，空彈漢吏冠。","马蹄穿欲尽，貂裘敝轉寒。","層冰橫九折，積石凌七盤。","重溪既下漱，峻峰亦上干。","隴头闻戍鼓，嶺外咽飞湍。","瑟瑟松风急，蒼蒼山月團。","傳語後来者，斯路誠独难。"]', '诗', 'shi', '', NULL, '早度分水嶺 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a456ea5-dcc7-4ec2-bac8-4de49ae19515', '三月曲水宴得尊字', '三月曲水宴得尊字', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["風煙彭澤里，山水仲長園。","由來棄銅墨，本自重琴尊。","高情邈不嗣，雅道今復存。","有美光時彥，養德坐山樊。","門開芳杜逕，室距桃花源。","公子黃金勒，仙人紫氣軒。","長懷去城市，高詠狎蘭蓀。","連沙飛白鷺，孤嶼嘯玄猿。","日影巖前落，雲花江上翻。","興蘭車馬散，林塘夕鳥喧。"]', '["风煙彭澤里，山水仲长园。","由来棄銅墨，本自重琴尊。","高情邈不嗣，雅道今复存。","有美光时彥，養德坐山樊。","门开芳杜逕，室距桃花源。","公子黄金勒，仙人紫氣軒。","长懷去城市，高詠狎蘭蓀。","連沙飞白鷺，孤嶼嘯玄猿。","日影巖前落，云花江上翻。","兴蘭车马散，林塘夕鸟喧。"]', '诗', 'shi', '', NULL, '三月曲水宴得尊字 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfcbb8ca-cb5f-4dfd-aec2-6cb17f15bdde', '奉使益州至長安發鍾陽驛', '奉使益州至长安發鍾陽驛', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["躋險方未夷，乘春聊騁望。","落花赴丹谷，奔流下青嶂。","葳蕤曉樹滋，滉瀁春江漲。","平川看釣侶，狹徑聞樵唱。","蝶戲綠苔前，鶯歌白雲上。","耳目多異賞，風煙有奇狀。","峻阻將長城，高標吞巨舫。","聯翩事羈靮，辛苦勞疲恙。","夕濟幾潺湲，晨登每惆悵。","誰念復芻狗，山河獨偏喪。"]', '["躋險方未夷，乘春聊騁望。","落花赴丹谷，奔流下青嶂。","葳蕤晓樹滋，滉瀁春江漲。","平川看釣侶，狹徑闻樵唱。","蝶戲綠苔前，鶯歌白云上。","耳目多異賞，风煙有奇狀。","峻阻將长城，高標吞巨舫。","聯翩事羈靮，辛苦勞疲恙。","夕濟幾潺湲，晨登每惆悵。","誰念复芻狗，山河独偏喪。"]', '诗', 'shi', '', NULL, '奉使益州至長安發鍾陽驛 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddc742aa-1465-4177-9203-011a6f7e6594', '和王奭秋夜有所思', '和王奭秋夜有所思', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["寂寂南軒夜，悠然懷所知。","長河落雁苑，明月下鯨池。","鳳臺有清曲，此曲何人吹？","丹脣間玉齒，妙響入雲涯。","窮巷秋風葉，空庭寒露枝。","勞歌欲有和，星鬢已將垂。"]', '["寂寂南軒夜，悠然懷所知。","长河落雁苑，明月下鯨池。","鳳台有清曲，此曲何人吹？","丹脣间玉齒，妙响入云涯。","窮巷秋风葉，空庭寒露枝。","勞歌欲有和，星鬢已將垂。"]', '诗', 'shi', '', NULL, '和王奭秋夜有所思 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddfb2ee8-b085-4e10-88b0-019d283ee62a', '望宅中樹有所思', '望宅中樹有所思', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["我家有庭樹，秋葉正離離。","上舞雙棲鳥，中秀合歡枝。","勞思復勞望，相見不相知。","何當共攀折？歌笑此堂垂。"]', '["我家有庭樹，秋葉正離離。","上舞雙棲鸟，中秀合歡枝。","勞思复勞望，相见不相知。","何當共攀折？歌笑此堂垂。"]', '诗', 'shi', '', NULL, '望宅中樹有所思 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa26701d-f665-411b-8136-bc7a13aadd99', '宿晉安亭', '宿晉安亭', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["聞有弦歌地，穿鑿本多奇。","遊人試一覽，臨翫果忘疲。","窗橫暮捲葉，簷臥古生枝。","舊石開紅鮮，新河覆綠池。","孤猿稍斷絕，宿鳥復參差。","汎灩月華曉，裴回星鬢垂。","今日刪書客，悽惶君詎知。"]', '["闻有弦歌地，穿鑿本多奇。","游人試一覽，臨翫果忘疲。","窗橫暮捲葉，簷臥古生枝。","旧石开紅鲜，新河覆綠池。","孤猿稍斷絕，宿鸟复參差。","汎灩月华晓，裴回星鬢垂。","今日刪书客，悽惶君詎知。"]', '诗', 'shi', '', NULL, '宿晉安亭 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b48823da-d47c-4b7e-8305-b73f2749f803', '于時春也慨然有江湖之思寄贈柳九隴', '于时春也慨然有江湖之思寄贈柳九隴', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["提琴一萬里，負書三十年。","晨攀偃蹇樹，暮宿清泠泉。","翔禽鳴我側，旅獸過我前。","無人且無事，獨酌還獨眠。","遙聞彭澤宰，高弄武城弦。","形骸寄文墨，意氣託神仙。","我有壺中要，題爲物外篇。","將以貽好道，道遠莫致旃。","相思勞日夜，相望阻風煙。","坐惜春華晚，徒令客思懸。","水去東南地，氣凝西北天。","關山悲蜀道，花鳥憶秦川。","天子何時問，公卿本亦憐。","自哀還自樂，歸藪復歸田。","海屋銀爲棟，雲車電作鞭。","倘遇鸞將鶴，誰論貂與蟬。","萊洲頻度淺，桃實幾成圓。","寄言飛鳧舃，歲[晏]同聯翩。"]', '["提琴一万里，負书三十年。","晨攀偃蹇樹，暮宿清泠泉。","翔禽鳴我側，旅獸過我前。","無人且無事，独酌還独眠。","遙闻彭澤宰，高弄武城弦。","形骸寄文墨，意氣託神仙。","我有壺中要，題爲物外篇。","將以貽好道，道远莫致旃。","相思勞日夜，相望阻风煙。","坐惜春华晚，徒令客思懸。","水去东南地，氣凝西北天。","关山悲蜀道，花鸟憶秦川。","天子何时问，公卿本亦怜。","自哀還自乐，归藪复归田。","海屋銀爲棟，云车電作鞭。","倘遇鸾將鹤，誰論貂與蟬。","萊洲頻度淺，桃實幾成圓。","寄言飞鳧舃，歲[晏]同聯翩。"]', '诗', 'shi', '', NULL, '于時春也慨然有江湖之思寄贈柳九隴 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a56ea6d4-8621-48a9-8a87-8d4d08de2a45', '至望喜矚目言懷貽劍外知己', '至望喜矚目言懷貽劍外知己', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["聖圖夷九折，神化掩三分。","緘愁赴蜀道，題拙奉虞薰。","隱轔度深谷，遙褭上高雲。","碧流遞縈注，青山互糾紛。","澗松咽風緒，巖花濯露文。","思北常依馭，圖南每喪羣。"]', '["聖圖夷九折，神化掩三分。","緘愁赴蜀道，題拙奉虞薰。","隐轔度深谷，遙褭上高云。","碧流遞縈注，青山互糾紛。","澗松咽风緒，巖花濯露文。","思北常依馭，圖南每喪羣。"]', '诗', 'shi', '', NULL, '至望喜矚目言懷貽劍外知己 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b90c0ead-1e5e-4603-93a3-8d85e5e17d72', '赤谷安禪師塔', '赤谷安禪師塔', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["獨坐巖之曲，悠然無俗紛。","酌酒呈丹桂，思詩贈白雲。","煙霞朝晚聚，猿鳥歲時聞。","水華競秋色，山翠含夕曛。","高談十二部，細覈五千文。","如如數冥味，生生理氛氳。","古人有糟粕，輪扁情未分。","且當事芝朮，從吾所好云。"]', '["独坐巖之曲，悠然無俗紛。","酌酒呈丹桂，思诗贈白云。","煙霞朝晚聚，猿鸟歲时闻。","水华競秋色，山翠含夕曛。","高談十二部，細覈五千文。","如如數冥味，生生理氛氳。","古人有糟粕，輪扁情未分。","且當事芝朮，從吾所好云。"]', '诗', 'shi', '', NULL, '赤谷安禪師塔 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76adf443-ff11-4694-ba5f-e1e292f0a5d1', '贈益府裴錄事', '贈益府裴錄事', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["忽忽歲云暮，相望限風煙。","長歌欲對酒，危坐遂停弦。","停弦變霜露，對酒懷朋故。","朝看桂蟾晚，夜聞鴻雁度。","鴻度何時還？桂晚不同攀。","浮雲映丹壑，明月滿青山。","青山雲路深，丹壑月華臨。","耿耿離憂積，空令星鬢侵。"]', '["忽忽歲云暮，相望限风煙。","长歌欲对酒，危坐遂停弦。","停弦变霜露，对酒懷朋故。","朝看桂蟾晚，夜闻鴻雁度。","鴻度何时還？桂晚不同攀。","浮云映丹壑，明月满青山。","青山云路深，丹壑月华臨。","耿耿離憂積，空令星鬢侵。"]', '诗', 'shi', '', NULL, '贈益府裴錄事 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd055164-1caf-4777-80c7-68876c692c7d', '贈益府羣官', '贈益府羣官', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["一鳥自北燕，飛來向西蜀。","單棲劍門上，獨舞岷山足。","昂藏多古貌，哀怨有新曲。","羣鳳從之遊，問之何所欲？","荅言寒鄉子，飄颻萬餘里。","不息惡木枝，不飲盜泉水。","常思稻粱遇，願棲梧桐樹。","智者不我邀，愚夫余不顧。","所以成獨立，耿耿歲云暮。","日夕苦風霜，思歸赴洛陽。","羽翮毛衣短，關山道路長。","明月流客思，白雲迷故鄉。","誰能借風便，一舉凌蒼蒼。"]', '["一鸟自北燕，飞来向西蜀。","單棲劍门上，独舞岷山足。","昂藏多古貌，哀怨有新曲。","羣鳳從之游，问之何所欲？","荅言寒乡子，飄颻万餘里。","不息惡木枝，不饮盜泉水。","常思稻粱遇，願棲梧桐樹。","智者不我邀，愚夫余不顧。","所以成独立，耿耿歲云暮。","日夕苦风霜，思归赴洛陽。","羽翮毛衣短，关山道路长。","明月流客思，白云迷故乡。","誰能借风便，一舉凌蒼蒼。"]', '诗', 'shi', '', NULL, '贈益府羣官 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c71cfe7d-31c6-46ef-bd68-b6b4a166ea48', '送梓州高參軍還京', '送梓州高參軍還京', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["京洛風塵遠，褒斜煙露深。","北遊君似智，南飛我異禽。","別路琴聲斷，秋山猿鳥吟。","一乖青巖酌，空佇白雲心。"]', '["京洛风塵远，褒斜煙露深。","北游君似智，南飞我異禽。","別路琴声斷，秋山猿鸟吟。","一乖青巖酌，空佇白云心。"]', '诗', 'shi', '', NULL, '送梓州高參軍還京 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f732e41e-9f88-4a95-bc87-fa8e37c485c5', '大劍送別劉右史', '大劍送別劉右史', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["金碧禺山遠，關梁蜀道難。","相逢屬晚歲，相送動征鞍。","地咽緜川冷，雲凝劍閣寒。","倘遇忠孝所，爲道憶長安。"]', '["金碧禺山远，关梁蜀道难。","相逢屬晚歲，相送动征鞍。","地咽緜川冷，云凝劍閣寒。","倘遇忠孝所，爲道憶长安。"]', '诗', 'shi', '', NULL, '大劍送別劉右史 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af89cce8-dcc4-4f68-9ca3-16e349a73a7b', '同臨津紀明府孤雁', '同臨津紀明府孤雁', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["三秋違北地，萬里向南翔。","河洲花稍白，關塞葉初黃。","避繳風霜勁，懷書道路長。","水流疑箭動，月照似弓傷。","橫天無有陣，度海不成行。","會刷能鳴羽，還赴上林鄉。"]', '["三秋違北地，万里向南翔。","河洲花稍白，关塞葉初黄。","避繳风霜勁，懷书道路长。","水流疑箭动，月照似弓傷。","橫天無有陣，度海不成行。","會刷能鳴羽，還赴上林乡。"]', '诗', 'shi', '', NULL, '同臨津紀明府孤雁 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe567083-75f2-4088-8cd1-7cd783bfe142', '失羣雁', '失羣雁', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["三秋北地雪皚皚，萬里南翔渡海來。","欲隨石燕沈湘水，試逐銅烏繞帝臺。","帝臺銀闕距金塘，中間鵷鷺已成行。","先過上苑傳書信，暫下中州戲稻粱。","虞人負繳來相及，齊客虛弓忽見傷。","毛翎頻頓飛無力，羽翮摧頹君不識。","唯有莊周解愛鳴，復道郊哥重奇色。","惆悵驚思悲未已，裴回自憐中罔極。","傳聞有鳥集朝陽，詎勝仙鳧邇帝鄉。","雲間海上應鳴舞，遠得鵾弦猶獨撫。","金龜全寫中牟印，玉鵠當變萊蕪釜。","願君弄影鳳皇池，時憶籠中摧折羽。"]', '["三秋北地雪皚皚，万里南翔渡海来。","欲隨石燕沈湘水，試逐銅烏繞帝台。","帝台銀闕距金塘，中间鵷鷺已成行。","先過上苑傳书信，暫下中州戲稻粱。","虞人負繳来相及，齊客虛弓忽见傷。","毛翎頻頓飞無力，羽翮摧頹君不識。","唯有莊周解愛鳴，复道郊哥重奇色。","惆悵驚思悲未已，裴回自怜中罔極。","傳闻有鸟集朝陽，詎勝仙鳧邇帝乡。","云间海上應鳴舞，远得鵾弦猶独撫。","金龟全寫中牟印，玉鵠當变萊蕪釜。","願君弄影鳳皇池，时憶籠中摧折羽。"]', '诗', 'shi', '', NULL, '失羣雁 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a29954ad-e112-4473-9804-52bad4b62b9c', '行路難', '行路难', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["君不見長安城北渭橋邊，枯木橫槎臥古田。","昔日含紅復含紫，常時留霧亦留煙。","春景春風花似雪，香車玉轝恆闐咽。","若箇遊人不競攀，若箇娼家不來折。","娼家寶袜蛟龍帔，公子銀鞍千萬騎。","黃鶯一一向花嬌，青鳥雙雙將子戲。","千尺長條百尺枝，月桂星榆相蔽虧。","珊瑚葉上鴛鴦鳥，鳳皇巢裏雛鵷兒。","巢傾枝折鳳歸去，條枯葉落任風吹。","一朝零落無人問，萬古摧殘君詎知。","人生貴賤無終始，倏忽須臾難久恃。","誰家能駐西山日，誰家能堰東流水。","漢家陵樹滿秦川，行來行去盡哀憐。","自昔公卿二千石，咸擬榮華一萬年。","不見朱脣將白貌，唯聞素棘與黃泉。","金貂有時換美酒，玉麈但搖莫計錢。","寄言坐客神仙署，一生一死交情處。","蒼龍闕下君不來，白鶴山前我應去。","雲間海上邈難期，赤心會合在何時。","但願堯年一百萬，長作巢由也不辭。"]', '["君不见长安城北渭橋邊，枯木橫槎臥古田。","昔日含紅复含紫，常时留霧亦留煙。","春景春风花似雪，香车玉轝恆闐咽。","若箇游人不競攀，若箇娼家不来折。","娼家寶袜蛟龙帔，公子銀鞍千万騎。","黄鶯一一向花嬌，青鸟雙雙將子戲。","千尺长條百尺枝，月桂星榆相蔽虧。","珊瑚葉上鴛鴦鸟，鳳皇巢裏雛鵷兒。","巢傾枝折鳳归去，條枯葉落任风吹。","一朝零落無人问，万古摧殘君詎知。","人生貴賤無終始，倏忽須臾难久恃。","誰家能駐西山日，誰家能堰东流水。","漢家陵樹满秦川，行来行去尽哀怜。","自昔公卿二千石，咸擬榮华一万年。","不见朱脣將白貌，唯闻素棘與黄泉。","金貂有时換美酒，玉麈但搖莫計錢。","寄言坐客神仙署，一生一死交情处。","蒼龙闕下君不来，白鹤山前我應去。","云间海上邈难期，赤心會合在何时。","但願堯年一百万，长作巢由也不辞。"]', '诗', 'shi', '', NULL, '行路難 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fecca913-ad91-4fab-b34d-5734a2533039', '長安古意', '长安古意', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["長安大道連狹斜，青牛白馬七香車。","玉輦縱橫過主第，金鞭絡繹向侯家。","龍銜寶蓋承朝日，鳳吐流蘇帶晚霞。","百丈遊絲爭繞樹，一羣嬌鳥共啼花。","啼花戲蝶千門側，碧樹銀臺萬種色。","複道交窗作合歡，雙闕連薨垂鳳翼。","梁家畫閣天中起，漢帝金莖雲外直。","樓前相望不相知，陌上相逢詎相識。","借問吹簫向紫煙，曾經學舞度芳年。","得成比目何辭死，願作鴛鴦不羨仙。","比目鴛鴦真可羨，雙去雙來君不見。","生憎帳額繡孤鸞，好取門簾帖雙燕。","雙燕雙飛繞畫梁，羅幃翠被鬱金香。","片片行雲著蟬鬢，纖纖初月上鴉黃。","鴉黃粉白車中出，含嬌含態情非一。","妖童寶馬鐵連錢，娼婦盤龍金屈膝。","御史府中烏夜啼，廷尉門前雀欲栖。","隱隱朱城臨玉道，遙遙翠幰沒金堤。","挾彈飛鷹杜陵北，探丸借客渭橋西。","俱邀俠客芙蓉劍，共宿娼家桃李蹊。","娼家日暮紫羅裙，清歌一囀口氛氳。","北堂夜夜人如月，南陌朝朝騎似雲。","南陌北堂連北里，五劇三條控三市。","弱柳青槐拂地垂，佳氣紅塵暗天起。","漢代金吾千騎來，翡翠屠蘇鸚鵡杯。","羅襦寶帶爲君解，燕歌趙舞爲君開。","別有豪華稱將相，轉日回天不相讓。","意氣由來排灌夫，專權判不容蕭相。","專權意氣本豪雄，青虬紫燕坐春風。","自言歌舞長千載，自謂驕奢凌五公。","節物風光不相待，桑田碧海須臾改。","昔時金階白玉堂，即今唯見青松在。","寂寂寥寥[揚]子居，年年歲歲一牀書。","獨有南山桂花發，飛來飛去襲人裾。"]', '["长安大道連狹斜，青牛白马七香车。","玉輦縱橫過主第，金鞭絡繹向侯家。","龙銜寶蓋承朝日，鳳吐流蘇带晚霞。","百丈游絲爭繞樹，一羣嬌鸟共啼花。","啼花戲蝶千门側，碧樹銀台万種色。","複道交窗作合歡，雙闕連薨垂鳳翼。","梁家畫閣天中起，漢帝金莖云外直。","楼前相望不相知，陌上相逢詎相識。","借问吹簫向紫煙，曾經学舞度芳年。","得成比目何辞死，願作鴛鴦不羨仙。","比目鴛鴦真可羨，雙去雙来君不见。","生憎帳額繡孤鸾，好取门簾帖雙燕。","雙燕雙飞繞畫梁，羅幃翠被鬱金香。","片片行云著蟬鬢，纖纖初月上鴉黄。","鴉黄粉白车中出，含嬌含態情非一。","妖童寶马鐵連錢，娼婦盤龙金屈膝。","御史府中烏夜啼，廷尉门前雀欲栖。","隐隐朱城臨玉道，遙遙翠幰沒金堤。","挾彈飞鷹杜陵北，探丸借客渭橋西。","俱邀俠客芙蓉劍，共宿娼家桃李蹊。","娼家日暮紫羅裙，清歌一囀口氛氳。","北堂夜夜人如月，南陌朝朝騎似云。","南陌北堂連北里，五劇三條控三市。","弱柳青槐拂地垂，佳氣紅塵暗天起。","漢代金吾千騎来，翡翠屠蘇鸚鵡杯。","羅襦寶带爲君解，燕歌趙舞爲君开。","別有豪华稱將相，轉日回天不相讓。","意氣由来排灌夫，專權判不容蕭相。","專權意氣本豪雄，青虬紫燕坐春风。","自言歌舞长千載，自謂驕奢凌五公。","節物风光不相待，桑田碧海須臾改。","昔时金階白玉堂，即今唯见青松在。","寂寂寥寥[揚]子居，年年歲歲一牀书。","独有南山桂花發，飞来飞去襲人裾。"]', '诗', 'shi', '', NULL, '長安古意 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fefcf1f-2187-40e6-942e-96af173b04a8', '明月引', '明月引', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["洞庭波起兮鴻雁翔，風瑟瑟兮野蒼蒼。","浮雲卷靄，明月流光。","荆南兮趙北，碣石兮瀟湘。","澄清規於萬里，照離思於千行。","橫桂枝於西第，繞菱花於北堂。","高樓思婦，飛蓋君王。","文姬絕域，侍子他鄉。","見胡鞍之似練，知漢劍之如霜。","試登高而騁目，莫不變而回腸。"]', '["洞庭波起兮鴻雁翔，风瑟瑟兮野蒼蒼。","浮云卷靄，明月流光。","荆南兮趙北，碣石兮瀟湘。","澄清規於万里，照離思於千行。","橫桂枝於西第，繞菱花於北堂。","高楼思婦，飞蓋君王。","文姬絕域，侍子他乡。","见胡鞍之似練，知漢劍之如霜。","試登高而騁目，莫不变而回腸。"]', '诗', 'shi', '', NULL, '明月引 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d9a5fbd-cf99-4284-aa9a-84eef6ac87bd', '獄中學騷體', '獄中学騷體', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["夫何秋夜之無情兮，皎皛悠悠而太長。","圜戶杳其幽邃兮，愁人披此嚴霜。","見河漢之西落，聞鴻雁之南翔。","山有桂兮桂有芳，心思君兮君不將。","憂與憂兮相積，歡與歡兮兩忘。","風嫋嫋兮木紛紛，凋綠葉兮吹白雲。","寸步千里兮不相聞，思公子兮日將曛。","林已暮兮鳥羣飛，重門掩兮人徑稀。","萬族皆有所托兮，蹇獨淹留而不歸。"]', '["夫何秋夜之無情兮，皎皛悠悠而太长。","圜戶杳其幽邃兮，愁人披此嚴霜。","见河漢之西落，闻鴻雁之南翔。","山有桂兮桂有芳，心思君兮君不將。","憂與憂兮相積，歡與歡兮兩忘。","风嫋嫋兮木紛紛，凋綠葉兮吹白云。","寸步千里兮不相闻，思公子兮日將曛。","林已暮兮鸟羣飞，重门掩兮人徑稀。","万族皆有所托兮，蹇独淹留而不归。"]', '诗', 'shi', '', NULL, '獄中學騷體 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b9647e1-6a61-431a-8a23-12ebaaa3c122', '懷仙引', '懷仙引', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["若有人兮山之曲，駕青虬兮乘白鹿。","往從之遊願心足，披澗戶，訪巖軒。","石瀨潺湲橫石徑，松蘿冪䍥掩松門。","下空濛而無鳥，上巉巖而有猨。","懷飛閣，度飛梁。","休余馬於幽谷，挂余冠於夕陽。","曲復曲兮煙莊邃，行復行兮天路長。","修途杳其未半，飛雨忽以茫茫。","山坱軋，磴連褰。","攀石壁而無據，泝泥溪而不前。","向無情之白日，竊有恨於皇天。","回行遵故道，通川遍流潦。","回首望羣峰，白雲正溶溶。","珠爲闕兮玉爲樓，青雲蓋兮紫霜裘。","天長地久時相憶，千齡萬代一來遊。"]', '["若有人兮山之曲，駕青虬兮乘白鹿。","往從之游願心足，披澗戶，訪巖軒。","石瀨潺湲橫石徑，松蘿冪䍥掩松门。","下空濛而無鸟，上巉巖而有猨。","懷飞閣，度飞梁。","休余马於幽谷，挂余冠於夕陽。","曲复曲兮煙莊邃，行复行兮天路长。","修途杳其未半，飞雨忽以茫茫。","山坱軋，磴連褰。","攀石壁而無據，泝泥溪而不前。","向無情之白日，竊有恨於皇天。","回行遵故道，通川遍流潦。","回首望羣峰，白云正溶溶。","珠爲闕兮玉爲楼，青云蓋兮紫霜裘。","天长地久时相憶，千齡万代一来游。"]', '诗', 'shi', '', NULL, '懷仙引 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf0d1aaf-62b4-45fe-846b-143219dae055', '七日登樂遊故墓', '七日登乐游故墓', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["四序周緹籥，三正紀璿耀。","綠野變初黃，暘山開曉眺。","中天擢露掌，匝地分星徼。","漢寢睠遺靈，秦江想餘弔。","蟻泛青田酌，鶯歌紫芝調。","柳色搖歲華，冰文蕩春照。","遠迹謝羣動，高情符衆妙。","蘭遊澹未歸，傾光下巖窈。"]', '["四序周緹籥，三正紀璿耀。","綠野变初黄，暘山开晓眺。","中天擢露掌，匝地分星徼。","漢寢睠遺靈，秦江想餘弔。","蟻泛青田酌，鶯歌紫芝調。","柳色搖歲华，冰文蕩春照。","远迹謝羣动，高情符衆妙。","蘭游澹未归，傾光下巖窈。"]', '诗', 'shi', '', NULL, '七日登樂遊故墓 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42a9e25a-c411-4091-8ea5-98eaf8f40898', '釋疾文三歌 一', '釋疾文三歌 一', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["歲將暮兮歡不再，時已晚兮憂來多。","東郊絕此麒麟筆，西山秘此鳳凰柯。"]', '["歲將暮兮歡不再，时已晚兮憂来多。","东郊絕此麒麟笔，西山秘此鳳凰柯。"]', '诗', 'shi', '', NULL, '釋疾文三歌 一 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d5af37b-1189-4896-8316-99d231ba3437', '釋疾文三歌 二', '釋疾文三歌 二', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["歲去憂來兮東流水，地久天長兮人共死。","明鏡羞窺兮向十年，駿馬停驅兮幾千里。","麟兮鳳兮，自古吞恨無已。"]', '["歲去憂来兮东流水，地久天长兮人共死。","明镜羞窺兮向十年，駿马停驱兮幾千里。","麟兮鳳兮，自古吞恨無已。"]', '诗', 'shi', '', NULL, '釋疾文三歌 二 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2e17d89-5874-44f1-bb92-508c917b605c', '釋疾文三歌 三', '釋疾文三歌 三', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["茨山有薇兮潁水有漪，夷爲柏兮秋有實。","叔爲柳兮春向飛，倏爾而笑，汎滄浪兮不歸。"]', '["茨山有薇兮潁水有漪，夷爲柏兮秋有實。","叔爲柳兮春向飞，倏爾而笑，汎滄浪兮不归。"]', '诗', 'shi', '', NULL, '釋疾文三歌 三 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c62feb83-a378-4215-bc2b-62e2cb4a7bee', '酬楊比部員外暮宿琴堂朝躋書閣率爾見贈之作', '酬楊比部員外暮宿琴堂朝躋书閣率爾见贈之作', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["閑拂簷塵看，鳴琴候月彈。","桃源迷漢姓，松徑有秦官。","空谷歸人少，青山背日寒。","羨君棲隱處，遙望在雲端。"]', '["闲拂簷塵看，鳴琴候月彈。","桃源迷漢姓，松徑有秦官。","空谷归人少，青山背日寒。","羨君棲隐处，遙望在云端。"]', '诗', 'shi', '', NULL, '酬楊比部員外暮宿琴堂朝躋書閣率爾見贈之作 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e13b9e9c-1984-45ef-9a2a-8311dad2e95e', '劉生', '劉生', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["劉生氣不平，抱劍欲專征。","報恩爲豪俠，死難在橫行。","翠羽裝刀鞘，黃金飾馬鈴。","但令一顧重，不恡百身輕。"]', '["劉生氣不平，抱劍欲專征。","報恩爲豪俠，死难在橫行。","翠羽裝刀鞘，黄金飾马鈴。","但令一顧重，不恡百身轻。"]', '诗', 'shi', '', NULL, '劉生 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90828a1a-3eb1-43cf-af43-cb3801b4a11b', '隴頭水', '隴头水', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["隴阪高無極，征人一望鄉。","關河別去水，沙塞斷歸腸。","馬繫千年樹，旌懸九月霜。","從來共嗚咽，皆是爲勤王。"]', '["隴阪高無極，征人一望乡。","关河別去水，沙塞斷归腸。","马繫千年樹，旌懸九月霜。","從来共嗚咽，皆是爲勤王。"]', '诗', 'shi', '', NULL, '隴頭水 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('758b079b-ecac-4f88-8600-257403690898', '巫山高', '巫山高', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["巫山望不極，望望下朝氛。","莫辨啼猿樹，徒看神女雲。","驚濤亂水脉，驟雨暗峯文。","霑裳即此地，況復遠思君。"]', '["巫山望不極，望望下朝氛。","莫辨啼猿樹，徒看神女云。","驚濤亂水脉，驟雨暗峯文。","霑裳即此地，況复远思君。"]', '诗', 'shi', '', NULL, '巫山高 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6409c86-16a6-4fe7-96ea-8b86172a06bc', '芳樹', '芳樹', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["芳樹本多奇，年華復在斯。","結翠成新幄，開紅滿故枝。","風歸花歷亂，日度影參差。","容色朝朝落，思君君不知。"]', '["芳樹本多奇，年华复在斯。","結翠成新幄，开紅满故枝。","风归花歷亂，日度影參差。","容色朝朝落，思君君不知。"]', '诗', 'shi', '', NULL, '芳樹 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27d3b858-16d3-4ace-8220-5af012748f1b', '雨雪曲', '雨雪曲', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["虜騎三秋入，關雲萬里平。","雪似胡沙暗，冰如漢月明。","高闕銀爲闕，長城玉作城。","節旄零落盡，天子不知名。"]', '["虜騎三秋入，关云万里平。","雪似胡沙暗，冰如漢月明。","高闕銀爲闕，长城玉作城。","節旄零落尽，天子不知名。"]', '诗', 'shi', '', NULL, '雨雪曲 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8ea6e9f-64ed-4670-b042-077f5dc46e86', '昭君怨', '昭君怨', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["合殿恩中絕，交河使漸稀。","肝腸辭玉輦，形影向金微。","漢地草應綠，胡庭沙正飛。","願逐三秋雁，年年一度歸。"]', '["合殿恩中絕，交河使漸稀。","肝腸辞玉輦，形影向金微。","漢地草應綠，胡庭沙正飞。","願逐三秋雁，年年一度归。"]', '诗', 'shi', '', NULL, '昭君怨 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b0035e7-490b-42ff-ad61-0927a2ed7573', '折楊柳', '折楊柳', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["倡樓啓曙扉，楊柳正依依。","鶯啼知歲隔，條變識春歸。","露葉凝愁黛，風花亂舞衣。","攀折聊將寄，軍中音信稀。"]', '["倡楼啓曙扉，楊柳正依依。","鶯啼知歲隔，條变識春归。","露葉凝愁黛，风花亂舞衣。","攀折聊將寄，軍中音信稀。"]', '诗', 'shi', '', NULL, '折楊柳 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77c3a980-2231-4b34-bc2e-5af8d2406b6d', '十五夜觀燈', '十五夜观灯', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["錦里開芳宴，蘭缸豔早年。","縟彩遙分地，繁光遠綴天。","接漢疑星落，依樓似月懸。","別有千金笑，來映九枝前。"]', '["錦里开芳宴，蘭缸豔早年。","縟彩遙分地，繁光远綴天。","接漢疑星落，依楼似月懸。","別有千金笑，来映九枝前。"]', '诗', 'shi', '', NULL, '十五夜觀燈 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fce5f0f4-4c34-4d14-9bee-fed38b21efab', '入秦川界', '入秦川界', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["隴阪長無極，蒼山望不窮。","石徑縈疑斷，回流映似空。","花開綠野霧，鶯囀紫巖風。","春芳勿遽盡，留賞故人同。"]', '["隴阪长無極，蒼山望不窮。","石徑縈疑斷，回流映似空。","花开綠野霧，鶯囀紫巖风。","春芳勿遽尽，留賞故人同。"]', '诗', 'shi', '', NULL, '入秦川界 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e58176d9-b4b1-48e7-a190-3ff988aecf3b', '文翁講堂', '文翁講堂', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["錦里淹中館，岷山稷下亭。","空梁無燕雀，古壁有丹青。","槐落猶疑市，苔深不辨銘。","良哉二千石，江漢表遺靈。"]', '["錦里淹中館，岷山稷下亭。","空梁無燕雀，古壁有丹青。","槐落猶疑市，苔深不辨銘。","良哉二千石，江漢表遺靈。"]', '诗', 'shi', '', NULL, '文翁講堂 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0ecc4f3-31c2-4ad4-baee-fdecaf8a31fd', '相如琴臺', '相如琴台', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["聞有雍容地，千年無四鄰。","園院風煙古，池臺松檟春。","雲疑作賦客，月似聽琴人。","寂寂啼鶯處，空傷遊子神。"]', '["闻有雍容地，千年無四鄰。","园院风煙古，池台松檟春。","云疑作賦客，月似听琴人。","寂寂啼鶯处，空傷游子神。"]', '诗', 'shi', '', NULL, '相如琴臺 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5513f618-8c28-45d0-82ec-78abbd3ae8d5', '石鏡寺', '石镜寺', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["古墓芙蓉塔，神銘松柏煙。","鸞沈仙鏡底，花沒梵輪前。","銖衣千古佛，寶月兩重圓。","隱隱香臺夜，鐘聲徹九天。"]', '["古墓芙蓉塔，神銘松柏煙。","鸾沈仙镜底，花沒梵輪前。","銖衣千古佛，寶月兩重圓。","隐隐香台夜，鐘声徹九天。"]', '诗', 'shi', '', NULL, '石鏡寺 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26f2fd7c-70a5-4489-bda1-392ee6d638f1', '辛法司宅觀妓', '辛法司宅观妓', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["南國佳人至，北棠羅薦開。","長帬隨鳳管，促柱送鸞杯。","雲光身後落，雪態掌中回。","到愁金谷晚，不怪玉山頹。"]', '["南国佳人至，北棠羅薦开。","长帬隨鳳管，促柱送鸾杯。","云光身後落，雪態掌中回。","到愁金谷晚，不怪玉山頹。"]', '诗', 'shi', '', NULL, '辛法司宅觀妓 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d92eb7e-a7d9-4cb5-96d9-b998639424c6', '春晚山莊率題二首 一', '春晚山莊率題二首 一', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["顧步三春晚，田園四望通。","遊絲橫惹樹，戲蝶亂依藂。","竹懶偏宜水，花狂不待風。","唯餘詩酒意，當了一生中。"]', '["顧步三春晚，田园四望通。","游絲橫惹樹，戲蝶亂依藂。","竹懶偏宜水，花狂不待风。","唯餘诗酒意，當了一生中。"]', '诗', 'shi', '', NULL, '春晚山莊率題二首 一 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01c26c32-dad7-4abd-ad71-b00d221b2975', '春晚山莊率題二首 二', '春晚山莊率題二首 二', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["田家無四鄰，獨坐一園春。","鶯啼非選樹，魚戲不驚綸。","山水彈琴盡，風花酌酒頻。","年華已可樂，高興復留人。"]', '["田家無四鄰，独坐一园春。","鶯啼非選樹，鱼戲不驚綸。","山水彈琴尽，风花酌酒頻。","年华已可乐，高兴复留人。"]', '诗', 'shi', '', NULL, '春晚山莊率題二首 二 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88d2ec1d-9d99-4720-a891-b4ba23537b8f', '江中望月', '江中望月', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["江水向涔陽，澄澄寫月光。","鏡圓珠留徹，弦滿箭波長。","沈鉤搖兔影，浮桂動丹芳。","延照相思夕，千里共霑裳。"]', '["江水向涔陽，澄澄寫月光。","镜圓珠留徹，弦满箭波长。","沈鉤搖兔影，浮桂动丹芳。","延照相思夕，千里共霑裳。"]', '诗', 'shi', '', NULL, '江中望月 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0997b1d-d026-4ea1-b3a9-fef2234b6338', '元日述懷', '元日述懷', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["筮仕無中秩，歸耕有外臣。","人歌小歲酒，花舞大唐春。","草色迷三徑，風光動四鄰。","願得長如此，年年物候新。"]', '["筮仕無中秩，归耕有外臣。","人歌小歲酒，花舞大唐春。","草色迷三徑，风光动四鄰。","願得长如此，年年物候新。"]', '诗', 'shi', '', NULL, '元日述懷 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da0a9e6d-a04b-41f8-833a-3415dd531eed', '益州城西張超亭觀妓', '益州城西張超亭观妓', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["落日明歌席，行雲逐舞人。","江前飛暮雨，梁上下輕塵。","冶服看疑畫，粧樓望似春。","高車勿遽返，長袖欲相親。"]', '["落日明歌席，行云逐舞人。","江前飞暮雨，梁上下轻塵。","冶服看疑畫，粧楼望似春。","高车勿遽返，长袖欲相親。"]', '诗', 'shi', '', NULL, '益州城西張超亭觀妓 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b25d8508-d48a-40b0-8aaa-11edad3a9783', '還京贈別', '還京贈別', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["風月清江夜，山水白雲朝。","萬里同爲客，三秋契不凋。","戲鳧分斷岸，歸騎別高標。","一去仙橋道，還望錦城遙。"]', '["风月清江夜，山水白云朝。","万里同爲客，三秋契不凋。","戲鳧分斷岸，归騎別高標。","一去仙橋道，還望錦城遙。"]', '诗', 'shi', '', NULL, '還京贈別 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f647af7a-5f34-4622-a308-1539377f083a', '至陳倉曉晴望京邑', '至陳倉晓晴望京邑', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["拂曙驅飛傳，初晴帶曉涼。","霧歛長安樹，雲歸仙帝鄉。","澗流漂素沫，巖景靄朱光。","今朝好風色，延瞰極天莊。"]', '["拂曙驱飞傳，初晴带晓涼。","霧歛长安樹，云归仙帝乡。","澗流漂素沫，巖景靄朱光。","今朝好风色，延瞰極天莊。"]', '诗', 'shi', '', NULL, '至陳倉曉晴望京邑 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('406125ce-3514-4912-9677-b66df15d8eac', '晚渡滹沱敬贈魏大', '晚渡滹沱敬贈魏大', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["津谷朝行遠，冰川夕望曛。","霞明深淺浪，風卷去來雲。","澄波泛月影，激浪聚沙文。","誰忍仙舟上，攜手獨思君。"]', '["津谷朝行远，冰川夕望曛。","霞明深淺浪，风卷去来云。","澄波泛月影，激浪聚沙文。","誰忍仙舟上，携手独思君。"]', '诗', 'shi', '', NULL, '晚渡滹沱敬贈魏大 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d446bc5b-152e-411a-9028-e7289a43e20c', '和吳侍御被使燕然', '和吳侍御被使燕然', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["春歸龍塞北，騎指雁門垂。","胡笳折楊柳，漢使採燕支。","戍城聊一望，花雪幾參差。","關山有新曲，應向笛中吹。"]', '["春归龙塞北，騎指雁门垂。","胡笳折楊柳，漢使採燕支。","戍城聊一望，花雪幾參差。","关山有新曲，應向笛中吹。"]', '诗', 'shi', '', NULL, '和吳侍御被使燕然 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d34ac42-aab9-4db1-bb9a-20a0e732a481', '七夕泛舟二首 一', '七夕泛舟二首 一', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["汀葭肅徂暑，江樹起初涼。","水疑通織室，舟似泛仙潢。","連橈渡急響，鳴櫂下浮光。","日晚菱歌唱，風煙滿夕陽。"]', '["汀葭肅徂暑，江樹起初涼。","水疑通织室，舟似泛仙潢。","連橈渡急响，鳴櫂下浮光。","日晚菱歌唱，风煙满夕陽。"]', '诗', 'shi', '', NULL, '七夕泛舟二首 一 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('183d219f-5901-43a4-ac3a-12ef4bedd6c4', '七夕泛舟二首 二', '七夕泛舟二首 二', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["鳳杼秋期至，鳧舟野望開。","微吟翠塘側，延想白雲隈。","石似支機罷，槎疑犯宿來。","天潢殊漫漫，日暮獨悠哉。"]', '["鳳杼秋期至，鳧舟野望开。","微吟翠塘側，延想白云隈。","石似支機罷，槎疑犯宿来。","天潢殊漫漫，日暮独悠哉。"]', '诗', 'shi', '', NULL, '七夕泛舟二首 二 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee8f79ea-36e2-4175-8575-f62818b98204', '西使兼送孟學士南遊', '西使兼送孟学士南游', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["地道巴陵北，天山弱水東。","相看萬餘里，共倚一征蓬。","零雨悲王粲，清尊別孔融。","裴回聞夜鶴，悵望待秋鴻。","骨肉胡秦外，風塵關塞中。","唯餘劍鋒在，耿耿氣成虹。"]', '["地道巴陵北，天山弱水东。","相看万餘里，共倚一征蓬。","零雨悲王粲，清尊別孔融。","裴回闻夜鹤，悵望待秋鴻。","骨肉胡秦外，风塵关塞中。","唯餘劍鋒在，耿耿氣成虹。"]', '诗', 'shi', '', NULL, '西使兼送孟學士南遊 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6afd914e-0c61-40bc-acd8-f5bb9476e9b7', '送鄭司倉入蜀', '送鄭司倉入蜀', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["離人丹水北，遊客錦城東。","別意還無已，離憂自不窮。","隴雲朝結陣，江月夜臨空。","關塞疲征馬，霜氛落早鴻。","潘年三十外，蜀道五千中。","送君秋水曲，酌酒對清風。"]', '["離人丹水北，游客錦城东。","別意還無已，離憂自不窮。","隴云朝結陣，江月夜臨空。","关塞疲征马，霜氛落早鴻。","潘年三十外，蜀道五千中。","送君秋水曲，酌酒对清风。"]', '诗', 'shi', '', NULL, '送鄭司倉入蜀 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dcbca94-4176-4e40-b656-4a0f102177e6', '綿州官池贈別同賦灣字', '綿州官池贈別同賦灣字', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["輶軒遵上國，仙佩下靈關。","尊酒方無地，聯綣喜暫攀。","離言欲贈策，高辨正連環。","野逕浮雲斷，荒池春草斑。","殘花落古樹，度鳥入澄灣。","欲敍他鄉別，幽谷有綿蠻。"]', '["輶軒遵上国，仙佩下靈关。","尊酒方無地，聯綣喜暫攀。","離言欲贈策，高辨正連环。","野逕浮云斷，荒池春草斑。","殘花落古樹，度鸟入澄灣。","欲敍他乡別，幽谷有綿蠻。"]', '诗', 'shi', '', NULL, '綿州官池贈別同賦灣字 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a068fb5-6efa-4d5d-887e-a0a9441d3d25', '還赴蜀中貽示京邑遊好', '還赴蜀中貽示京邑游好', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["籞宿花初滿，章臺柳向飛。","如何正此日，還望昔多違。","悵別風期阻，將乖雲會稀。","歛衽辭丹闕，懸旗陟翠微。","野禽喧戍鼓，春草變征衣。","回顧長安道，關山起夕霏。"]', '["籞宿花初满，章台柳向飞。","如何正此日，還望昔多違。","悵別风期阻，將乖云會稀。","歛衽辞丹闕，懸旗陟翠微。","野禽喧戍鼓，春草变征衣。","回顧长安道，关山起夕霏。"]', '诗', 'shi', '', NULL, '還赴蜀中貽示京邑遊好 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd4a26c0-ca35-4280-b6ec-36900df5c9ef', '初夏日幽莊', '初夏日幽莊', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["聞有高蹤客，耿介坐幽莊。","林壑人事少，風煙鳥路長。","瀑水含秋氣，垂藤引夏涼。","苗深全覆隴，荷上半侵塘。","釣渚青鳧沒，村田白鷺翔。","知君振奇藻，還嗣海隅芳。"]', '["闻有高蹤客，耿介坐幽莊。","林壑人事少，风煙鸟路长。","瀑水含秋氣，垂藤引夏涼。","苗深全覆隴，荷上半侵塘。","釣渚青鳧沒，村田白鷺翔。","知君振奇藻，還嗣海隅芳。"]', '诗', 'shi', '', NULL, '初夏日幽莊 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31ccc940-33ab-45d5-9ee7-4c32092a3001', '山莊休沐', '山莊休沐', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["蘭署乘閑日，蓬扉狎遁棲。","龍柯疎玉井，鳳葉下金堤。","川光搖水箭，山氣上雲梯。","亭幽聞唳鶴，窗曉聽鳴雞。","玉軫臨風奏，瓊漿映月攜。","田家自有樂，誰肯謝青溪。"]', '["蘭署乘闲日，蓬扉狎遁棲。","龙柯疎玉井，鳳葉下金堤。","川光搖水箭，山氣上云梯。","亭幽闻唳鹤，窗晓听鳴雞。","玉軫臨风奏，瓊漿映月携。","田家自有乐，誰肯謝青溪。"]', '诗', 'shi', '', NULL, '山莊休沐 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bb5d9f5-9691-48ed-8cae-86453e48e22d', '山林休日田家', '山林休日田家', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["歸休乘暇日，饁稼返秋場。","徑草疏王篲，巖枝落帝桑。","耕田虞訟寢，鑿井漢機忘。","戎葵朝委露，齊棗夜含霜。","南澗泉初冽，東籬菊正芳。","還思北窗下，高臥偃羲皇。"]', '["归休乘暇日，饁稼返秋場。","徑草疏王篲，巖枝落帝桑。","耕田虞訟寢，鑿井漢機忘。","戎葵朝委露，齊棗夜含霜。","南澗泉初冽，东籬菊正芳。","還思北窗下，高臥偃羲皇。"]', '诗', 'shi', '', NULL, '山林休日田家 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d2b0b52-172e-4e69-bdbc-4a6b057037df', '宴梓州南亭得池字', '宴梓州南亭得池字', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["二條開勝迹，大隱叶沖規。","亭閣分危岫，樓臺遶曲池。","長薄秋煙起，飛梁古蔓垂。","水鳥翻荷葉，山蟲咬桂枝。","遊人惜將晚，公子愛忘疲。","願得回三舍，琴尊長若斯。"]', '["二條开勝迹，大隐叶沖規。","亭閣分危岫，楼台遶曲池。","长薄秋煙起，飞梁古蔓垂。","水鸟翻荷葉，山蟲咬桂枝。","游人惜將晚，公子愛忘疲。","願得回三舍，琴尊长若斯。"]', '诗', 'shi', '', NULL, '宴梓州南亭得池字 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14c66721-876b-4492-b9c9-4b6937b1952f', '山行寄劉李二參軍', '山行寄劉李二參軍', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["萬里煙塵客，三春桃李時。","事去紛無限，愁來不自持。","狂歌欲嘆鳳，失路反占龜。","草礙人行緩，花繁鳥度遲。","彼美參卿事，留連求友詩。","安知倦遊子，兩鬢漸如絲。"]', '["万里煙塵客，三春桃李时。","事去紛無限，愁来不自持。","狂歌欲嘆鳳，失路反占龟。","草礙人行緩，花繁鸟度遲。","彼美參卿事，留連求友诗。","安知倦游子，兩鬢漸如絲。"]', '诗', 'shi', '', NULL, '山行寄劉李二參軍 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84f9b347-9993-4dfd-8fb6-39bfd6c7dc24', '首春貽京邑文士', '首春貽京邑文士', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["寂寂罷將迎，門無車馬聲。","橫琴荅山水，披卷閱公卿。","忽聞歲云晏，倚杖出簷楹。","寒辭楊柳陌，春滿鳳皇城。","梅花扶院吐，蘭葉遶階生。","覽鏡改容色，藏書留姓名。","時來不假問，生死任交情。"]', '["寂寂罷將迎，门無车马声。","橫琴荅山水，披卷閱公卿。","忽闻歲云晏，倚杖出簷楹。","寒辞楊柳陌，春满鳳皇城。","梅花扶院吐，蘭葉遶階生。","覽镜改容色，藏书留姓名。","时来不假问，生死任交情。"]', '诗', 'shi', '', NULL, '首春貽京邑文士 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cedbc79-1480-4f03-bcd3-91c04c9cf805', '贈許左丞從駕萬年宮', '贈許左丞從駕万年宮', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["聞道上之回，詔蹕下蓬萊。","中樞移北斗，左轄去南臺。","黃山聞鳳笛，清蹕侍龍媒。","曳日朱旗卷，參雲金障開。","朝參五城柳，夕宴柏梁杯。","漢畤光如月，秦祠聽似雷。","寂寂芸香閣，離思獨悠哉。"]', '["闻道上之回，詔蹕下蓬萊。","中樞移北斗，左轄去南台。","黄山闻鳳笛，清蹕侍龙媒。","曳日朱旗卷，參云金障开。","朝參五城柳，夕宴柏梁杯。","漢畤光如月，秦祠听似雷。","寂寂芸香閣，離思独悠哉。"]', '诗', 'shi', '', NULL, '贈許左丞從駕萬年宮 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2065dc7a-5ac9-406f-b7cd-285c5b5293df', '晚渡渭橋寄示京邑遊好', '晚渡渭橋寄示京邑游好', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["我行背城闕，驅馬獨悠悠。","寥落百年事，裴回萬里憂。","途遙日向夕，時晚鬢將秋。","滔滔俯東逝，耿耿泣西浮。","長虹掩釣浦，落雁下星洲。","草變黃山曲，花飛清渭流。","迸水驚愁鷺，騰沙起狎鷗。","一赴清泥道，空思玄灞遊。"]', '["我行背城闕，驱马独悠悠。","寥落百年事，裴回万里憂。","途遙日向夕，时晚鬢將秋。","滔滔俯东逝，耿耿泣西浮。","长虹掩釣浦，落雁下星洲。","草变黄山曲，花飞清渭流。","迸水驚愁鷺，腾沙起狎鷗。","一赴清泥道，空思玄灞游。"]', '诗', 'shi', '', NULL, '晚渡渭橋寄示京邑遊好 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac59c260-320d-4909-adc9-841b7af88f6d', '羈臥山中', '羈臥山中', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["臥壑迷時代，行歌任死生。","紅顏意氣盡，白璧故交輕。","澗戶無人跡，山窗聽鳥聲。","春色緣巖上，寒光入溜平。","雪盡松帷暗，雲開石路明。","夜伴飢鼯宿，朝隨馴雉行。","度溪猶憶處，尋洞不知名。","紫書常日閱，丹藥幾年成。","扣鐘鳴天鼓，燒香厭地精。","倘遇浮丘鶴，飄颻凌太清。"]', '["臥壑迷时代，行歌任死生。","紅顏意氣尽，白璧故交轻。","澗戶無人跡，山窗听鸟声。","春色緣巖上，寒光入溜平。","雪尽松帷暗，云开石路明。","夜伴飢鼯宿，朝隨馴雉行。","度溪猶憶处，尋洞不知名。","紫书常日閱，丹藥幾年成。","扣鐘鳴天鼓，燒香厭地精。","倘遇浮丘鹤，飄颻凌太清。"]', '诗', 'shi', '', NULL, '羈臥山中 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd4e8883-5eb6-423e-9854-8e6b0f0bbfa2', '酬張少府柬之', '酬張少府柬之', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["昔余與夫子，相遇漢川陰。","珠浦龍猶臥，檀溪馬正沈。","價重瑤山曲，詞驚丹鳳林。","十年暌賞慰，萬里隔招尋。","毫翰風期阻，荆衡雲路深。","鵬飛俱望昔，蠖屈共悲今。","誰謂青衣道，還嘆白頭吟。","地接神仙磵，江連雲雨岑。","飛泉如散玉，落日似懸金。","重以瑤華贈，空懷舞詠心。"]', '["昔余與夫子，相遇漢川陰。","珠浦龙猶臥，檀溪马正沈。","價重瑤山曲，词驚丹鳳林。","十年暌賞慰，万里隔招尋。","毫翰风期阻，荆衡云路深。","鵬飞俱望昔，蠖屈共悲今。","誰謂青衣道，還嘆白头吟。","地接神仙磵，江連云雨岑。","飞泉如散玉，落日似懸金。","重以瑤华贈，空懷舞詠心。"]', '诗', 'shi', '', NULL, '酬張少府柬之 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b889c22b-1949-4327-9f2f-ad9804991c35', '過東山谷口', '過东山谷口', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["不知名利險，辛苦滯皇州。","始覺飛塵倦，歸來事綠疇。","桃源迷處所，桂樹可淹留。","跡異人間俗，禽同海上鷗。","古苔依井被，新乳傍崖流。","野老堪成鶴，山神或化鳩。","泉鳴碧澗底，花落紫巖幽。","日暮飡龜殼，天寒御鹿裘。","不辨秦將漢，寧知春與秋。","多謝青溪客，去去赤松遊。"]', '["不知名利險，辛苦滯皇州。","始覺飞塵倦，归来事綠疇。","桃源迷处所，桂樹可淹留。","跡異人间俗，禽同海上鷗。","古苔依井被，新乳傍崖流。","野老堪成鹤，山神或化鳩。","泉鳴碧澗底，花落紫巖幽。","日暮飡龟殼，天寒御鹿裘。","不辨秦將漢，寧知春與秋。","多謝青溪客，去去赤松游。"]', '诗', 'shi', '', NULL, '過東山谷口 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e4f53da-0190-413d-9c18-f8043d90e2be', '送幽州陳參軍赴任寄呈鄉曲父老', '送幽州陳參軍赴任寄呈乡曲父老', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["薊北三千里，關西二十年。","馮唐猶在漢，樂毅不歸燕。","人同黃鶴遠，鄉共白雲連。","郭隗池臺處，昭王尊酒前。","故人當已老，舊壑幾成田。","紅顏如昨日，衰鬢似秋天。","西蜀橋應毀，東周石尚全。","灞池水猶綠，榆關月早圓。","塞雲初上雁，庭樹欲銷蟬。","送君之舊國，揮淚獨澘然。"]', '["薊北三千里，关西二十年。","馮唐猶在漢，乐毅不归燕。","人同黄鹤远，乡共白云連。","郭隗池台处，昭王尊酒前。","故人當已老，旧壑幾成田。","紅顏如昨日，衰鬢似秋天。","西蜀橋應毀，东周石尚全。","灞池水猶綠，榆关月早圓。","塞云初上雁，庭樹欲銷蟬。","送君之旧国，揮泪独澘然。"]', '诗', 'shi', '', NULL, '送幽州陳參軍赴任寄呈鄉曲父老 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc29cf49-34db-4291-8795-cea0661afcb2', '哭金部韋郎中', '哭金部韋郎中', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["金曹初受拜，玉地始含香。","翻同五日尹，遽見一星亡。","賀客猶扶路，哀人遂上堂。","歌筵長寂寂，哭位自蒼蒼。","歲時賓徑斷，朝暮雀羅張。","書留魏主闕，魂掩漢家牀。","徒令永平帝，千載罷撞郎。"]', '["金曹初受拜，玉地始含香。","翻同五日尹，遽见一星亡。","賀客猶扶路，哀人遂上堂。","歌筵长寂寂，哭位自蒼蒼。","歲时賓徑斷，朝暮雀羅張。","书留魏主闕，魂掩漢家牀。","徒令永平帝，千載罷撞郎。"]', '诗', 'shi', '', NULL, '哭金部韋郎中 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f3d1c20-b12f-4ffe-9b34-a5c7c951c469', '哭明堂裴主簿', '哭明堂裴主簿', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["締歡三十載，通家數百年。","潘楊稱代穆，秦晉忝姻連。","風雲洛陽道，花月茂陵田。","相悲共相樂，交騎復交筵。","始謂調金鼎，如何掩玉泉。","黃公酒鑪處，青眼竹林前。","故琴無復雪，新樹但生煙。","遽痛蘭襟斷，徒令寶劍懸。","客散同秋葉，人亡似夜川。","送君一長慟，松臺路幾千。"]', '["締歡三十載，通家數百年。","潘楊稱代穆，秦晉忝姻連。","风云洛陽道，花月茂陵田。","相悲共相乐，交騎复交筵。","始謂調金鼎，如何掩玉泉。","黄公酒鑪处，青眼竹林前。","故琴無复雪，新樹但生煙。","遽痛蘭襟斷，徒令寶劍懸。","客散同秋葉，人亡似夜川。","送君一长慟，松台路幾千。"]', '诗', 'shi', '', NULL, '哭明堂裴主簿 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('669a1229-04ef-4957-81a7-043b871316ac', '同崔錄事哭鄭員外', '同崔錄事哭鄭員外', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["文學秋天遠，郎官星位尊。","伊人表時彥，飛譽滿司存。","楚席光文雅，瑤山侍討論。","鳳詞凌漢閣，龜辯罩周園。","已陪東嶽駕，將逝北溟鯤。","如何萬化盡，空嘆九飛魂。","白馬西京驛，青松北海門。","夜臺無曉箭，朝奠有虛尊。","一代儒風沒，千年隴霧昏。","梁山送夫子，湘水弔王孫。","僕本多悲淚，沾裳不待猿。","聞君絕弦曲，吞恨更無言。"]', '["文学秋天远，郎官星位尊。","伊人表时彥，飞譽满司存。","楚席光文雅，瑤山侍討論。","鳳词凌漢閣，龟辯罩周园。","已陪东嶽駕，將逝北溟鯤。","如何万化尽，空嘆九飞魂。","白马西京驛，青松北海门。","夜台無晓箭，朝奠有虛尊。","一代儒风沒，千年隴霧昏。","梁山送夫子，湘水弔王孫。","僕本多悲泪，沾裳不待猿。","闻君絕弦曲，吞恨更無言。"]', '诗', 'shi', '', NULL, '同崔錄事哭鄭員外 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a64c785b-0a0f-4392-af9c-47926d1dac90', '登玉清', '登玉清', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["絕頂橫臨日，孤峰半倚天。","裴回拜真老，萬里見風煙。"]', '["絕頂橫臨日，孤峰半倚天。","裴回拜真老，万里见风煙。"]', '诗', 'shi', '', NULL, '登玉清 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15a37290-0aef-4c6b-92c9-97cff61aafa6', '曲池荷', '曲池荷', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["浮香繞曲岸，圓影覆華池。","常恐秋風早，飄零君不知。"]', '["浮香繞曲岸，圓影覆华池。","常恐秋风早，飄零君不知。"]', '诗', 'shi', '', NULL, '曲池荷 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3285c49f-f375-45da-9af5-aaac7b50fefb', '浴浪鳥', '浴浪鸟', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["獨舞依磐石，羣飛動輕浪。","奮迅碧沙前，長懷白雲上。"]', '["独舞依磐石，羣飞动轻浪。","奮迅碧沙前，长懷白云上。"]', '诗', 'shi', '', NULL, '浴浪鳥 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('249420f3-fc9d-4123-a073-595cb15e3e48', '臨階竹', '臨階竹', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["封霜連錦砌，防露拂瑤階。","聊將儀鳳質，暫與俗人諧。"]', '["封霜連錦砌，防露拂瑤階。","聊將儀鳳質，暫與俗人諧。"]', '诗', 'shi', '', NULL, '臨階竹 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0b758f8-94eb-401a-981a-939f5b0ac9e1', '含風蟬', '含风蟬', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["高情臨爽月，急響送秋風。","獨有危冠意，還將衰鬢同。"]', '["高情臨爽月，急响送秋风。","独有危冠意，還將衰鬢同。"]', '诗', 'shi', '', NULL, '含風蟬 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9586bbe6-2570-4388-abef-bef340dca01a', '葮川獨泛', '葮川独泛', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["倚櫂春江上，橫舟石岸前。","山瞑行人斷，迢迢獨泛仙。"]', '["倚櫂春江上，橫舟石岸前。","山瞑行人斷，迢迢独泛仙。"]', '诗', 'shi', '', NULL, '葮川獨泛 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('870a55a5-8d37-4903-810c-6bf02874c7f5', '送二兄入蜀', '送二兄入蜀', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["關山客子路，花柳帝王城。","此中一分手，相顧憐無聲。"]', '["关山客子路，花柳帝王城。","此中一分手，相顧怜無声。"]', '诗', 'shi', '', NULL, '送二兄入蜀 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdae66c6-9f86-45c8-8a5f-d1181052f25b', '宿玄武二首 一', '宿玄武二首 一', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["方池開曉色，圓月下秋陰。","已乘千里興，還撫一弦琴。"]', '["方池开晓色，圓月下秋陰。","已乘千里兴，還撫一弦琴。"]', '诗', 'shi', '', NULL, '宿玄武二首 一 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e763161-1f93-4d8f-bec1-c0d0a9d636c0', '宿玄武二首 二', '宿玄武二首 二', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["庭搖北風柳，院繞南溟禽。","累宿恩方重，窮秋嘆不深。"]', '["庭搖北风柳，院繞南溟禽。","累宿恩方重，窮秋嘆不深。"]', '诗', 'shi', '', NULL, '宿玄武二首 二 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bee511bd-1104-475f-8254-c914e3f70f10', '九隴津集', '九隴津集', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["落落樹陰紫，澄澄水華碧。","復有翻飛禽，裴回疑曳舃。"]', '["落落樹陰紫，澄澄水华碧。","复有翻飞禽，裴回疑曳舃。"]', '诗', 'shi', '', NULL, '九隴津集 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ebaccc6-ae72-4010-98ac-5de8cd9b105c', '遊昌化山精舍', '游昌化山精舍', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["寶地乘峰出，香臺接漢高。","稍覺真途近，方知人事勞。"]', '["寶地乘峰出，香台接漢高。","稍覺真途近，方知人事勞。"]', '诗', 'shi', '', NULL, '遊昌化山精舍 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe1644ee-ec63-43b5-b0df-80496869af64', '登封大酺歌四首 一', '登封大酺歌四首 一', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["明君封禪日重光，天子垂衣曆數長。","九州四海常無事，萬歲千秋樂未央。"]', '["明君封禪日重光，天子垂衣曆數长。","九州四海常無事，万歲千秋乐未央。"]', '诗', 'shi', '', NULL, '登封大酺歌四首 一 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3f2198c-a49f-4f80-9f0b-84f0d10b912a', '登封大酺歌四首 二', '登封大酺歌四首 二', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["日觀仙雲隨鳳輦，天門瑞雪照龍衣。","繁弦綺席方終夜，妙舞清歌歡未歸。"]', '["日观仙云隨鳳輦，天门瑞雪照龙衣。","繁弦綺席方終夜，妙舞清歌歡未归。"]', '诗', 'shi', '', NULL, '登封大酺歌四首 二 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d0e830f-8269-444d-8a86-c5f679ed3b61', '登封大酺歌四首 三', '登封大酺歌四首 三', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["翠鳳逶迤登介丘，仙鶴裴回天上遊。","借問乾封何所樂，人皆壽命得千秋。"]', '["翠鳳逶迤登介丘，仙鹤裴回天上游。","借问乾封何所乐，人皆壽命得千秋。"]', '诗', 'shi', '', NULL, '登封大酺歌四首 三 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9768f5e7-0e92-4e82-a2c2-0a53f4df5f64', '登封大酺歌四首 四', '登封大酺歌四首 四', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["千年聖主應昌期，萬國淳風王化基。","請比上古無爲代，何如今日太平時。"]', '["千年聖主應昌期，万国淳风王化基。","請比上古無爲代，何如今日太平时。"]', '诗', 'shi', '', NULL, '登封大酺歌四首 四 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc1a56cb-8746-4218-84f8-04a685e8c9c3', '九月九日登玄武山', '九月九日登玄武山', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["九月九日眺山川，歸心歸望積風煙。","他鄉共酌金花酒，萬里同悲鴻雁天。"]', '["九月九日眺山川，归心归望積风煙。","他乡共酌金花酒，万里同悲鴻雁天。"]', '诗', 'shi', '', NULL, '九月九日登玄武山 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aa932be-bef9-4847-ab6e-57880e14c166', '句', '句', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["城狐尾獨束，山鬼面參覃。"]', '["城狐尾独束，山鬼面參覃。"]', '诗', 'shi', '', NULL, '句 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7519153-94de-4167-8be6-166f13fa0264', '少年行', '少年行', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["少年飛翠蓋，上路勒金鑣。","始酌文君酒，新吹弄玉簫。","少年不歡樂，何以盡芳朝。","千金笑裏面，一搦掌中腰。","挂纓豈憚宿，落珥不勝嬌。","寄語少年子，無辭歸路遙。"]', '["少年飞翠蓋，上路勒金鑣。","始酌文君酒，新吹弄玉簫。","少年不歡乐，何以尽芳朝。","千金笑裏面，一搦掌中腰。","挂纓豈憚宿，落珥不勝嬌。","寄語少年子，無辞归路遙。"]', '诗', 'shi', '', NULL, '少年行 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94eecb16-1c55-4e84-a824-a885267389d5', '渡漢江', '渡漢江', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["東流既瀰瀰，南紀信滔滔。","水激沈碑岸，波駭弄珠皐。","含星映淺石，浮蓋下奔濤。","溜闊霞光近，川長曉氣高。","檣烏轉輕翼，戲鳥落風毛。","客心既多緒，長歌且代勞。"]', '["东流既瀰瀰，南紀信滔滔。","水激沈碑岸，波駭弄珠皐。","含星映淺石，浮蓋下奔濤。","溜闊霞光近，川长晓氣高。","檣烏轉轻翼，戲鸟落风毛。","客心既多緒，长歌且代勞。"]', '诗', 'shi', '', NULL, '渡漢江 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4542edb4-128e-4216-840a-8503ae4fe03b', '秋晚登古城', '秋晚登古城', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["日落征途遠，悵然臨古城。","頹墉寒雀集，荒堞晚烏驚。","蕭森灌木上，迢遰孤煙生。","霞景煥餘照，露氣澄晚清。","秋風轉搖落，此志安可平。"]', '["日落征途远，悵然臨古城。","頹墉寒雀集，荒堞晚烏驚。","蕭森灌木上，迢遰孤煙生。","霞景煥餘照，露氣澄晚清。","秋风轉搖落，此志安可平。"]', '诗', 'shi', '', NULL, '秋晚登古城 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38dbe298-cd2a-4f2f-b5ed-67b6e481b064', '途中述懷', '途中述懷', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["伯喈遷塞北，亭伯之遼東。","伊余何爲客，獨守雲臺中。","途遙已日暮，時泰道斯窮。","拔心悲岸草，半死落巖桐。","目送衡陽雁，情傷江上楓。","福兮良所伏，今也信難通。","丈夫自有志，寧傷官不公。"]', '["伯喈遷塞北，亭伯之遼东。","伊余何爲客，独守云台中。","途遙已日暮，时泰道斯窮。","拔心悲岸草，半死落巖桐。","目送衡陽雁，情傷江上楓。","福兮良所伏，今也信难通。","丈夫自有志，寧傷官不公。"]', '诗', 'shi', '', NULL, '途中述懷 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84560524-af19-4281-b978-2ab24a4ef50b', '郢城懷古', '郢城懷古', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["客心悲暮序，登墉瞰平陸。","林澤窅芊緜，山川鬱重複。","王公資設險，名都拒江隩。","方城次北門，溟海窮南服。","長策挫吳豕，雄圖競周鹿。","萬乘重沮漳，九鼎輕伊穀。","大蒐雲夢掩，壯觀章華築。","人世更盛衰，吉凶良倚伏。","遽見鄰交斷，仍覩賢臣逐。","南風忽不競，西師日侵蹙。","運圯屬馳驅，時屯恣敲朴。","莫救夷陵火，無復秦庭哭。","鄢郢遂丘墟，風塵俄慘黷。","狐兔時遊踐，霜露日霑沐。","釣渚故池平，神臺層宇覆。","陣雲埋夏首，窮陰慘荒谷。","悵矣舟壑遷，悲哉年祀倏。","雖異三春望，終傷千里目。"]', '["客心悲暮序，登墉瞰平陸。","林澤窅芊緜，山川鬱重複。","王公資設險，名都拒江隩。","方城次北门，溟海窮南服。","长策挫吳豕，雄圖競周鹿。","万乘重沮漳，九鼎轻伊穀。","大蒐云梦掩，壯观章华築。","人世更盛衰，吉凶良倚伏。","遽见鄰交斷，仍覩賢臣逐。","南风忽不競，西師日侵蹙。","運圯屬驰驱，时屯恣敲朴。","莫救夷陵火，無复秦庭哭。","鄢郢遂丘墟，风塵俄慘黷。","狐兔时游踐，霜露日霑沐。","釣渚故池平，神台層宇覆。","陣云埋夏首，窮陰慘荒谷。","悵矣舟壑遷，悲哉年祀倏。","雖異三春望，終傷千里目。"]', '诗', 'shi', '', NULL, '郢城懷古 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b235ba9-ee6b-4670-9ca5-bb522b52a43e', '晚渡江津', '晚渡江津', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["寂寂江山晚，蒼蒼原野暮。","秋氣懷易悲，長波淼難泝。","索索風葉下，離離早鴻度。","丘壑列夕陰，葭菼凝寒霧。","日落亭皐遠，獨此懷歸慕。"]', '["寂寂江山晚，蒼蒼原野暮。","秋氣懷易悲，长波淼难泝。","索索风葉下，離離早鴻度。","丘壑列夕陰，葭菼凝寒霧。","日落亭皐远，独此懷归慕。"]', '诗', 'shi', '', NULL, '晚渡江津 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a057cb3f-9d7a-44ab-8172-cdb3ebfd049a', '王師渡漢水經襄陽', '王師渡漢水經襄陽', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["導漾疏源遠，歸海會流長。","延波接荆夢，通望邇沮漳。","高岸沈碑影，曲漵麗珠光。","雲昏翠島沒，水廣素濤揚。","閱川已多歎，遐睇幾增傷。","臨谿猶駐馬，望峴欲霑裳。","喬木下寒葉，亭林落曉霜。","山公不可遇，誰與訪高陽。"]', '["導漾疏源远，归海會流长。","延波接荆梦，通望邇沮漳。","高岸沈碑影，曲漵丽珠光。","云昏翠島沒，水廣素濤揚。","閱川已多歎，遐睇幾增傷。","臨谿猶駐马，望峴欲霑裳。","喬木下寒葉，亭林落晓霜。","山公不可遇，誰與訪高陽。"]', '诗', 'shi', '', NULL, '王師渡漢水經襄陽 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('887b73ab-b767-4327-8f4b-bce906981116', '謁漢高廟', '謁漢高廟', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["纂堯靈命啓，滅楚餘閏終。","飛名膺帝籙，沈迹韞神功。","瑞氣朝浮碭，祥符夜告豐。","抑揚駕人傑，叱咤掩時雄。","締構三靈改，經綸五緯同。","干戈革宇內，聲教盡寰中。","運謝年逾遠，魂歸道未窮。","樹碑留故邑，抗殿表祠宮。","沐蘭祈泗上，謁帝動深衷。","英威肅如在，文物杳成空。","竹皮聚寒徑，枌社落霜叢。","蕭索陰雲晚，長川起大風。"]', '["纂堯靈命啓，滅楚餘閏終。","飞名膺帝籙，沈迹韞神功。","瑞氣朝浮碭，祥符夜告豐。","抑揚駕人傑，叱咤掩时雄。","締構三靈改，經綸五緯同。","干戈革宇內，声教尽寰中。","運謝年逾远，魂归道未窮。","樹碑留故邑，抗殿表祠宮。","沐蘭祈泗上，謁帝动深衷。","英威肅如在，文物杳成空。","竹皮聚寒徑，枌社落霜叢。","蕭索陰云晚，长川起大风。"]', '诗', 'shi', '', NULL, '謁漢高廟 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e82ca232-9a56-4a68-acaa-b6e622fe2777', '登葉縣故城謁沈諸梁廟', '登葉縣故城謁沈諸梁廟', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["總轡臨秋原，登城望寒日。","煙霞共掩映，林野俱蕭瑟。","楚塞鬱不窮，吳山高漸出。","客行殊未已，沐澡期終吉。","椒桂奠芳樽，風雲下虛室。","館宇肅而靜，神心康且逸。","伊我非真龍，勿驚疲朽質。"]', '["總轡臨秋原，登城望寒日。","煙霞共掩映，林野俱蕭瑟。","楚塞鬱不窮，吳山高漸出。","客行殊未已，沐澡期終吉。","椒桂奠芳樽，风云下虛室。","館宇肅而静，神心康且逸。","伊我非真龙，勿驚疲朽質。"]', '诗', 'shi', '', NULL, '登葉縣故城謁沈諸梁廟 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('409125e2-cc6b-41d3-95c2-8a8522724c16', '安德山池宴集', '安德山池宴集', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["朝宰論思暇，高宴臨方塘。","雲飛鳳臺管，風動令君香。","細草開金埒，流霞泛羽觴。","虹橋分水態，鏡石引菱光。","上才同振藻，小技謬連章。","懷音自蘭室，徐步返山莊。"]', '["朝宰論思暇，高宴臨方塘。","云飞鳳台管，风动令君香。","細草开金埒，流霞泛羽觴。","虹橋分水態，镜石引菱光。","上才同振藻，小技謬連章。","懷音自蘭室，徐步返山莊。"]', '诗', 'shi', '', NULL, '安德山池宴集 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae1dbbdd-01aa-4492-9c49-d64235c4c9ec', '和許侍郎遊昆明池', '和許侍郎游昆明池', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["神池望不極，滄波接遠天。","儀星似河漢，落景類虞泉。","年深平館宇，道泰偃戈船。","差池下鳧雁，掩映生雲煙。","浪花開已合，風文直且連。","稅馬金堤外，橫舟石岸前。","羽觴傾綠蟻，飛日落紅鮮。","積水浮深智，明珠曜雅篇。","大鯨方遠擊，沈灰獨未然。","知君嘯儔侶，短翮徒聯翩。"]', '["神池望不極，滄波接远天。","儀星似河漢，落景類虞泉。","年深平館宇，道泰偃戈船。","差池下鳧雁，掩映生云煙。","浪花开已合，风文直且連。","稅马金堤外，橫舟石岸前。","羽觴傾綠蟻，飞日落紅鲜。","積水浮深智，明珠曜雅篇。","大鯨方远擊，沈灰独未然。","知君嘯儔侶，短翮徒聯翩。"]', '诗', 'shi', '', NULL, '和許侍郎遊昆明池 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('490cf518-c296-44a6-b651-41e12e243ce6', '賦得魏都', '賦得魏都', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["炎運精華歇，清都寶命開。","帝里三方盛，王庭萬國來。","玄武疏遙磴，金鳳上層臺。","乍進仙童藥，時傾避暑杯。","南館招奇士，西園引上才。","還惜劉公幹，疲病清漳隈。"]', '["炎運精华歇，清都寶命开。","帝里三方盛，王庭万国来。","玄武疏遙磴，金鳳上層台。","乍進仙童藥，时傾避暑杯。","南館招奇士，西园引上才。","還惜劉公幹，疲病清漳隈。"]', '诗', 'shi', '', NULL, '賦得魏都 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35ec6317-7b10-493a-8ef1-6e30d096e624', '賦禮記', '賦禮記', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["玉帛資王會，郊丘叶聖情。","重廣開環堵，至道軼金籝。","盤薄依厚地，遙裔騰太清。","方悅升中禮，足以慰餘生。"]', '["玉帛資王會，郊丘叶聖情。","重廣开环堵，至道軼金籝。","盤薄依厚地，遙裔腾太清。","方悅升中禮，足以慰餘生。"]', '诗', 'shi', '', NULL, '賦禮記 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('509191f0-423b-44b6-b067-176c951d0f10', '奉和正日臨朝應詔', '奉和正日臨朝應詔', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["化曆昭唐典，承天順夏正。","百靈警朝禁，三辰揚斾旌。","充庭富禮樂，高讌齒簪纓。","獻壽符萬歲，移風韻九成。"]', '["化曆昭唐典，承天順夏正。","百靈警朝禁，三辰揚斾旌。","充庭富禮乐，高讌齒簪纓。","獻壽符万歲，移风韻九成。"]', '诗', 'shi', '', NULL, '奉和正日臨朝應詔 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63f091c8-9253-4604-8f58-3cb055332d77', '妾薄命', '妾薄命', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["團扇秋風起，長門夜月明。","羞聞拊背入，恨說舞腰輕。","太常先已醉，劉君恆帶酲。","橫陳每虛設，吉夢竟何成。"]', '["團扇秋风起，长门夜月明。","羞闻拊背入，恨说舞腰轻。","太常先已醉，劉君恆带酲。","橫陳每虛設，吉梦竟何成。"]', '诗', 'shi', '', NULL, '妾薄命 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f9f2087-9511-454f-b199-d3b367b29eaf', '火鳳詞二首 一', '火鳳词二首 一', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["歌聲扇後出，妝影鏡中輕。","未能令掩笑，何處欲障聲。","知音自不惑，得念是分明。","莫見雙嚬歛，疑人含笑情。"]', '["歌声扇後出，妝影镜中轻。","未能令掩笑，何处欲障声。","知音自不惑，得念是分明。","莫见雙嚬歛，疑人含笑情。"]', '诗', 'shi', '', NULL, '火鳳詞二首 一 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('508aa87e-4cf7-4a4a-903d-07ea38b4c51c', '火鳳詞二首 二', '火鳳词二首 二', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["佳人靚晚妝，清唱動蘭房。","影出含風扇，聲飛照日梁。","嬌嚬眉際歛，逸韻口中香。","自有橫陳會，應憐秋夜長。"]', '["佳人靚晚妝，清唱动蘭房。","影出含风扇，声飞照日梁。","嬌嚬眉際歛，逸韻口中香。","自有橫陳會，應怜秋夜长。"]', '诗', 'shi', '', NULL, '火鳳詞二首 二 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e53765b3-84fe-4028-bd32-1c46d7ed7052', '奉和初春出遊應令', '奉和初春出游應令', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["鳴笳出望苑，飛蓋下芝田。","水光浮落照，霞彩淡輕煙。","柳色迎三月，梅花隔二年。","日斜歸騎動，餘興滿山川。"]', '["鳴笳出望苑，飞蓋下芝田。","水光浮落照，霞彩淡轻煙。","柳色迎三月，梅花隔二年。","日斜归騎动，餘兴满山川。"]', '诗', 'shi', '', NULL, '奉和初春出遊應令 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b37522f-73a2-48a1-b6c3-43f771353756', '寄楊公', '寄楊公', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["公子盛西京，光華早著名。","分庭接遊士，虛館待時英。","高閣浮香出，長廊寶釧鳴。","面花無隔笑，歌扇不障聲。"]', '["公子盛西京，光华早著名。","分庭接游士，虛館待时英。","高閣浮香出，长廊寶釧鳴。","面花無隔笑，歌扇不障声。"]', '诗', 'shi', '', NULL, '寄楊公 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b935dc2f-43b5-4f83-9ee3-4ec5211c588e', '戲贈潘徐城門迎兩新婦', '戲贈潘徐城门迎兩新婦', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["秦晉稱舊匹，潘徐有世親。","三星宿已會，四德婉而嬪。","霞光鬢裏薄，月影扇中新。","年華與妝面，共作一芳春。"]', '["秦晉稱旧匹，潘徐有世親。","三星宿已會，四德婉而嬪。","霞光鬢裏薄，月影扇中新。","年华與妝面，共作一芳春。"]', '诗', 'shi', '', NULL, '戲贈潘徐城門迎兩新婦 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0519561c-3d1e-45c7-b4b2-98441aebe8a2', '送別', '送別', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["眷言一杯酒，悽愴起離憂。","夜花飄露氣，暗水急還流。","雁行遙上月，蟲聲迥映秋。","明日河梁上，誰與論仙舟。"]', '["眷言一杯酒，悽愴起離憂。","夜花飄露氣，暗水急還流。","雁行遙上月，蟲声迥映秋。","明日河梁上，誰與論仙舟。"]', '诗', 'shi', '', NULL, '送別 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('127c095a-7497-4325-a7c5-f1f6e3407af2', '雨後', '雨後', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["晚來風景麗，晴初物色華。","薄雲向空盡，輕虹逐望斜。","後窗臨岸竹，前階枕浦沙。","寂寥無與晤，尊酒論風花。"]', '["晚来风景丽，晴初物色华。","薄云向空尽，轻虹逐望斜。","後窗臨岸竹，前階枕浦沙。","寂寥無與晤，尊酒論风花。"]', '诗', 'shi', '', NULL, '雨後 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16d5478a-d7b1-427b-8e6b-28f2d47d8fc7', '文德皇后挽歌', '文德皇后挽歌', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["裴回兩儀殿，悵望九成臺。","玉輦終辭宴，瑤筐遂不開。","野曠陰風積，川長思鳥來。","寒山寂已暮，虞殯有餘哀。"]', '["裴回兩儀殿，悵望九成台。","玉輦終辞宴，瑤筐遂不开。","野曠陰风積，川长思鸟来。","寒山寂已暮，虞殯有餘哀。"]', '诗', 'shi', '', NULL, '文德皇后挽歌 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f291438-5f13-449c-a049-b9e02cfe50b8', '詠蟬', '詠蟬', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["清心自飲露，哀響乍吟風。","未上華冠側，先驚翳葉中。"]', '["清心自饮露，哀响乍吟风。","未上华冠側，先驚翳葉中。"]', '诗', 'shi', '', NULL, '詠蟬 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96c16098-4513-4a47-99f4-477de55b5244', '詠螢火示情人', '詠螢火示情人', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["窗裏憐燈暗，階前畏月明。","不辭逢露溼，祗爲重宵行。"]', '["窗裏怜灯暗，階前畏月明。","不辞逢露溼，祗爲重宵行。"]', '诗', 'shi', '', NULL, '詠螢火示情人 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68342232-1a39-4c2b-979a-8d7dda75bff3', '春眺', '春眺', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["疲痾荷拙患，淪躓合幽襟。","栖息在何處？丘中鳴素琴。"]', '["疲痾荷拙患，淪躓合幽襟。","栖息在何处？丘中鳴素琴。"]', '诗', 'shi', '', NULL, '春眺 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e32e21ed-d6c6-4512-a45f-8dc1ef05f415', '句', '句', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["今日持團扇，非是爲秋風。"]', '["今日持團扇，非是爲秋风。"]', '诗', 'shi', '', NULL, '句 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('272e70ae-7357-4c26-bfed-6e16de2d59fe', '奉和太子納妃太平公主出降', '奉和太子納妃太平公主出降', 'b54c67e8-8e16-4f1e-8c02-7dc607e5c9b7', '唐', '["夢梓光青陛，穠桃藹紫宮。","德優宸念遠，禮備國姻崇。","萬戶聲明發，三條騎吹通。","香輪送重景，綵斾引仙虹。"]', '["梦梓光青陛，穠桃藹紫宮。","德優宸念远，禮備国姻崇。","万戶声明發，三條騎吹通。","香輪送重景，綵斾引仙虹。"]', '诗', 'shi', '', NULL, '奉和太子納妃太平公主出降 劉禕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd8ddf29-7238-467a-a4fd-f7dad1520b24', '奉和別越王', '奉和別越王', 'b54c67e8-8e16-4f1e-8c02-7dc607e5c9b7', '唐', '["周屏辭金殿，梁驂整玉珂。","管聲依折柳，琴韻動流波。","鶴蓋分陰促，龍軒別念多。","延襟小山路，還起大風歌。"]', '["周屏辞金殿，梁驂整玉珂。","管声依折柳，琴韻动流波。","鹤蓋分陰促，龙軒別念多。","延襟小山路，還起大风歌。"]', '诗', 'shi', '', NULL, '奉和別越王 劉禕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5fe28f5-9e56-472f-aef4-1bb7f6ff27d9', '酬鄭沁州', '酬鄭沁州', 'b54c67e8-8e16-4f1e-8c02-7dc607e5c9b7', '唐', '["麒閣一代良，熊軒千里躅。","緝圖昭國典，按部留宸矚。","匪厭承明廬，佇兼司隸局。","芸書暫輟載，竹使方臨俗。","節變風緒高，秋深露華溽。","寒山斂輕靄，霽野澄初旭。","已切長年悲，誰堪岐路促。","遙林征馬迅，別館嘶驂跼。","雅贈響摐金，索居暌倚玉。","悽斷離鴻引，勞歌思足曲。"]', '["麒閣一代良，熊軒千里躅。","緝圖昭国典，按部留宸矚。","匪厭承明廬，佇兼司隸局。","芸书暫輟載，竹使方臨俗。","節变风緒高，秋深露华溽。","寒山斂轻靄，霽野澄初旭。","已切长年悲，誰堪岐路促。","遙林征马迅，別館嘶驂跼。","雅贈响摐金，索居暌倚玉。","悽斷離鴻引，勞歌思足曲。"]', '诗', 'shi', '', NULL, '酬鄭沁州 劉禕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9004484b-473f-48dd-862d-0c56bbffa8d3', '孝敬皇帝挽歌', '孝敬皇帝挽歌', 'b54c67e8-8e16-4f1e-8c02-7dc607e5c9b7', '唐', '["戒奢虛蜃輅，錫號紀鴻名。","地叶蒼梧野，途經紫聚城。","重照掩寒色，晨飆斷曙聲。","一隨仙驥遠，霜雪愁陰生。"]', '["戒奢虛蜃輅，錫號紀鴻名。","地叶蒼梧野，途經紫聚城。","重照掩寒色，晨飆斷曙声。","一隨仙驥远，霜雪愁陰生。"]', '诗', 'shi', '', NULL, '孝敬皇帝挽歌 劉禕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a4f65f1-a96e-4257-9c0f-7e048aee3ac9', '九成宮秋初應詔', '九成宮秋初應詔', 'b54c67e8-8e16-4f1e-8c02-7dc607e5c9b7', '唐', '["帝圃疏金闕，仙臺駐玉鑾。","野分鳴鸑岫，路接寶雞壇。","林樹千霜積，山宮四序寒。","蟬急知秋早，鶯疎覺夏闌。","怡神紫氣外，凝睇白雲端。","舜海詞波發，空驚遊聖難。"]', '["帝圃疏金闕，仙台駐玉鑾。","野分鳴鸑岫，路接寶雞壇。","林樹千霜積，山宮四序寒。","蟬急知秋早，鶯疎覺夏闌。","怡神紫氣外，凝睇白云端。","舜海词波發，空驚游聖难。"]', '诗', 'shi', '', NULL, '九成宮秋初應詔 劉禕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9555fe3-1f41-4015-bade-c616a78e1079', '奉和別魯王', '奉和別魯王', 'c2853ffc-a5d7-4e86-85c2-6911da4d4df9', '唐', '["綠車旋楚服，丹蹕佇秦川。","珠皐轉歸騎，金岸引行旃。","一朝限原隰，千里間風煙。","鶯喧上林谷，鳧響御溝泉。","斷雲移魯蓋，離歌動舜弦。","別念凝神扆，崇恩洽玳筵。","顧惟慙叩寂，徒自仰鈞天。"]', '["綠车旋楚服，丹蹕佇秦川。","珠皐轉归騎，金岸引行旃。","一朝限原隰，千里间风煙。","鶯喧上林谷，鳧响御溝泉。","斷云移魯蓋，離歌动舜弦。","別念凝神扆，崇恩洽玳筵。","顧惟慙叩寂，徒自仰鈞天。"]', '诗', 'shi', '', NULL, '奉和別魯王 李敬玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9e86ab3-fe2e-4fc7-a063-ae784d77948e', '奉和別越王', '奉和別越王', 'c2853ffc-a5d7-4e86-85c2-6911da4d4df9', '唐', '["飛蓋迴蘭坂，宸襟佇柏梁。","別館分涇渭，歸路指衡漳。","關山通曙色，林籞徧春光。","帝念紆千里，詞波照五潢。"]', '["飞蓋迴蘭坂，宸襟佇柏梁。","別館分涇渭，归路指衡漳。","关山通曙色，林籞徧春光。","帝念紆千里，词波照五潢。"]', '诗', 'shi', '', NULL, '奉和別越王 李敬玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed717515-0b8b-44ba-a5c7-491867608b51', '奉和別越王', '奉和別越王', 'f0509d15-c9b5-4855-829d-fd8379575c0e', '唐', '["盛藩資右戚，連蕚重皇情。","離襟愴睢苑，分途指鄴城。","麗日開芳甸，佳氣積神京。","何時驂駕入，還見謁承明。"]', '["盛藩資右戚，連蕚重皇情。","離襟愴睢苑，分途指鄴城。","丽日开芳甸，佳氣積神京。","何时驂駕入，還见謁承明。"]', '诗', 'shi', '', NULL, '奉和別越王 張大安 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef1b7dde-5d9c-49fb-8689-472d965c7ee2', '奉和太子納妃太平公主出降', '奉和太子納妃太平公主出降', 'c5fc0375-56fa-450c-aea1-2d6c97535136', '唐', '["象輅初乘鴈，璇宮早結褵。","離元應春夕，帝子降秋期。","鳴瑜合清響，冠玉麗穠姿。","和聲躋鳳掖，交影步鸞墀。"]', '["象輅初乘鴈，璇宮早結褵。","離元應春夕，帝子降秋期。","鳴瑜合清响，冠玉丽穠姿。","和声躋鳳掖，交影步鸾墀。"]', '诗', 'shi', '', NULL, '奉和太子納妃太平公主出降 元萬頃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b760a75-8c4a-41c5-be5b-6e686b4b8c75', '奉和春日池臺', '奉和春日池台', 'c5fc0375-56fa-450c-aea1-2d6c97535136', '唐', '["日影飛花殿，風文積草池。","鳳樓通夜敞，虬輦望春移。"]', '["日影飞花殿，风文積草池。","鳳楼通夜敞，虬輦望春移。"]', '诗', 'shi', '', NULL, '奉和春日池臺 元萬頃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d693186e-aedb-4ff9-b542-930f0411d3fb', '奉和春日二首 一', '奉和春日二首 一', 'c5fc0375-56fa-450c-aea1-2d6c97535136', '唐', '["花輕蘂亂仙人杏，葉密鶯喧帝女桑。","飛雲閣上春應至，明月樓中夜未央。"]', '["花轻蘂亂仙人杏，葉密鶯喧帝女桑。","飞云閣上春應至，明月楼中夜未央。"]', '诗', 'shi', '', NULL, '奉和春日二首 一 元萬頃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c76de463-4f2f-4fb9-bd49-87679461a7d0', '奉和春日二首 二', '奉和春日二首 二', 'c5fc0375-56fa-450c-aea1-2d6c97535136', '唐', '["鳳輦迎風乘紫閣，鸞車避日轉彤闈。","中堂促管淹春望，後殿清歌開夜扉。"]', '["鳳輦迎风乘紫閣，鸾车避日轉彤闈。","中堂促管淹春望，後殿清歌开夜扉。"]', '诗', 'shi', '', NULL, '奉和春日二首 二 元萬頃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1af0e0c-8e7a-411b-a2f3-9b22858ccb77', '奉和太子納妃太平公主出降', '奉和太子納妃太平公主出降', 'b7fb2eb7-6cc2-4873-a513-42f56bbf50e4', '唐', '["桂宮初服冕，蘭掖早升筓。","禮盛親迎晉，聲芬出降齊。","金龜開瑞鈕，寶翟上仙袿。","轉扇承宵月，揚旌照夕蜺。"]', '["桂宮初服冕，蘭掖早升筓。","禮盛親迎晉，声芬出降齊。","金龟开瑞鈕，寶翟上仙袿。","轉扇承宵月，揚旌照夕蜺。"]', '诗', 'shi', '', NULL, '奉和太子納妃太平公主出降 郭正一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9381d96-cea0-40cc-a3f0-99582b2323d3', '奉和太子納妃太平公主出降三首 一', '奉和太子納妃太平公主出降三首 一', '08e71476-743b-4044-9dc4-2c0e226b6c5a', '唐', '["帝子威儀絕，儲妃禮度優。","疊鼓陪仙觀，凝笳翼畫輈。","鬱鬱神香滿，奕奕彩雲浮。","排空列錦罽，騰歡溢皇州。"]', '["帝子威儀絕，儲妃禮度優。","叠鼓陪仙观，凝笳翼畫輈。","鬱鬱神香满，奕奕彩云浮。","排空列錦罽，腾歡溢皇州。"]', '诗', 'shi', '', NULL, '奉和太子納妃太平公主出降三首 一 胡元範 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4388e401-f0ac-441b-aa30-6d15ef6ff41c', '奉和太子納妃太平公主出降三首 二', '奉和太子納妃太平公主出降三首 二', '08e71476-743b-4044-9dc4-2c0e226b6c5a', '唐', '["金閨未息火，玉樹鍾天愛。","月路飾還裝，星津動歸佩。","紫極流宸渥，清規佇慈誨。","恩波洽九流，光輝軼千載。"]', '["金閨未息火，玉樹鍾天愛。","月路飾還裝，星津动归佩。","紫極流宸渥，清規佇慈誨。","恩波洽九流，光輝軼千載。"]', '诗', 'shi', '', NULL, '奉和太子納妃太平公主出降三首 二 胡元範 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b18b21c-9fe3-47e6-ab69-858602883e56', '奉和太子納妃太平公主出降三首 三', '奉和太子納妃太平公主出降三首 三', '08e71476-743b-4044-9dc4-2c0e226b6c5a', '唐', '["列席詔親賢，式宴坐神仙。","聖文飛聖筆，天樂奏鈞天。","曲池涵瑞景，文宇孕祥煙。","小臣同百獸，率舞悅堯年。"]', '["列席詔親賢，式宴坐神仙。","聖文飞聖笔，天乐奏鈞天。","曲池涵瑞景，文宇孕祥煙。","小臣同百獸，率舞悅堯年。"]', '诗', 'shi', '', NULL, '奉和太子納妃太平公主出降三首 三 胡元範 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff9bd7ac-738b-429b-ab14-95a38f0f585c', '奉和太子納妃太平公主出降', '奉和太子納妃太平公主出降', 'a5180785-2195-4bda-a302-e8185f1ff1be', '唐', '["帝子陞青陛，王姬降紫宸。","星光移雜珮，月彩薦重輪。","龍旌翻地杪，鳳管颺天濱。","槐陰浮淺瀨，葆吹翼輕塵。"]', '["帝子陞青陛，王姬降紫宸。","星光移杂珮，月彩薦重輪。","龙旌翻地杪，鳳管颺天濱。","槐陰浮淺瀨，葆吹翼轻塵。"]', '诗', 'shi', '', NULL, '奉和太子納妃太平公主出降 任希古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('939e0995-4c5d-4af7-9f47-3c1ae9875797', '和東觀羣賢七夕臨泛昆明池', '和东观羣賢七夕臨泛昆明池', 'a5180785-2195-4bda-a302-e8185f1ff1be', '唐', '["秋風始搖落，秋水正澄鮮。","飛眺牽牛渚，激賞鏤鯨川。","岸珠淪曉魄，池灰斂曙煙。","泛查分寫漢，儀星別搆天。","雲光波處動，日影浪中懸。","驚鴻絓蒲弋，遊鯉入莊筌。","萍葉疑江上，菱花似鏡前。","長林代輕幄，細草即芳筵。","文峰開翠瀲，筆海控清漣。","不挹蘭樽聖，空仰桂舟仙。"]', '["秋风始搖落，秋水正澄鲜。","飞眺牽牛渚，激賞鏤鯨川。","岸珠淪晓魄，池灰斂曙煙。","泛查分寫漢，儀星別搆天。","云光波处动，日影浪中懸。","驚鴻絓蒲弋，游鯉入莊筌。","萍葉疑江上，菱花似镜前。","长林代轻幄，細草即芳筵。","文峰开翠瀲，笔海控清漣。","不挹蘭樽聖，空仰桂舟仙。"]', '诗', 'shi', '', NULL, '和東觀羣賢七夕臨泛昆明池 任希古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('150c11df-3192-4d8e-84af-4aec7dd77da7', '和左僕射燕公春日端居述懷', '和左僕射燕公春日端居述懷', 'a5180785-2195-4bda-a302-e8185f1ff1be', '唐', '["豐野光三傑，嬀庭贊五臣。","綈緗歌美譽，絲竹詠芳塵。","聖曆開環象，昌年降甫申。","高門非捨築，華構豈垂綸。","鳳邸摶霄翰，龍池躍海鱗。","玉鼎昇黃閣，金章謁紫宸。","禮闈通政本，文昌總國均。","調風振薄俗，清教敘彝倫。","星迴應緹管，日御警寅賓。","葉上曾槐變，花發小堂春。","思挂五都冕，言訪北山巾。","赫赫容臺上，千祀耀平津。"]', '["豐野光三傑，嬀庭贊五臣。","綈緗歌美譽，絲竹詠芳塵。","聖曆开环象，昌年降甫申。","高门非捨築，华構豈垂綸。","鳳邸摶霄翰，龙池躍海鱗。","玉鼎昇黄閣，金章謁紫宸。","禮闈通政本，文昌總国均。","調风振薄俗，清教敘彝倫。","星迴應緹管，日御警寅賓。","葉上曾槐变，花發小堂春。","思挂五都冕，言訪北山巾。","赫赫容台上，千祀耀平津。"]', '诗', 'shi', '', NULL, '和左僕射燕公春日端居述懷 任希古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d46997eb-d100-4f71-94dc-3701e22d91c8', '和長孫祕監伏日苦熱', '和长孫祕監伏日苦熱', 'a5180785-2195-4bda-a302-e8185f1ff1be', '唐', '["玉署三時曉，金羈五日歸。","北林開逸徑，東閣敞閑扉。","池鏡分天色，雲峰減日輝。","游鱗映荷聚，驚翰遶林飛。","披襟[揚]子宅，舒嘯仰重闈。"]', '["玉署三时晓，金羈五日归。","北林开逸徑，东閣敞闲扉。","池镜分天色，云峰減日輝。","游鱗映荷聚，驚翰遶林飞。","披襟[揚]子宅，舒嘯仰重闈。"]', '诗', 'shi', '', NULL, '和長孫祕監伏日苦熱 任希古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdc8c314-14e2-4e5d-a692-70986b3a2a25', '和李公七夕', '和李公七夕', 'a5180785-2195-4bda-a302-e8185f1ff1be', '唐', '["落日照高牖，涼風起庭樹。","悠悠天宇平，昭昭月華度。","開軒卷綃幕，延首晞雲路。","層漢有靈妃，仙居無與晤。","履化悲流易，臨川怨遲暮。","昔從九春徂，方此三秋遇。","瑤駕越星河，羽蓋凝珠露。","便妍耀井色，窈窕凌波步。","始閱故人新，俄見新人故。","掩淚收機石，銜啼襞紈素。","惆悵何傷已，裴回勞永慕。","無由西北歸，空自東南顧。"]', '["落日照高牖，涼风起庭樹。","悠悠天宇平，昭昭月华度。","开軒卷綃幕，延首晞云路。","層漢有靈妃，仙居無與晤。","履化悲流易，臨川怨遲暮。","昔從九春徂，方此三秋遇。","瑤駕越星河，羽蓋凝珠露。","便妍耀井色，窈窕凌波步。","始閱故人新，俄见新人故。","掩泪收機石，銜啼襞紈素。","惆悵何傷已，裴回勞永慕。","無由西北归，空自东南顧。"]', '诗', 'shi', '', NULL, '和李公七夕 任希古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98e0ab67-bf26-46e0-a938-9eada686fa37', '和長孫祕監七夕', '和长孫祕監七夕', 'a5180785-2195-4bda-a302-e8185f1ff1be', '唐', '["二秋叶神媛，七夕望仙妃。","影照河陽妓，色麗平津闈。","鵲橋波裏出，龍車霄外飛。","露泫低珠佩，雲移薦錦衣。","更深黃月落，夜久靨星稀。","空接靈臺下，方恧辨支機。"]', '["二秋叶神媛，七夕望仙妃。","影照河陽妓，色丽平津闈。","鵲橋波裏出，龙车霄外飞。","露泫低珠佩，云移薦錦衣。","更深黄月落，夜久靨星稀。","空接靈台下，方恧辨支機。"]', '诗', 'shi', '', NULL, '和長孫祕監七夕 任希古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61851d55-bb5e-45f0-8d07-4de1987575f7', '奉和太子納妃太平公主出降三首 一', '奉和太子納妃太平公主出降三首 一', 'd5d106b2-8ac0-4fac-a954-897a86934c89', '唐', '["瑜珮升青殿，穠華降紫微。","還如桃李發，更似鳳皇飛。","金屋真離象，瑤臺起婺徽。","綵纓紛碧坐，[繢]羽泛褕衣。"]', '["瑜珮升青殿，穠华降紫微。","還如桃李發，更似鳳皇飞。","金屋真離象，瑤台起婺徽。","綵纓紛碧坐，[繢]羽泛褕衣。"]', '诗', 'shi', '', NULL, '奉和太子納妃太平公主出降三首 一 裴守真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0364f72-dc5b-4561-8822-dcbe5dc310f1', '奉和太子納妃太平公主出降三首 二', '奉和太子納妃太平公主出降三首 二', 'd5d106b2-8ac0-4fac-a954-897a86934c89', '唐', '["雲路移彤輦，天津轉明鏡。","仙珠照乘歸，寶月重輪映。","望園嘉宴洽，主第歡娛盛。","絲竹揚帝熏，簪裾奉宸慶。"]', '["云路移彤輦，天津轉明镜。","仙珠照乘归，寶月重輪映。","望园嘉宴洽，主第歡娛盛。","絲竹揚帝熏，簪裾奉宸慶。"]', '诗', 'shi', '', NULL, '奉和太子納妃太平公主出降三首 二 裴守真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d10771e6-f816-4f50-b4f6-249d338e3178', '奉和太子納妃太平公主出降三首 三', '奉和太子納妃太平公主出降三首 三', 'd5d106b2-8ac0-4fac-a954-897a86934c89', '唐', '["藂雲靄曉光，湛露晞朝陽。","天文天景麗，睿藻睿詞芳。","玉庭散秋色，銀宮生夕涼。","太平超邃古，萬壽樂無疆。"]', '["藂云靄晓光，湛露晞朝陽。","天文天景丽，睿藻睿词芳。","玉庭散秋色，銀宮生夕涼。","太平超邃古，万壽乐無疆。"]', '诗', 'shi', '', NULL, '奉和太子納妃太平公主出降三首 三 裴守真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10a7a237-cb33-495a-bf95-170cde661530', '奉和聖製過溫湯', '奉和聖製過溫湯', '3c8c05b5-68c0-44c6-9a40-09e5ba2afef1', '唐', '["豐城觀漢迹，溫谷幸秦餘。","地接幽王壘，塗分鄭國渠。","風威肅文衛，日彩鏡雕輿。","遠岫凝氛重，寒叢對影疎。","迴瞻漢章闕，佳氣滿宸居。"]', '["豐城观漢迹，溫谷幸秦餘。","地接幽王壘，塗分鄭国渠。","风威肅文衛，日彩镜雕輿。","远岫凝氛重，寒叢对影疎。","迴瞻漢章闕，佳氣满宸居。"]', '诗', 'shi', '', NULL, '奉和聖製過溫湯 楊思玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcd6160c-5b84-4899-bebd-e43cd91ea49b', '奉和別魯王', '奉和別魯王', '3c8c05b5-68c0-44c6-9a40-09e5ba2afef1', '唐', '["元王詩傳博，文后寵靈優。","鶴蓋動宸眷，龍章送遠遊。","函關疏別道，灞岸引行舟。","北林分苑樹，東流溢御溝。","鳥聲含羽碎，騎影曳花浮。","聖澤九垓普，天文七曜周。","方圖獻雅樂，簪帶奉鳴球。"]', '["元王诗傳博，文后寵靈優。","鹤蓋动宸眷，龙章送远游。","函关疏別道，灞岸引行舟。","北林分苑樹，东流溢御溝。","鸟声含羽碎，騎影曳花浮。","聖澤九垓普，天文七曜周。","方圖獻雅乐，簪带奉鳴球。"]', '诗', 'shi', '', NULL, '奉和別魯王 楊思玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfdd75c5-3693-4edb-8f69-9894020e1de4', '奉和聖製過溫湯', '奉和聖製過溫湯', 'fb61bd57-8c2c-456c-a157-159ab8e506b9', '唐', '["握圖開萬宇，屬聖啓千年。","驪阜疏緹騎，驚鴻映綵旃。","玉霜鳴鳳野，金陣藻龍川。","祥煙聚危岫，德水溢飛泉。","停輿興睿覽，還舉大風篇。"]', '["握圖开万宇，屬聖啓千年。","驪阜疏緹騎，驚鴻映綵旃。","玉霜鳴鳳野，金陣藻龙川。","祥煙聚危岫，德水溢飞泉。","停輿兴睿覽，還舉大风篇。"]', '诗', 'shi', '', NULL, '奉和聖製過溫湯 王德真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ded1b93-1e2e-4f09-a407-cbf6edbd64aa', '奉和聖製過溫湯', '奉和聖製過溫湯', '24e65205-9824-4f3e-990c-5e74c3b835ed', '唐', '["洛川方駐蹕，豐野暫停鑾。","湯泉恆獨涌，溫谷豈知寒。","漏鼓依巖畔，相風出樹端。","嶺煙遙聚草，山月迥臨鞍。","日用誠多幸，天文遂仰觀。"]', '["洛川方駐蹕，豐野暫停鑾。","湯泉恆独涌，溫谷豈知寒。","漏鼓依巖畔，相风出樹端。","嶺煙遙聚草，山月迥臨鞍。","日用誠多幸，天文遂仰观。"]', '诗', 'shi', '', NULL, '奉和聖製過溫湯 鄭義真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92681379-cbf2-4c6a-bc7c-b7e807cdccac', '奉和展禮岱宗塗經濮濟', '奉和展禮岱宗塗經濮濟', '99770ec7-ebb5-4f7a-933b-de99813b5a91', '唐', '["拂漢星旗轉，分霄日羽明。","將追會阜跡，更勒岱宗銘。","林戈咽濟岸，獸鼓震河庭。","葉箭凌寒矯，鳥弓望曉驚。","已降汾水作，仍深迎渭情。"]', '["拂漢星旗轉，分霄日羽明。","將追會阜跡，更勒岱宗銘。","林戈咽濟岸，獸鼓震河庭。","葉箭凌寒矯，鸟弓望晓驚。","已降汾水作，仍深迎渭情。"]', '诗', 'shi', '', NULL, '奉和展禮岱宗塗經濮濟 蕭楚材 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b96312f4-ef5f-41aa-86fa-488e23c8f5ce', '奉和展禮岱宗塗經濮濟', '奉和展禮岱宗塗經濮濟', '95e26ce3-82a1-4dda-b7d1-2b1043c3eb5a', '唐', '["龍圖冠胥陸，鳳駕指云亭。","非煙泛濟浦，綠字啓河汀。","畫裳晨應月，文戟曙分星。","四田巡揖禮，三驅道契經。","行欣奉萬歲，竊抃偶千齡。"]', '["龙圖冠胥陸，鳳駕指云亭。","非煙泛濟浦，綠字啓河汀。","畫裳晨應月，文戟曙分星。","四田巡揖禮，三驱道契經。","行欣奉万歲，竊抃偶千齡。"]', '诗', 'shi', '', NULL, '奉和展禮岱宗塗經濮濟 薛克構 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13841a18-9cc4-4482-9aee-64c944898e64', '日暮望涇水', '日暮望涇水', 'cc57566e-0a3c-400b-90ca-f3456d1e9904', '唐', '["導源徑隴阪，屬汭貫嬴都。","下瀨波常急，迴圻溜亦紆。","毒流秦卒斃，泥糞漢田腴。","獨有迷津客，懷歸軫暮途。"]', '["導源徑隴阪，屬汭貫嬴都。","下瀨波常急，迴圻溜亦紆。","毒流秦卒斃，泥糞漢田腴。","独有迷津客，懷归軫暮途。"]', '诗', 'shi', '', NULL, '日暮望涇水 徐珩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4e13367-9756-4efa-8c1f-fc3b2231aad2', '贈韓思彥', '贈韓思彥', 'c39306a8-9913-4af8-bb9b-69158b68813c', '唐', '["意氣百年內，平生一寸心。","欲交天下士，未面已虛襟。","君子重名義，直道冠衣簪。","風雲行可託，懷抱自然深。","落霞靜霜景，墜葉下風林。","若上南登岸，希訪北山岑。"]', '["意氣百年內，平生一寸心。","欲交天下士，未面已虛襟。","君子重名義，直道冠衣簪。","风云行可託，懷抱自然深。","落霞静霜景，墜葉下风林。","若上南登岸，希訪北山岑。"]', '诗', 'shi', '', NULL, '贈韓思彥 賀遂亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0b9d1cc-80ba-4807-a6c2-27836a34ed63', '酬賀遂亮', '酬賀遂亮', 'fee7b6de-02fb-49a0-baba-f46d1e1c0bdc', '唐', '["古人一言重，嘗謂百年輕。","今投歡會面，顧盼盡平生。","簪裾非所託，琴酒冀相倂。","累日同游處，通宵欵素誠。","霜飄知柳脆，雪冒覺松貞。","願言何所道，幸得歲寒名。"]', '["古人一言重，嘗謂百年轻。","今投歡會面，顧盼尽平生。","簪裾非所託，琴酒冀相倂。","累日同游处，通宵欵素誠。","霜飄知柳脆，雪冒覺松貞。","願言何所道，幸得歲寒名。"]', '诗', 'shi', '', NULL, '酬賀遂亮 韓思彥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84794959-5249-4c3d-9cda-18ae875322b2', '自御史左授山陽丞', '自御史左授山陽丞', 'd110abad-45b7-4f32-8c50-6ac7a898008c', '唐', '["朝昇照日檻，夕次下烏臺。","風竿一眇邈，月樹幾裴回。","翼向高標斂，聲隨下調哀。","懷燕首自白，非是爲年催。"]', '["朝昇照日檻，夕次下烏台。","风竿一眇邈，月樹幾裴回。","翼向高標斂，声隨下調哀。","懷燕首自白，非是爲年催。"]', '诗', 'shi', '', NULL, '自御史左授山陽丞 魏求己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e18429f0-43d1-4097-9f91-faf926c4a647', '贈右臺監察鄧茂遷左臺殿中', '贈右台監察鄧茂遷左台殿中', 'b1e687e7-5e01-42bc-bd36-f4c55e643618', '唐', '["惟昔參多士，無雙仰異才。","鷹鸇同效逐，鵷鷺忝游陪。","入仕光三命，遷榮歷二臺。","隔牆欽素躅，對問限清埃。","紫署春光早，蘭闈曙色催。","誰言夕鳥至，空想鄧林隈。"]', '["惟昔參多士，無雙仰異才。","鷹鸇同效逐，鵷鷺忝游陪。","入仕光三命，遷榮歷二台。","隔牆欽素躅，对问限清埃。","紫署春光早，蘭闈曙色催。","誰言夕鸟至，空想鄧林隈。"]', '诗', 'shi', '', NULL, '贈右臺監察鄧茂遷左臺殿中 劉懷一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc80ffc7-f17e-446a-85d9-56aed2155a49', '湘川新曲二首 一', '湘川新曲二首 一', 'eaf529fc-90b8-430a-847f-a4435a712301', '唐', '["昭潭深無底，橘洲淺而浮。","本欲凌波去，翻爲目成留。","願君稍弭檝，無令賤妾羞。"]', '["昭潭深無底，橘洲淺而浮。","本欲凌波去，翻爲目成留。","願君稍弭檝，無令賤妾羞。"]', '诗', 'shi', '', NULL, '湘川新曲二首 一 杜易簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2801b9b-c753-467c-8ef3-6de9a96d6705', '湘川新曲二首 二', '湘川新曲二首 二', 'eaf529fc-90b8-430a-847f-a4435a712301', '唐', '["二八相招攜，采菱渡前谿。","弱腕隨橈起，纖腰向舸低。","自解看花笑，憎聞染竹啼。"]', '["二八相招携，采菱渡前谿。","弱腕隨橈起，纖腰向舸低。","自解看花笑，憎闻染竹啼。"]', '诗', 'shi', '', NULL, '湘川新曲二首 二 杜易簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3faf3410-28f6-457f-abf4-d16336cce25e', '落成會詠一首', '落成會詠一首', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["泉潮天萬里，一鎮屹天中。","筮宅龍鍾地，承恩燕翼宮。","環堂巍嶽秀，帶礪大江雄。","輪奐雲霄望，晶華日月通。","凌煙喬木茂，獻寶介圭崇。","昆俊歌常棣，民和教即戎。","盤庚遷美士，陶侃效兼庸。","設醴延張老，開軒禮呂蒙。","無孤南國仰，庶補聖皇功。"]', '["泉潮天万里，一鎮屹天中。","筮宅龙鍾地，承恩燕翼宮。","环堂巍嶽秀，带礪大江雄。","輪奐云霄望，晶华日月通。","凌煙喬木茂，獻寶介圭崇。","昆俊歌常棣，民和教即戎。","盤庚遷美士，陶侃效兼庸。","設醴延張老，开軒禮呂蒙。","無孤南国仰，庶補聖皇功。"]', '诗', 'shi', '', NULL, '落成會詠一首 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('041f5266-023d-424a-852c-9e92f3b4061d', '示珦', '示珦', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["恩銜楓陛渥，策向桂淵弘。","載筆沿儒習，持弓纘祖風。","祛災勦猛虎，溥德翊飛龍。","日閱書開士，星言駕勸農。","勤勞思命重，戲謔逐時空。","百粵霧紛滿，諸戎澤普通。","願言加壯努，勿坐鬢霜蓬。"]', '["恩銜楓陛渥，策向桂淵弘。","載笔沿儒習，持弓纘祖风。","祛災勦猛虎，溥德翊飞龙。","日閱书开士，星言駕勸農。","勤勞思命重，戲謔逐时空。","百粵霧紛满，諸戎澤普通。","願言加壯努，勿坐鬢霜蓬。"]', '诗', 'shi', '', NULL, '示珦 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2cdd49e-e29f-4f4e-b1ca-cbf2165b2ccd', '太母魏氏半徑題石', '太母魏氏半徑題石', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["喬岳標仙蹟，玄扃妥壽姬。","烏號非嶺海，鶴仰向京師。","繫牒公侯裔，懸弧將相兒。","清貞蜚簡籍，規範肅門楣。","萬里提兵路，三年報母慈。","劒埋龍守壤，石臥虎司碑。","憂闋情猶結，祥回禫屆期。","竹符忠介凜，桐杖孝思淒。","許史峋嶙篆，曹侯感舊詩。","鴻濛山暝啓，駿彩德昭垂。","華表瑤池冥，清漳玉樹枝。","昭題盟岳瀆，展墓慶重熙。"]', '["喬岳標仙蹟，玄扃妥壽姬。","烏號非嶺海，鹤仰向京師。","繫牒公侯裔，懸弧將相兒。","清貞蜚簡籍，規範肅门楣。","万里提兵路，三年報母慈。","劒埋龙守壤，石臥虎司碑。","憂闋情猶結，祥回禫屆期。","竹符忠介凜，桐杖孝思淒。","許史峋嶙篆，曹侯感旧诗。","鴻濛山暝啓，駿彩德昭垂。","华表瑤池冥，清漳玉樹枝。","昭題盟岳瀆，展墓慶重熙。"]', '诗', 'shi', '', NULL, '太母魏氏半徑題石 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42f3a3f0-9d0d-467e-848c-8a0fe4f255bc', '和陳元光平潮寇詩', '和陳元光平潮寇诗', 'b5da9639-f470-4e95-ab23-614730d84454', '唐', '["抱磴從天上，驅車返嶺東。","氣昂無醜虜，策妙詘羣雄。","飛絮隨風散，餘氛響日鎔。","長戈收百甲，聚騎破千重。","落劒惟戎首，游繩繫脅從。","四野無堅壁，羣生未化融。","龍湖膏澤下，早晚徧枯窮。"]', '["抱磴從天上，驱车返嶺东。","氣昂無醜虜，策妙詘羣雄。","飞絮隨风散，餘氛响日鎔。","长戈收百甲，聚騎破千重。","落劒惟戎首，游繩繫脅從。","四野無堅壁，羣生未化融。","龙湖膏澤下，早晚徧枯窮。"]', '诗', 'shi', '', NULL, '和陳元光平潮寇詩 許天正 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab366c63-b6ce-4210-82f4-6f4c2621135e', '詠牛應制', '詠牛應制', '5eef6e65-e05e-4802-a193-3b30dac2fbd1', '唐', '["逸足還同驥，奇毛自偶麟。","欲知花跡遠，雲影入天津。"]', '["逸足還同驥，奇毛自偶麟。","欲知花跡远，云影入天津。"]', '诗', 'shi', '', NULL, '詠牛應制 許圉師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f82a580d-d750-49c9-99dd-309b71bc64a7', '荅戶部員外賀遂涉戲贈', '荅戶部員外賀遂涉戲贈', '10579e24-8eb3-4878-8557-a2d1edc7ad4f', '唐', '["錦帳隨情設，金鑪任意熏。","惟愁員外署，不應列星文。"]', '["錦帳隨情設，金鑪任意熏。","惟愁員外署，不應列星文。"]', '诗', 'shi', '', NULL, '荅戶部員外賀遂涉戲贈 趙謙光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e81b9c98-b5ed-47fa-824a-ebc4cff04eeb', '送蘇尚書赴益州', '送蘇尚书赴益州', '37aacf96-4d0e-431f-be5c-50f23fd2cdbe', '唐', '["離憂將歲盡，歸望逐春來。","庭花如有意，留豔待人開。"]', '["離憂將歲尽，归望逐春来。","庭花如有意，留豔待人开。"]', '诗', 'shi', '', NULL, '送蘇尚書赴益州 鄭惟忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa0fb4d9-c6e2-445f-aa45-66048025619b', '詠燕', '詠燕', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["變石身猶重，銜泥力尚微。","從來赴甲第，兩起一雙飛。"]', '["变石身猶重，銜泥力尚微。","從来赴甲第，兩起一雙飞。"]', '诗', 'shi', '', NULL, '詠燕 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e58959d-fe91-4129-a956-36b42abd366a', '嶺外守歲', '嶺外守歲', 'b3937c78-9e8c-4370-a572-a8cab18b0c21', '唐', '["冬去更籌盡，春隨斗柄迴。","寒暄一夜隔，客鬢兩年催。"]', '["冬去更籌尽，春隨斗柄迴。","寒暄一夜隔，客鬢兩年催。"]', '诗', 'shi', '', NULL, '嶺外守歲 李福業 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d03a192f-7940-41a6-8c81-71c18169a3c6', '奉和進船洛水應制', '奉和進船洛水應制', 'd3274108-2798-4b6b-aa12-f66fd76aaf6a', '唐', '["禁園紆睿覽，仙櫂叶宸遊。","洛北風花樹，江南彩畫舟。","榮生蘭蕙草，春入鳳皇樓。","興盡離宮暮，煙光起夕流。"]', '["禁园紆睿覽，仙櫂叶宸游。","洛北风花樹，江南彩畫舟。","榮生蘭蕙草，春入鳳皇楼。","兴尽離宮暮，煙光起夕流。"]', '诗', 'shi', '', NULL, '奉和進船洛水應制 薛眘惑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3148b2e5-e3c2-4e8d-8d31-966c9adea836', '奉和九月九日應制', '奉和九月九日應制', '3f303940-24fd-4370-847f-c78c1a0734b4', '唐', '["商飆凝素籥，玄覽賁黃圖。","曉霜驚斷雁，晨吹結栖烏。","寒花低岸菊，涼葉下庭梧。","澤宮申舊典，相圃叶前模。","玉砌分雕戟，金溝轉鏤衢。","帶星飛夏箭，映月上軒弧。","慶展簪裾洽，恩融雨露濡。","天文發丹篆，寶思掩玄珠。","承歡徒抃舞，負弛竊忘軀。"]', '["商飆凝素籥，玄覽賁黄圖。","晓霜驚斷雁，晨吹結栖烏。","寒花低岸菊，涼葉下庭梧。","澤宮申旧典，相圃叶前模。","玉砌分雕戟，金溝轉鏤衢。","带星飞夏箭，映月上軒弧。","慶展簪裾洽，恩融雨露濡。","天文發丹篆，寶思掩玄珠。","承歡徒抃舞，負弛竊忘軀。"]', '诗', 'shi', '', NULL, '奉和九月九日應制 賀敱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d4e1930-659a-45dc-9c5d-6295f8ec33c4', '奉和聖製夏日遊石淙山', '奉和聖製夏日游石淙山', '4785c234-e65f-4415-a907-96b647835650', '唐', '["宸暉降望金輿轉，仙路崢嶸碧澗幽。","羽杖遙臨鸞鶴駕，帷宮直坐鳳麟洲。","飛泉灑液恆疑雨，密樹含涼鎮似秋。","老臣預陪懸圃宴，餘年方共赤松遊。"]', '["宸暉降望金輿轉，仙路崢嶸碧澗幽。","羽杖遙臨鸾鹤駕，帷宮直坐鳳麟洲。","飞泉灑液恆疑雨，密樹含涼鎮似秋。","老臣預陪懸圃宴，餘年方共赤松游。"]', '诗', 'shi', '', NULL, '奉和聖製夏日遊石淙山 狄仁傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('537ea290-9bc8-4ca1-85ef-333283704a98', '修書院學士奉勅宴梁王宅', '修书院学士奉勅宴梁王宅', '9f057e3a-2855-4f90-92a1-fcd96bd8b7be', '唐', '["大君敦宴賞，萬乘下梁園。","酒助閑平樂，人霑雨露恩。","榮光開帳殿，佳氣滿旌門。","願陪南岳壽，長奉北宸樽。"]', '["大君敦宴賞，万乘下梁园。","酒助闲平乐，人霑雨露恩。","榮光开帳殿，佳氣满旌门。","願陪南岳壽，长奉北宸樽。"]', '诗', 'shi', '', NULL, '修書院學士奉勅宴梁王宅 魏元忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec46607d-ef03-4008-b82e-e8b7a6a6db2d', '銀潢宮侍宴應制', '銀潢宮侍宴應制', '9f057e3a-2855-4f90-92a1-fcd96bd8b7be', '唐', '["別殿秋雲上，離宮夏景移。","寒風生玉樹，涼氣下瑤池。","塹花仍吐葉，巖木尚抽枝。","願奉南山壽，千秋長若斯。"]', '["別殿秋云上，離宮夏景移。","寒风生玉樹，涼氣下瑤池。","塹花仍吐葉，巖木尚抽枝。","願奉南山壽，千秋长若斯。"]', '诗', 'shi', '', NULL, '銀潢宮侍宴應制 魏元忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c9c2b52-edc9-465d-bda7-ef8d4aa38756', '折楊柳', '折楊柳', '1a2f17fc-4959-4965-acd0-6e6c5c735a73', '唐', '["萬里邊城地，三春楊柳節。","葉似鏡中眉，花如關外雪。","征人遠鄉思，倡婦高樓別。","不忍擲年華，含情寄攀折。"]', '["万里邊城地，三春楊柳節。","葉似镜中眉，花如关外雪。","征人远乡思，倡婦高楼別。","不忍擲年华，含情寄攀折。"]', '诗', 'shi', '', NULL, '折楊柳 韋承慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9722f9a-5865-4638-9961-96cad7cbab00', '寒食應制', '寒食應制', '1a2f17fc-4959-4965-acd0-6e6c5c735a73', '唐', '["鳳城春色晚，龍禁早暉通。","舊火收槐燧，餘寒入桂宮。","鶯啼正隱葉，雞鬬始開籠。","藹藹瑤山滿，仙歌始樂風。"]', '["鳳城春色晚，龙禁早暉通。","旧火收槐燧，餘寒入桂宮。","鶯啼正隐葉，雞鬬始开籠。","藹藹瑤山满，仙歌始乐风。"]', '诗', 'shi', '', NULL, '寒食應制 韋承慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5c6ca0b-e8c8-4ab9-9b65-0f6298f9708c', '凌朝浮江旅思', '凌朝浮江旅思', '1a2f17fc-4959-4965-acd0-6e6c5c735a73', '唐', '["天晴上初日，春水送孤舟。","山遠疑無樹，潮平似不流。","岸花開且落，江鳥沒還浮。","羈望傷千里，長歌遣四愁。"]', '["天晴上初日，春水送孤舟。","山远疑無樹，潮平似不流。","岸花开且落，江鸟沒還浮。","羈望傷千里，长歌遣四愁。"]', '诗', 'shi', '', NULL, '凌朝浮江旅思 韋承慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0382cbde-c1d8-49da-ae39-540e0c1f8aca', '直中書省', '直中书省', '1a2f17fc-4959-4965-acd0-6e6c5c735a73', '唐', '["清切鳳皇池，扶疎雞樹枝。","唯應集鸞鷺，何爲宿羈雌。","大造乾坤闢，深恩雨露垂。","昆蚑皆含養，駑駘亦驅馳。","木偶翻爲用，芝泥忽濫窺。","九思空自勉，五字本無施。","徒喜逢千載，何階荅二儀。","螢光向日盡，蚊力負山疲。","禁宇庭除闊，閑宵鐘箭移。","暗花臨戶發，殘月下簾欹。","白髮隨年改，丹心爲主披。","命將時共泰，言與行俱危。","寄謝巢由客，堯年正在斯。"]', '["清切鳳皇池，扶疎雞樹枝。","唯應集鸾鷺，何爲宿羈雌。","大造乾坤闢，深恩雨露垂。","昆蚑皆含養，駑駘亦驱驰。","木偶翻爲用，芝泥忽濫窺。","九思空自勉，五字本無施。","徒喜逢千載，何階荅二儀。","螢光向日尽，蚊力負山疲。","禁宇庭除闊，闲宵鐘箭移。","暗花臨戶發，殘月下簾欹。","白髮隨年改，丹心爲主披。","命將时共泰，言與行俱危。","寄謝巢由客，堯年正在斯。"]', '诗', 'shi', '', NULL, '直中書省 韋承慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71ac5280-9b58-4381-ac21-23a62f486092', '南行別弟', '南行別弟', '1a2f17fc-4959-4965-acd0-6e6c5c735a73', '唐', '["澹澹長江水，悠悠遠客情。","落花相與恨，到地一無聲。"]', '["澹澹长江水，悠悠远客情。","落花相與恨，到地一無声。"]', '诗', 'shi', '', NULL, '南行別弟 韋承慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cb8ce3e-dbe3-4e67-af00-a804071e351c', '南中詠雁', '南中詠雁', '1a2f17fc-4959-4965-acd0-6e6c5c735a73', '唐', '["萬里人南去，三春雁北飛。","不知何歲月？得與爾同歸。"]', '["万里人南去，三春雁北飞。","不知何歲月？得與爾同归。"]', '诗', 'shi', '', NULL, '南中詠雁 韋承慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb14448f-b5b5-4e78-811b-fd105d3e771c', '江樓', '江楼', '1a2f17fc-4959-4965-acd0-6e6c5c735a73', '唐', '["獨酌芳春酒，登樓已半曛。","誰驚一行雁，衝斷過江雲。"]', '["独酌芳春酒，登楼已半曛。","誰驚一行雁，衝斷過江云。"]', '诗', 'shi', '', NULL, '江樓 韋承慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37ed7598-c25c-4394-95fc-36ba2fbd9e41', '凝碧池侍宴看競渡應制', '凝碧池侍宴看競渡應制', 'e0a2bc68-0715-4c69-a8a8-6218aaaa4fc4', '唐', '["上苑清鑾路，高居重豫遊。","前對芙蓉沼，傍臨杜若洲。","地如玄扈望，波似洞庭秋。","列筵飛翠斝，分曹戲鷁舟。","湍高櫂影沒，岸近榜歌遒。","舞曲依鸞殿，簫聲下鳳樓。","忽聞天上樂，疑逐海查流。"]', '["上苑清鑾路，高居重豫游。","前对芙蓉沼，傍臨杜若洲。","地如玄扈望，波似洞庭秋。","列筵飞翠斝，分曹戲鷁舟。","湍高櫂影沒，岸近榜歌遒。","舞曲依鸾殿，簫声下鳳楼。","忽闻天上乐，疑逐海查流。"]', '诗', 'shi', '', NULL, '凝碧池侍宴看競渡應制 李懷遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac1d8c07-f1ea-43c3-9a6c-5baee29578a4', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', 'b93f3304-6cb5-42e4-923f-9928d32ae301', '唐', '["紫宸歡每洽，紺殿法初隆。","菊泛延齡酒，蘭吹解慍風。","咸英調正樂，香梵徧秋空。","臨幸浮天瑞，重陽日再中。"]', '["紫宸歡每洽，紺殿法初隆。","菊泛延齡酒，蘭吹解慍风。","咸英調正乐，香梵徧秋空。","臨幸浮天瑞，重陽日再中。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 崔日用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d37add31-d4aa-40c6-8195-f44d72a66b8e', '奉和聖製送張說巡邊', '奉和聖製送張说巡邊', 'b93f3304-6cb5-42e4-923f-9928d32ae301', '唐', '["軒相推風后，周官重夏卿。","廟謀能允迪，韜略又縱橫。","吉日四黃馬，宣王六月兵。","擬清雞鹿塞，先指朔方城。","列將懷威撫，匈奴畏盛名。","去當推轂送，來佇出郊迎。","絕漠蓬將斷，華筵槿正榮。","壯心看舞劒，別緒應懸旌。","睿錫承優旨，乾文復寵行。","暫勞期永逸，赫矣振天聲。"]', '["軒相推风后，周官重夏卿。","廟謀能允迪，韜略又縱橫。","吉日四黄马，宣王六月兵。","擬清雞鹿塞，先指朔方城。","列將懷威撫，匈奴畏盛名。","去當推轂送，来佇出郊迎。","絕漠蓬將斷，华筵槿正榮。","壯心看舞劒，別緒應懸旌。","睿錫承優旨，乾文复寵行。","暫勞期永逸，赫矣振天声。"]', '诗', 'shi', '', NULL, '奉和聖製送張說巡邊 崔日用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6102da34-bbc0-46b8-aecd-4d118e80c07c', '奉和立春遊苑迎春應制', '奉和立春游苑迎春應制', 'b93f3304-6cb5-42e4-923f-9928d32ae301', '唐', '["乘時迎氣正璿衡，灞滻煙氛向晚清。","剪綺裁紅妙春色，宮梅殿柳識天情。","瑤筐綵燕先呈端，金縷晨雞未學鳴。","聖澤陽和宜宴樂，年年捧日向東城。"]', '["乘时迎氣正璿衡，灞滻煙氛向晚清。","剪綺裁紅妙春色，宮梅殿柳識天情。","瑤筐綵燕先呈端，金縷晨雞未学鳴。","聖澤陽和宜宴乐，年年捧日向东城。"]', '诗', 'shi', '', NULL, '奉和立春遊苑迎春應制 崔日用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7f2d7f8-a6e2-4eb2-8c20-99db92f4dc7f', '奉和聖製春日幸望春宮應制', '奉和聖製春日幸望春宮應制', 'b93f3304-6cb5-42e4-923f-9928d32ae301', '唐', '["東郊風物正熏馨，素滻鳧鷖戲綠汀。","鳳閣斜通平樂觀，龍旂直逼望春亭。","光風搖動蘭英紫，淑氣依遲柳色青。","渭浦明晨修禊事，羣公傾賀水心銘。"]', '["东郊风物正熏馨，素滻鳧鷖戲綠汀。","鳳閣斜通平乐观，龙旂直逼望春亭。","光风搖动蘭英紫，淑氣依遲柳色青。","渭浦明晨修禊事，羣公傾賀水心銘。"]', '诗', 'shi', '', NULL, '奉和聖製春日幸望春宮應制 崔日用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab913da7-fe1d-42d5-9afb-97d6c3224570', '奉和人日重宴大明宮恩賜綵縷人勝應制', '奉和人日重宴大明宮恩賜綵縷人勝應制', 'b93f3304-6cb5-42e4-923f-9928d32ae301', '唐', '["新年宴樂坐東朝，鐘鼓鏗鍠大樂調。","金屋瑤筐開寶勝，花箋綵筆頌春椒。","曲池苔色冰前液，上苑梅香雪裏嬌。","宸極此時飛聖藻，微臣竊抃預聞韶。"]', '["新年宴乐坐东朝，鐘鼓鏗鍠大乐調。","金屋瑤筐开寶勝，花箋綵笔頌春椒。","曲池苔色冰前液，上苑梅香雪裏嬌。","宸極此时飞聖藻，微臣竊抃預闻韶。"]', '诗', 'shi', '', NULL, '奉和人日重宴大明宮恩賜綵縷人勝應制 崔日用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ea0b4eb-d6ef-4199-9b25-60f80722bb52', '奉和聖製龍池篇', '奉和聖製龙池篇', 'b93f3304-6cb5-42e4-923f-9928d32ae301', '唐', '["龍興白水漢興符，聖主時乘運斗樞。","岸上䒠茸五花樹，波中的皪千金珠。","操環昔聞迎夏啓，發匣先來瑞有虞。","風色雲光隨隱見，赤雲神化象江湖。"]', '["龙兴白水漢兴符，聖主时乘運斗樞。","岸上䒠茸五花樹，波中的皪千金珠。","操环昔闻迎夏啓，發匣先来瑞有虞。","风色云光隨隐见，赤云神化象江湖。"]', '诗', 'shi', '', NULL, '奉和聖製龍池篇 崔日用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f80c6962-9af7-49db-830d-17412e18ea2a', '夜宴安樂公主宅', '夜宴安乐公主宅', 'b93f3304-6cb5-42e4-923f-9928d32ae301', '唐', '["銀燭金屏坐碧堂，只言河漢動神光。","主家盛時歡不極，才子能歌夜未央。"]', '["銀燭金屏坐碧堂，只言河漢动神光。","主家盛时歡不極，才子能歌夜未央。"]', '诗', 'shi', '', NULL, '夜宴安樂公主宅 崔日用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f26fe1c9-3a67-417f-a738-6d0a919dad93', '餞唐永昌', '餞唐永昌', 'b93f3304-6cb5-42e4-923f-9928d32ae301', '唐', '["洛陽桴鼓今不鳴，朝野咸推重太平。","冬至冰霜俱怨別，春來花鳥若爲情。"]', '["洛陽桴鼓今不鳴，朝野咸推重太平。","冬至冰霜俱怨別，春来花鸟若爲情。"]', '诗', 'shi', '', NULL, '餞唐永昌 崔日用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39390e9e-7226-46ff-b955-60a0bb460bca', '奉和送金城公主適西蕃', '奉和送金城公主適西蕃', 'b93f3304-6cb5-42e4-923f-9928d32ae301', '唐', '["聖后經綸遠，謀臣計畫多。","受降追漢策，築館計戎和。","俗化烏孫壘，春生積石河。","六龍今出餞，雙鶴願爲歌。"]', '["聖后經綸远，謀臣計畫多。","受降追漢策，築館計戎和。","俗化烏孫壘，春生積石河。","六龙今出餞，雙鹤願爲歌。"]', '诗', 'shi', '', NULL, '奉和送金城公主適西蕃 崔日用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5646354e-0082-4b48-88b3-ff31b8ecabf6', '句', '句', 'b93f3304-6cb5-42e4-923f-9928d32ae301', '唐', '["彼名流兮左氏癖，意玄遠兮冠今夕。"]', '["彼名流兮左氏癖，意玄远兮冠今夕。"]', '诗', 'shi', '', NULL, '句 崔日用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('429e15be-738b-416b-8e51-1d600e08ac10', '奉和人日清暉閣宴羣臣遇雪應制', '奉和人日清暉閣宴羣臣遇雪應制', '202f61dc-01a4-428f-a545-181ed7b9993e', '唐', '["窈窕神仙閣，參差雲漢間。","九重中葉啓，七日早春還。","太液天爲水，蓬萊雪作山。","今朝上林樹，無處不堪攀。"]', '["窈窕神仙閣，參差云漢间。","九重中葉啓，七日早春還。","太液天爲水，蓬萊雪作山。","今朝上林樹，無处不堪攀。"]', '诗', 'shi', '', NULL, '奉和人日清暉閣宴羣臣遇雪應制 宗楚客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25dfc95b-7088-4eb3-b967-03820bc78859', '安樂公主移入新宅侍宴應制', '安乐公主移入新宅侍宴應制', '202f61dc-01a4-428f-a545-181ed7b9993e', '唐', '["星橋他日創，仙牓此時開。","馬向鋪錢埒，簫聞弄玉臺。","人同衛叔美，客似長卿才。","借問遊天漢，誰能取石回。"]', '["星橋他日創，仙牓此时开。","马向鋪錢埒，簫闻弄玉台。","人同衛叔美，客似长卿才。","借问游天漢，誰能取石回。"]', '诗', 'shi', '', NULL, '安樂公主移入新宅侍宴應制 宗楚客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1c3aaca-f15c-47df-b5dc-16ac2d5464f8', '正月晦日侍宴滻水應制賦得長字', '正月晦日侍宴滻水應制賦得长字', '202f61dc-01a4-428f-a545-181ed7b9993e', '唐', '["御輦出明光，乘流泛羽觴。","珠胎隨月減，玉漏與年長。","寒盡梅猶白，風遲柳未黃。","日斜旌騎轉，休氣滿林塘。"]', '["御輦出明光，乘流泛羽觴。","珠胎隨月減，玉漏與年长。","寒尽梅猶白，风遲柳未黄。","日斜旌騎轉，休氣满林塘。"]', '诗', 'shi', '', NULL, '正月晦日侍宴滻水應制賦得長字 宗楚客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5102dcfb-8520-471e-a5fc-7bf36b48ff74', '奉和幸上陽宮侍宴應制', '奉和幸上陽宮侍宴應制', '202f61dc-01a4-428f-a545-181ed7b9993e', '唐', '["紫庭金鳳闕，丹禁玉雞川。","似立蓬瀛上，疑遊崑閬前。","鳥將歌合轉，花共錦爭鮮。","湛露飛堯酒，熏風入舜弦。","水光搖落日，樹色帶晴煙。","向夕迴琱輦，佳氣滿巖泉。"]', '["紫庭金鳳闕，丹禁玉雞川。","似立蓬瀛上，疑游崑閬前。","鸟將歌合轉，花共錦爭鲜。","湛露飞堯酒，熏风入舜弦。","水光搖落日，樹色带晴煙。","向夕迴琱輦，佳氣满巖泉。"]', '诗', 'shi', '', NULL, '奉和幸上陽宮侍宴應制 宗楚客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a68d3c9d-dad7-4f39-804c-5295b85101f9', '奉和幸安樂公主山莊應制', '奉和幸安乐公主山莊應制', '202f61dc-01a4-428f-a545-181ed7b9993e', '唐', '["玉樓銀牓枕嚴城，翠蓋紅旂列禁營。","日映層巖圖畫色，風搖雜樹管弦聲。","水邊重閣含飛動，雲裏孤峰類削成。","幸覩八龍遊閬苑，無勞萬里訪蓬瀛。"]', '["玉楼銀牓枕嚴城，翠蓋紅旂列禁營。","日映層巖圖畫色，风搖杂樹管弦声。","水邊重閣含飞动，云裏孤峰類削成。","幸覩八龙游閬苑，無勞万里訪蓬瀛。"]', '诗', 'shi', '', NULL, '奉和幸安樂公主山莊應制 宗楚客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c30e4c1c-e83d-49fb-8bc9-35ec57d98bbb', '奉和聖製喜雪應制', '奉和聖製喜雪應制', '202f61dc-01a4-428f-a545-181ed7b9993e', '唐', '["飄飄瑞雪下山川，散漫輕飛集九埏。","似絮還飛垂柳陌，如花更繞落梅前。","影隨明月團紈扇，聲將流水雜鳴弦。","共荷神功萬庾積，終朝聖壽百千年。"]', '["飄飄瑞雪下山川，散漫轻飞集九埏。","似絮還飞垂柳陌，如花更繞落梅前。","影隨明月團紈扇，声將流水杂鳴弦。","共荷神功万庾積，終朝聖壽百千年。"]', '诗', 'shi', '', NULL, '奉和聖製喜雪應制 宗楚客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0277e0ca-9ba4-4748-98a8-663a5e1b27a0', '句', '句', '202f61dc-01a4-428f-a545-181ed7b9993e', '唐', '["竹町羅千衛，蘭莛降兩宮。","七萃鑾輿動，千年瑞檢開。","綵旗臨鳳闕，翠幕遶龜津。"]', '["竹町羅千衛，蘭莛降兩宮。","七萃鑾輿动，千年瑞檢开。","綵旗臨鳳闕，翠幕遶龟津。"]', '诗', 'shi', '', NULL, '句 宗楚客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83a2178a-099b-4e39-9c39-b0a022f8c229', '奉和九日幸臨渭亭登高應制得暉字', '奉和九日幸臨渭亭登高應制得暉字', 'e6f447ea-a0f9-485c-bbcc-d55d3b0abd39', '唐', '["重陽早露晞，睿賞瞰秋磯。","菊氣先熏酒，萸香更襲衣。","清切絲桐會，縱橫文雅飛。","恩深荅效淺，留醉奉宸暉。"]', '["重陽早露晞，睿賞瞰秋磯。","菊氣先熏酒，萸香更襲衣。","清切絲桐會，縱橫文雅飞。","恩深荅效淺，留醉奉宸暉。"]', '诗', 'shi', '', NULL, '奉和九日幸臨渭亭登高應制得暉字 蘇瓌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2541506b-27b1-483c-952b-beb08f2bfe75', '興慶池侍宴應制', '兴慶池侍宴應制', 'e6f447ea-a0f9-485c-bbcc-d55d3b0abd39', '唐', '["金闕平明宿霧收，瑤池式宴俯清流。","瑞鳳飛來隨帝輦，祥魚出戲躍王舟。","帷齊綠樹當筵密，蓋轉緗荷接岸浮。","如臨竊比微臣懼，若濟叨陪聖主遊。"]', '["金闕平明宿霧收，瑤池式宴俯清流。","瑞鳳飞来隨帝輦，祥鱼出戲躍王舟。","帷齊綠樹當筵密，蓋轉緗荷接岸浮。","如臨竊比微臣懼，若濟叨陪聖主游。"]', '诗', 'shi', '', NULL, '興慶池侍宴應制 蘇瓌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9566e5b-ddb3-4e5d-91c2-8c8efe97a2ae', '奉和聖製燭龍齋祭', '奉和聖製燭龙斋祭', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["上帝臨下，鑒亦有光。","孰云陰隲，惟聖克彰。","六月徂暑，四郊愆陽。","我后其勤，告于壇場。","精意允溢，羣靈鼓舞。","蔚兮朝雲，沛然時雨。","雨我原田，亦既有年。","燭龍煌煌，明宗報祀。","于以助之，天人帝子。","聞詩有訓，國風茲始。"]', '["上帝臨下，鑒亦有光。","孰云陰隲，惟聖克彰。","六月徂暑，四郊愆陽。","我后其勤，告于壇場。","精意允溢，羣靈鼓舞。","蔚兮朝云，沛然时雨。","雨我原田，亦既有年。","燭龙煌煌，明宗報祀。","于以助之，天人帝子。","闻诗有訓，国风茲始。"]', '诗', 'shi', '', NULL, '奉和聖製燭龍齋祭 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cbbc945-d6eb-4ada-8511-a45d7b8518c1', '奉和聖製喜雨', '奉和聖製喜雨', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["艱我稼穡，載育載亭。","隨物應之，曷聖與靈。","謂我何憑，惟德之馨。","誰云天遠，以誠必至。","太清無雲，羲和頓轡。","于斯烝人，瞻彼非覬。","陰冥倏忽，沛澤咸洎。","何以致之，我后之感。","無皐無隰，黍稷黯黯。","無卉無木，敷芬黮黤。","黃龍勿來，鳴鳥不思。","人和年豐，皇心則怡。","豈與周宣，雲漢徒詩。"]', '["艱我稼穡，載育載亭。","隨物應之，曷聖與靈。","謂我何憑，惟德之馨。","誰云天远，以誠必至。","太清無云，羲和頓轡。","于斯烝人，瞻彼非覬。","陰冥倏忽，沛澤咸洎。","何以致之，我后之感。","無皐無隰，黍稷黯黯。","無卉無木，敷芬黮黤。","黄龙勿来，鳴鸟不思。","人和年豐，皇心則怡。","豈與周宣，云漢徒诗。"]', '诗', 'shi', '', NULL, '奉和聖製喜雨 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5f2288a-1511-4498-859c-4c588a8d4391', '南郊文武出入舒和之樂', '南郊文武出入舒和之乐', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["祝史辭正，人神慶叶。","福以德昭，享以誠接。","六變云備，百禮斯浹。","祀事孔明，祚流萬葉。"]', '["祝史辞正，人神慶叶。","福以德昭，享以誠接。","六变云備，百禮斯浹。","祀事孔明，祚流万葉。"]', '诗', 'shi', '', NULL, '南郊文武出入舒和之樂 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71bada30-9afa-49ec-b815-968c5306e107', '奉和聖製幸晉陽宮', '奉和聖製幸晉陽宮', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["隋季失天策，萬方罹凶殘。","皇祖稱義旗，三靈皆獲安。","聖期將申錫，王業成艱難。","盜移未改命，曆在終履端。","彼汾惟帝鄉，雄都信鬱盤。","一月朔巡狩，羣后陪清鑾。","霸跡在沛庭，舊儀覩漢官。","唐風思何深？舜典敷更寬。","戶蒙枌榆復，邑爭牛酒歡。","緬惟翦商後，豈獨微禹歎。","三后既在天，萬年斯不刊。","尊祖實我皇，天文皆仰觀。"]', '["隋季失天策，万方罹凶殘。","皇祖稱義旗，三靈皆獲安。","聖期將申錫，王業成艱难。","盜移未改命，曆在終履端。","彼汾惟帝乡，雄都信鬱盤。","一月朔巡狩，羣后陪清鑾。","霸跡在沛庭，旧儀覩漢官。","唐风思何深？舜典敷更寬。","戶蒙枌榆复，邑爭牛酒歡。","緬惟翦商後，豈独微禹歎。","三后既在天，万年斯不刊。","尊祖實我皇，天文皆仰观。"]', '诗', 'shi', '', NULL, '奉和聖製幸晉陽宮 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a19b5bfa-bb35-4d92-80c1-13f1a7b02234', '奉和聖製次成皐先聖擒建德之所', '奉和聖製次成皐先聖擒建德之所', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["天命誠有集，王業初惟艱。","翦商自文祖，夷項在茲山。","地識斬蛇處，河臨飲馬間。","威加昔運往，澤流今聖還。","尊祖頌先烈，賡歌安用攀。","紹成即我后，封岱出天關。"]', '["天命誠有集，王業初惟艱。","翦商自文祖，夷項在茲山。","地識斬蛇处，河臨饮马间。","威加昔運往，澤流今聖還。","尊祖頌先烈，賡歌安用攀。","紹成即我后，封岱出天关。"]', '诗', 'shi', '', NULL, '奉和聖製次成皐先聖擒建德之所 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80bd6628-261d-41a9-852a-67f80285c53f', '奉和聖製賜諸州刺史以題座右', '奉和聖製賜諸州刺史以題座右', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["聖人合天德，洪覆在元元。","每勞蒼生念，不以黃屋尊。","興化俟羣辟，擇賢守列藩。","得人此爲盛，咨岳今復存。","降鑒引君道，殷勤啓政門。","容光無不照，有象必爲言。","成憲知所奉，致理歸其根。","肅肅稟玄猷，煌煌戒朱軒。","豈徒任遇重，兼爾宴錫繁。","載聞勵臣節，持答明主恩。"]', '["聖人合天德，洪覆在元元。","每勞蒼生念，不以黄屋尊。","兴化俟羣辟，擇賢守列藩。","得人此爲盛，咨岳今复存。","降鑒引君道，殷勤啓政门。","容光無不照，有象必爲言。","成憲知所奉，致理归其根。","肅肅稟玄猷，煌煌戒朱軒。","豈徒任遇重，兼爾宴錫繁。","載闻勵臣節，持答明主恩。"]', '诗', 'shi', '', NULL, '奉和聖製賜諸州刺史以題座右 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44ac8705-4526-4dcb-be9d-039279cd1178', '奉和聖製送十道採訪使及朝集使', '奉和聖製送十道採訪使及朝集使', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["三年一上計，萬國趨河洛。","課最力已陳，賞延恩復博。","垂衣深共理，改瑟其咸若。","首路迴竹符，分鑣揚木鐸。","戒程有攸往，詔餞無淹泊。","昭晰動天文，殷勤在人瘼。","持久望茲念，克終期所託。","行矣當自強，春耕庶秋獲。"]', '["三年一上計，万国趨河洛。","課最力已陳，賞延恩复博。","垂衣深共理，改瑟其咸若。","首路迴竹符，分鑣揚木鐸。","戒程有攸往，詔餞無淹泊。","昭晰动天文，殷勤在人瘼。","持久望茲念，克終期所託。","行矣當自強，春耕庶秋獲。"]', '诗', 'shi', '', NULL, '奉和聖製送十道採訪使及朝集使 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0584ae56-f5a7-44c6-9af7-1b768459d7b1', '奉和聖製謁玄元皇帝廟齋', '奉和聖製謁玄元皇帝廟斋', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["興運昔有感，建祠北山巔。","雲雷初締構，日月今悠然。","紫氣尚蓊鬱，玄元如在焉。","迨茲事追遠，輪奐復增鮮。","洞府香林處，齋壇清漢邊。","吾君乃尊祖，夙駕此留連。","樂動人神會，鐘成律度圓。","笙歌下鸞鶴，芝朮萃靈仙。","曾是福黎庶，豈唯味虛玄。","賡歌徒有作，微薄謝昭宣。"]', '["兴運昔有感，建祠北山巔。","云雷初締構，日月今悠然。","紫氣尚蓊鬱，玄元如在焉。","迨茲事追远，輪奐复增鲜。","洞府香林处，斋壇清漢邊。","吾君乃尊祖，夙駕此留連。","乐动人神會，鐘成律度圓。","笙歌下鸾鹤，芝朮萃靈仙。","曾是福黎庶，豈唯味虛玄。","賡歌徒有作，微薄謝昭宣。"]', '诗', 'shi', '', NULL, '奉和聖製謁玄元皇帝廟齋 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4406edea-27bd-40ec-9340-e33c43bfa149', '巫山高', '巫山高', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["巫山與天近，煙景長青熒。","此中楚王夢，夢得神女靈。","神女去已久，雲雨空冥冥。","唯有巴猿嘯，哀音不可聽。"]', '["巫山與天近，煙景长青熒。","此中楚王梦，梦得神女靈。","神女去已久，云雨空冥冥。","唯有巴猿嘯，哀音不可听。"]', '诗', 'shi', '', NULL, '巫山高 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c1a8add-764b-466a-b14b-c329f00d7ef0', '和黃門盧監望秦始皇陵', '和黄门盧監望秦始皇陵', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["秦帝始求仙，驪山何遽卜。","中年既無效，茲地所宜復。","徒役如雷奔，珍怪亦雲蓄。","黔首無寄命，赭衣相追逐。","人怨神亦怒，身死宗遂覆。","土崩失天下，龍鬬入函谷。","國爲項籍屠，君同華元戮。","始掘既由楚，終焚乃因牧。","上宰議揚賢，中阿感桓速。","一聞過秦論，載懷空杼軸。"]', '["秦帝始求仙，驪山何遽卜。","中年既無效，茲地所宜复。","徒役如雷奔，珍怪亦云蓄。","黔首無寄命，赭衣相追逐。","人怨神亦怒，身死宗遂覆。","土崩失天下，龙鬬入函谷。","国爲項籍屠，君同华元戮。","始掘既由楚，終焚乃因牧。","上宰議揚賢，中阿感桓速。","一闻過秦論，載懷空杼軸。"]', '诗', 'shi', '', NULL, '和黃門盧監望秦始皇陵 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdad555d-a566-4950-8508-2437c9359415', '酬周判官巡至始興會改秘書少監見貽之作兼呈耿廣州', '酬周判官巡至始兴會改秘书少監见貽之作兼呈耿廣州', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["惟昔遷樂土，迨今已重世。","陰慶荷先德，素風慙後裔。","唯益梓桑恭，豈稟山川麗。","于時初自勉，揆己無兼濟。","瘠土資勞力，良書啓蒙蔽。","一探石室文，再擢金門第。","既起南宮草，復掌西掖制。","過舉及小人，便蕃在中歲。","亞司河海秩，轉牧江湖澨。","勿謂符竹輕，但覺涓塵細。","一麾尚云忝，十駕宜求稅。","心息已如灰，跡牽且爲贅。","忽捧天書委，將革海隅弊。","朝聞循誠節，夕飲蒙瘴癘。","義疾恥無勇，盜憎攻亦銳。","葵藿是傾心，豺狼何反噬。","履險甘所受，勞賢恧相曳。","攬轡但荒服，循陔便私第。","嘉慶始獲申，恩華復相繼。","無庸我先舉，同事君猶滯。","當推奉使績，且結拜親契。","更延懷安旨，曾是慮危際。","善謀雖若茲，至理焉可替。","所杖有神道，況承明主惠。"]', '["惟昔遷乐土，迨今已重世。","陰慶荷先德，素风慙後裔。","唯益梓桑恭，豈稟山川丽。","于时初自勉，揆己無兼濟。","瘠土資勞力，良书啓蒙蔽。","一探石室文，再擢金门第。","既起南宮草，复掌西掖制。","過舉及小人，便蕃在中歲。","亞司河海秩，轉牧江湖澨。","勿謂符竹轻，但覺涓塵細。","一麾尚云忝，十駕宜求稅。","心息已如灰，跡牽且爲贅。","忽捧天书委，將革海隅弊。","朝闻循誠節，夕饮蒙瘴癘。","義疾恥無勇，盜憎攻亦銳。","葵藿是傾心，豺狼何反噬。","履險甘所受，勞賢恧相曳。","攬轡但荒服，循陔便私第。","嘉慶始獲申，恩华复相繼。","無庸我先舉，同事君猶滯。","當推奉使績，且結拜親契。","更延懷安旨，曾是慮危際。","善謀雖若茲，至理焉可替。","所杖有神道，況承明主惠。"]', '诗', 'shi', '', NULL, '酬周判官巡至始興會改秘書少監見貽之作兼呈耿廣州 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd14f44a-0c60-49ed-a8fd-4310a28f8823', '和吏部李侍郎見示秋夜望月憶諸侍郎之什其卒章有前後行之戲因命僕繼作', '和吏部李侍郎见示秋夜望月憶諸侍郎之什其卒章有前後行之戲因命僕繼作', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["清秋發高興，涼月復閑宵。","光逐露華滿，情因水鏡搖。","同時亦所見，異路無相招。","美景向空盡，歡言隨事銷。","忽聽金華作，誠如玉律調。","南宮尚爲後，東觀何其遼。","名數雖云隔，風期幸未遙。","今來重餘論，懷此更終朝。"]', '["清秋發高兴，涼月复闲宵。","光逐露华满，情因水镜搖。","同时亦所见，異路無相招。","美景向空尽，歡言隨事銷。","忽听金华作，誠如玉律調。","南宮尚爲後，东观何其遼。","名數雖云隔，风期幸未遙。","今来重餘論，懷此更終朝。"]', '诗', 'shi', '', NULL, '和吏部李侍郎見示秋夜望月憶諸侍郎之什其卒章有前後行之戲因命僕繼作 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c404b3a0-8660-43f2-9ad2-36b70d01c77b', '登南嶽事畢謁司馬道士', '登南嶽事畢謁司马道士', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["將命祈靈嶽，迴策詣真士。","絕跡尋一徑，異香聞數里。","分庭八桂樹，肅容兩童子。","入室希把袖，登牀願啓齒。","誘我棄智訣，迨茲長生理。","吸精反自然，鍊藥求不死。","斯言眇霄漢，顧余嬰紛滓。","相去九牛毛，慙歎知何已。"]', '["將命祈靈嶽，迴策詣真士。","絕跡尋一徑，異香闻數里。","分庭八桂樹，肅容兩童子。","入室希把袖，登牀願啓齒。","誘我棄智訣，迨茲长生理。","吸精反自然，鍊藥求不死。","斯言眇霄漢，顧余嬰紛滓。","相去九牛毛，慙歎知何已。"]', '诗', 'shi', '', NULL, '登南嶽事畢謁司馬道士 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3344d843-6e7e-423f-9ae6-d6c96689d34c', '九月九日登龍山', '九月九日登龙山', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["郡庭常窘束，涼野求昭曠。","楚客凜秋時，桓公舊臺上。","清明風日好，歷落江山望。","極遠何蕭條，中留坐惆悵。","東彌夏首闊，西拒荆門壯。","夷險雖異時，古今豈殊狀。","先賢杳不接，故老猶可訪。","投弔傷昔人，揮斤感前匠。","自爲本疎散，未始忘幽尚。","際會非有欲，往來是无妄。","爲邦復多幸，去國殊遷放。","且汎籬下菊，還聆郢中唱。","灌園亦何爲，於陵乃逃相。"]', '["郡庭常窘束，涼野求昭曠。","楚客凜秋时，桓公旧台上。","清明风日好，歷落江山望。","極远何蕭條，中留坐惆悵。","东彌夏首闊，西拒荆门壯。","夷險雖異时，古今豈殊狀。","先賢杳不接，故老猶可訪。","投弔傷昔人，揮斤感前匠。","自爲本疎散，未始忘幽尚。","際會非有欲，往来是无妄。","爲邦复多幸，去国殊遷放。","且汎籬下菊，還聆郢中唱。","灌园亦何爲，於陵乃逃相。"]', '诗', 'shi', '', NULL, '九月九日登龍山 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d986c471-a075-481d-a7f2-952fa8e2c409', '登郡城南樓', '登郡城南楼', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["閉閣幸無事，登樓聊永日。","雲霞千里開，洲渚萬形出。","澹澹澄江漫，飛飛度鳥疾。","邑人半艫艦，津樹多楓橘。","感別時已屢，憑眺情非一。","遠懷不我同，孤興與誰悉。","平生本單緒，邂逅承優秩。","謬忝爲邦寄，多慙理人術。","駑鉛雖自勉，倉廩素非實。","陳力倘無効，謝病從芝朮。"]', '["閉閣幸無事，登楼聊永日。","云霞千里开，洲渚万形出。","澹澹澄江漫，飞飞度鸟疾。","邑人半艫艦，津樹多楓橘。","感別时已屢，憑眺情非一。","远懷不我同，孤兴與誰悉。","平生本單緒，邂逅承優秩。","謬忝爲邦寄，多慙理人術。","駑鉛雖自勉，倉廩素非實。","陳力倘無効，謝病從芝朮。"]', '诗', 'shi', '', NULL, '登郡城南樓 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d6c2871-a934-4de6-bd8c-bd1e892ec141', '歲初巡屬縣登高安南樓言懷', '歲初巡屬縣登高安南楼言懷', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["山城本孤峻，憑高結層軒。","江氣偏宜早，林英粲已繁。","餘滋含宿霽，衆妍在朝暾。","拂衣釋簿領，伏檻遺紛喧。","深俯東溪澳，遠延南山樊。","歸雲納前嶺，去鳥投遙村。","目盡有餘意，心惻不可諼。","朅來彭蠡澤，載經敷淺原。","春及但生思，時哉無與言。","不才叨過舉，唯力酬明恩。","美化猶寂蔑，迅節徒飛奔。","雖無成立効，庶以去思論。","行復徇孤迹，亦云吾道存。"]', '["山城本孤峻，憑高結層軒。","江氣偏宜早，林英粲已繁。","餘滋含宿霽，衆妍在朝暾。","拂衣釋簿領，伏檻遺紛喧。","深俯东溪澳，远延南山樊。","归云納前嶺，去鸟投遙村。","目尽有餘意，心惻不可諼。","朅来彭蠡澤，載經敷淺原。","春及但生思，时哉無與言。","不才叨過舉，唯力酬明恩。","美化猶寂蔑，迅節徒飞奔。","雖無成立効，庶以去思論。","行复徇孤迹，亦云吾道存。"]', '诗', 'shi', '', NULL, '歲初巡屬縣登高安南樓言懷 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0f7f1e4-7cbb-43d4-9517-b795ca94fff8', '秋晚登樓望南江入始興郡路', '秋晚登楼望南江入始兴郡路', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["潦收沙衍出，霜降天宇晶。","伏檻一長眺，津途多遠情。","思來江山外，望盡煙雲生。","滔滔不自辨，役役且何成。","我來颯衰鬢，孰云飄華纓。","櫪馬苦踡跼，籠禽念遐征。","歲陰向晼晚，日夕空屏營。","物生貴得性，身累由近名。","內顧覺今是，追歎何時平。"]', '["潦收沙衍出，霜降天宇晶。","伏檻一长眺，津途多远情。","思来江山外，望尽煙云生。","滔滔不自辨，役役且何成。","我来颯衰鬢，孰云飄华纓。","櫪马苦踡跼，籠禽念遐征。","歲陰向晼晚，日夕空屏營。","物生貴得性，身累由近名。","內顧覺今是，追歎何时平。"]', '诗', 'shi', '', NULL, '秋晚登樓望南江入始興郡路 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0cd2108-f068-4b92-ada5-5bfb7c5a7782', '登古陽雲臺', '登古陽云台', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["庭樹日衰颯，風霜未云已。","駕言遣憂思，乘興求相似。","楚國茲故都，蘭臺有餘址。","傳聞襄王世，仍立巫山祀。","方此全盛時，豈無嬋娟子。","色荒神女至，魂蕩宮觀啓。","蔓草今如積，朝雲爲誰起。"]', '["庭樹日衰颯，风霜未云已。","駕言遣憂思，乘兴求相似。","楚国茲故都，蘭台有餘址。","傳闻襄王世，仍立巫山祀。","方此全盛时，豈無嬋娟子。","色荒神女至，魂蕩宮观啓。","蔓草今如積，朝云爲誰起。"]', '诗', 'shi', '', NULL, '登古陽雲臺 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fefc21d-970a-40ba-aee7-6b831130b2af', '與生公尋幽居處', '與生公尋幽居处', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["同方久厭俗，相與事遐討。","及此雲山去，窅然巖徑好。","疑入武陵源，如逢漢陰老。","清諧欣有得，幽閑歘盈抱。","我本玉階侍，偶訪金仙道。","茲焉求卜築，所過皆神造。","歲晚林始敷，日晏崖方杲。","不種緣嶺竹，豈植臨潭草。","即途可淹留，隨日成黼藻。","期爲靜者說，曾是終焉保。","今爲簡書畏，秖令歸思浩。"]', '["同方久厭俗，相與事遐討。","及此云山去，窅然巖徑好。","疑入武陵源，如逢漢陰老。","清諧欣有得，幽闲歘盈抱。","我本玉階侍，偶訪金仙道。","茲焉求卜築，所過皆神造。","歲晚林始敷，日晏崖方杲。","不種緣嶺竹，豈植臨潭草。","即途可淹留，隨日成黼藻。","期爲静者说，曾是終焉保。","今爲簡书畏，秖令归思浩。"]', '诗', 'shi', '', NULL, '與生公尋幽居處 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72f55764-164d-48cc-a2a2-165be4a3c681', '與生公遊石窟山', '與生公游石窟山', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["探秘孰云遠，忘懷復爾同。","日尋高深意，宛是神仙中。","躋險搆靈室，詭制非人功。","潛洞黝無底，殊庭忽似夢。","豈如武安鑿，自若茅山通。","造物良有寄，嬉遊迺愜衷。","猶希咽玉液，從此昇雲空。","咄咄共攜手，泠然且馭風。"]', '["探秘孰云远，忘懷复爾同。","日尋高深意，宛是神仙中。","躋險搆靈室，詭制非人功。","潛洞黝無底，殊庭忽似梦。","豈如武安鑿，自若茅山通。","造物良有寄，嬉游迺愜衷。","猶希咽玉液，從此昇云空。","咄咄共携手，泠然且馭风。"]', '诗', 'shi', '', NULL, '與生公遊石窟山 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a71a229-d884-46dd-bf6a-089e69ee9278', '郡舍南有園畦雜樹聊以永日', '郡舍南有园畦杂樹聊以永日', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["爲郡久無補，越鄉空復深。","苟能秉素節，安用叨華簪。","却步園畦裏，追吾野逸心。","形骸拘俗吏，光景賴閑林。","內訟誠知止，外言猶匪忱。","成蹊謝李徑，衞足感葵陰。","榮達豈不偉，孤生非所任。","江城何寂歷，秋樹亦蕭森。","下有北流水，上有南飛禽。","我願從歸翼，無然坐自沈。"]', '["爲郡久無補，越乡空复深。","苟能秉素節，安用叨华簪。","却步园畦裏，追吾野逸心。","形骸拘俗吏，光景賴闲林。","內訟誠知止，外言猶匪忱。","成蹊謝李徑，衞足感葵陰。","榮達豈不偉，孤生非所任。","江城何寂歷，秋樹亦蕭森。","下有北流水，上有南飞禽。","我願從归翼，無然坐自沈。"]', '诗', 'shi', '', NULL, '郡舍南有園畦雜樹聊以永日 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0249981e-ab46-4b02-822d-97779f1c1b59', '臨泛東湖', '臨泛东湖', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["郡庭日休暇，湖曲邀勝踐。","樂職在中和，靈心挹上善。","乘流坐清曠，舉目眺悠緬。","林與西山重，雲因北風卷。","晶明畫不逮，陰影鏡無辨。","晚秀復芬敷，秋光更遙衍。","萬族紛可佳，一遊豈能展。","羇孤忝邦牧，顧己非時選。","梁公世不容，長孺心亦褊。","永念出籠縶，常思退疲蹇。","歲徂風露嚴，日恐蘭苕剪。","佳辰不可得，良會何其鮮。","罷興還江城，閉關聊自遣。"]', '["郡庭日休暇，湖曲邀勝踐。","乐職在中和，靈心挹上善。","乘流坐清曠，舉目眺悠緬。","林與西山重，云因北风卷。","晶明畫不逮，陰影镜無辨。","晚秀复芬敷，秋光更遙衍。","万族紛可佳，一游豈能展。","羇孤忝邦牧，顧己非时選。","梁公世不容，长孺心亦褊。","永念出籠縶，常思退疲蹇。","歲徂风露嚴，日恐蘭苕剪。","佳辰不可得，良會何其鲜。","罷兴還江城，閉关聊自遣。"]', '诗', 'shi', '', NULL, '臨泛東湖 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f06c180b-3753-4b25-b5e4-6a809ed32b69', '始興南山下有林泉嘗卜居焉荆州臥病有懷此地', '始兴南山下有林泉嘗卜居焉荆州臥病有懷此地', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["出處各有在，何者爲陸沈。","幸無迫賤事，聊可祛迷襟。","世路少夷坦，孟門未嶇嶔。","多慙入火術，常惕履冰心。","一跌不自保，萬全焉可尋。","行行念歸路，眇眇惜光陰。","浮生如過隙，先達已吾箴。","敢忘丘山施，亦云年病侵。","力衰在所養，時謝良不任。","但憶舊棲息，願言遂窺臨。","雲間日孤秀，山下面清深。","蘿蔦自爲幄，風泉何必琴。","歸此老吾老，還當日千金。"]', '["出处各有在，何者爲陸沈。","幸無迫賤事，聊可祛迷襟。","世路少夷坦，孟门未嶇嶔。","多慙入火術，常惕履冰心。","一跌不自保，万全焉可尋。","行行念归路，眇眇惜光陰。","浮生如過隙，先達已吾箴。","敢忘丘山施，亦云年病侵。","力衰在所養，时謝良不任。","但憶旧棲息，願言遂窺臨。","云间日孤秀，山下面清深。","蘿蔦自爲幄，风泉何必琴。","归此老吾老，還當日千金。"]', '诗', 'shi', '', NULL, '始興南山下有林泉嘗卜居焉荆州臥病有懷此地 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8e942b0-0407-45cc-92d9-1d6b27d868b8', '晨坐齋中偶而成詠', '晨坐斋中偶而成詠', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["寒露潔秋空，遙山紛在矚。","孤頂乍修聳，微雲復相續。","人茲賞地偏，鳥亦愛林旭。","結念憑幽遠，撫躬曷羈束。","仰霄謝逸翰，臨路嗟疲足。","徂歲方暌攜，歸心亟躑躅。","休閑倘有素，豈負南山曲。"]', '["寒露潔秋空，遙山紛在矚。","孤頂乍修聳，微云复相續。","人茲賞地偏，鸟亦愛林旭。","結念憑幽远，撫躬曷羈束。","仰霄謝逸翰，臨路嗟疲足。","徂歲方暌携，归心亟躑躅。","休闲倘有素，豈負南山曲。"]', '诗', 'shi', '', NULL, '晨坐齋中偶而成詠 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0aa91a05-c4ce-4593-8537-d89bda495082', '詠史', '詠史', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["大德始無頗，中智是所是。","居然已不一，況乃務相詭。","小道致泥難，巧言因萋毀。","穰侯或見遲，蘇生得陰揣。","輕既長沙傅，重亦邊郡徙。","勢傾不幸然，跡在胡寧爾。","滄溟所爲大，江漢日來委。","灃水雖復清，魚鼈豈游此。","賢哉有小白，讎中有管氏。","若人不世生，悠悠多如彼。"]', '["大德始無頗，中智是所是。","居然已不一，況乃務相詭。","小道致泥难，巧言因萋毀。","穰侯或见遲，蘇生得陰揣。","轻既长沙傅，重亦邊郡徙。","勢傾不幸然，跡在胡寧爾。","滄溟所爲大，江漢日来委。","灃水雖复清，鱼鼈豈游此。","賢哉有小白，讎中有管氏。","若人不世生，悠悠多如彼。"]', '诗', 'shi', '', NULL, '詠史 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fe6b67d-539d-43e6-a172-19abd72c9434', '龍門旬宴得月字韻', '龙门旬宴得月字韻', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["恩華逐芳歲，形勝兼韶月。","中席傍魚潭，前山倚龍闕。","花迎妙妓至，鳥避仙舟發。","宴賞良在茲，再來情不歇。"]', '["恩华逐芳歲，形勝兼韶月。","中席傍鱼潭，前山倚龙闕。","花迎妙妓至，鸟避仙舟發。","宴賞良在茲，再来情不歇。"]', '诗', 'shi', '', NULL, '龍門旬宴得月字韻 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b6a0985-bf67-4083-8371-f0c415d20313', '驪山下逍遙公舊居游集', '驪山下逍遙公旧居游集', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["君子體清尚，歸處有兼資。","雖然經濟日，無忘幽棲時。","卜居舊何所，休澣嘗來茲。","岑寂罕人至，幽深獲我思。","松澗聆遺風，蘭林覽餘滋。","往事誠已矣，道存猶可追。","遺子後黃金，作歌先紫芝。","明德有自來，奕世皆秉彝。","豈與磻溪老，崛起周太師。","我心希碩人，逮此問元龜。","怊悵既懷遠，沈吟亦省私。","已云寵祿過，況在華髮衰。","軒蓋有迷復，丘壑無磷緇。","感物重所懷，何但止足斯。"]', '["君子體清尚，归处有兼資。","雖然經濟日，無忘幽棲时。","卜居旧何所，休澣嘗来茲。","岑寂罕人至，幽深獲我思。","松澗聆遺风，蘭林覽餘滋。","往事誠已矣，道存猶可追。","遺子後黄金，作歌先紫芝。","明德有自来，奕世皆秉彝。","豈與磻溪老，崛起周太師。","我心希碩人，逮此问元龟。","怊悵既懷远，沈吟亦省私。","已云寵祿過，況在华髮衰。","軒蓋有迷复，丘壑無磷緇。","感物重所懷，何但止足斯。"]', '诗', 'shi', '', NULL, '驪山下逍遙公舊居游集 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f30083f-23c2-4787-b60c-cfbb7567bf17', '雜詩五首 一', '杂诗五首 一', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["孤桐亦胡爲，百尺傍無枝。","疎陰不自覆，修幹欲何施。","高岡地復迥，弱植風屢吹。","凡鳥已相噪，鳳皇安得知。"]', '["孤桐亦胡爲，百尺傍無枝。","疎陰不自覆，修幹欲何施。","高岡地复迥，弱植风屢吹。","凡鸟已相噪，鳳皇安得知。"]', '诗', 'shi', '', NULL, '雜詩五首 一 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('262d50a6-0dec-4cc8-af7d-5a65c39aa684', '雜詩五首 二', '杂诗五首 二', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["蘿蔦必有託，風霜不能落。","酷在蘭將蕙，甘從葵與藿。","運命雖爲宰，寒暑自回薄。","悠悠天地間，委順無不樂。"]', '["蘿蔦必有託，风霜不能落。","酷在蘭將蕙，甘從葵與藿。","運命雖爲宰，寒暑自回薄。","悠悠天地间，委順無不乐。"]', '诗', 'shi', '', NULL, '雜詩五首 二 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('712be3c6-45f2-4948-b956-4c38335e5564', '雜詩五首 三', '杂诗五首 三', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["良辰不可遇，心賞更蹉跎。","終日塊然坐，有時勞者歌。","庭前攬芳蕙，江上託微波。","路遠無能達，憂情空復多。"]', '["良辰不可遇，心賞更蹉跎。","終日塊然坐，有时勞者歌。","庭前攬芳蕙，江上託微波。","路远無能達，憂情空复多。"]', '诗', 'shi', '', NULL, '雜詩五首 三 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d00cec61-36f7-4af9-a4e3-4e731624cd7b', '雜詩五首 四', '杂诗五首 四', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["湘水弔靈妃，斑竹爲情緒。","漢水訪遊女，解佩欲誰與。","同心不可見，異路空延佇。","浦上青楓林，津傍白沙渚。","行吟至落日，坐望秖愁予。","神物亦豈孤，佳期竟何許。"]', '["湘水弔靈妃，斑竹爲情緒。","漢水訪游女，解佩欲誰與。","同心不可见，異路空延佇。","浦上青楓林，津傍白沙渚。","行吟至落日，坐望秖愁予。","神物亦豈孤，佳期竟何許。"]', '诗', 'shi', '', NULL, '雜詩五首 四 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1398ae96-a9ff-43a3-90b6-62c92bc1fdb9', '雜詩五首 五', '杂诗五首 五', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["木直幾自寇，石堅亦他攻。","何言爲用薄，而與火膏同。","物類有固然，誰能取徑通。","纖纖良田草，靡靡唯從風。","日夜沐甘澤，春秋等芳叢。","生性苟不夭，香臭誰爲中。","道家貴至柔，儒生何固窮。","終始行一意，無乃過愚公。"]', '["木直幾自寇，石堅亦他攻。","何言爲用薄，而與火膏同。","物類有固然，誰能取徑通。","纖纖良田草，靡靡唯從风。","日夜沐甘澤，春秋等芳叢。","生性苟不夭，香臭誰爲中。","道家貴至柔，儒生何固窮。","終始行一意，無乃過愚公。"]', '诗', 'shi', '', NULL, '雜詩五首 五 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b4f2d56-6df4-4999-a82c-11283529dd51', '感遇十二首 一', '感遇十二首 一', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["蘭葉春葳蕤，桂華秋皎潔。","欣欣此生意，自爾爲佳節。","誰知林棲者，聞風坐相悅。","草木有本心，何求美人折。"]', '["蘭葉春葳蕤，桂华秋皎潔。","欣欣此生意，自爾爲佳節。","誰知林棲者，闻风坐相悅。","草木有本心，何求美人折。"]', '诗', 'shi', '', NULL, '感遇十二首 一 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6df38a77-6e5d-43ae-a115-7de36475f53e', '感遇十二首 二', '感遇十二首 二', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["幽林歸獨臥，滯慮洗孤清。","持此謝高鳥，因之傳遠情。","日夕懷空意，人誰感至精。","飛沈理自隔，何所慰吾誠。"]', '["幽林归独臥，滯慮洗孤清。","持此謝高鸟，因之傳远情。","日夕懷空意，人誰感至精。","飞沈理自隔，何所慰吾誠。"]', '诗', 'shi', '', NULL, '感遇十二首 二 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d89b9e8-8deb-4969-ac17-4ea6ce0d299a', '感遇十二首 三', '感遇十二首 三', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["魚游樂深池，鳥棲欲高枝。","嗟爾蜉蝣羽，薨薨亦何爲。","有生豈不化，所感奚若斯。","神理日微滅，吾心安得知。","浩歎楊朱子，徒然泣路岐。"]', '["鱼游乐深池，鸟棲欲高枝。","嗟爾蜉蝣羽，薨薨亦何爲。","有生豈不化，所感奚若斯。","神理日微滅，吾心安得知。","浩歎楊朱子，徒然泣路岐。"]', '诗', 'shi', '', NULL, '感遇十二首 三 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9798830-48c1-45e3-be90-4028d93954dc', '感遇十二首 四', '感遇十二首 四', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["孤鴻海上來，池潢不敢顧。","側見雙翠鳥，巢在三珠樹。","矯矯珍木巔，得無金丸懼。","美服患人指，高明逼神惡。","今我遊冥冥，弋者何所慕。"]', '["孤鴻海上来，池潢不敢顧。","側见雙翠鸟，巢在三珠樹。","矯矯珍木巔，得無金丸懼。","美服患人指，高明逼神惡。","今我游冥冥，弋者何所慕。"]', '诗', 'shi', '', NULL, '感遇十二首 四 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3aa30ff-3a42-47ef-a176-c25d8536a261', '感遇十二首 五', '感遇十二首 五', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["吳越數千里，夢寐今夕見。","形骸非我親，衾枕即鄉縣。","化蝶猶不識，川魚安可羨。","海上有仙山，歸期覺神變。"]', '["吳越數千里，梦寐今夕见。","形骸非我親，衾枕即乡縣。","化蝶猶不識，川鱼安可羨。","海上有仙山，归期覺神变。"]', '诗', 'shi', '', NULL, '感遇十二首 五 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81a1887d-9a38-4135-ae3a-6e5f26698e4d', '感遇十二首 六', '感遇十二首 六', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["西日下山隱，北風乘夕流。","燕雀感昏旦，簷楹呼匹儔。","鴻鵠雖自遠，哀音非所求。","貴人棄疵賤，下士嘗殷憂。","衆情累外物，恕己忘內修。","感歎長如此，使我心悠悠。"]', '["西日下山隐，北风乘夕流。","燕雀感昏旦，簷楹呼匹儔。","鴻鵠雖自远，哀音非所求。","貴人棄疵賤，下士嘗殷憂。","衆情累外物，恕己忘內修。","感歎长如此，使我心悠悠。"]', '诗', 'shi', '', NULL, '感遇十二首 六 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11b013f9-aa6a-4e55-8e68-195dc62f161f', '感遇十二首 七', '感遇十二首 七', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["江南有丹橘，經冬猶綠林。","豈伊地氣暖，自有歲寒心。","可以薦嘉客，奈何阻重深。","運命唯所遇，循環不可尋。","徒言樹桃李，此木豈無陰。"]', '["江南有丹橘，經冬猶綠林。","豈伊地氣暖，自有歲寒心。","可以薦嘉客，奈何阻重深。","運命唯所遇，循环不可尋。","徒言樹桃李，此木豈無陰。"]', '诗', 'shi', '', NULL, '感遇十二首 七 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('152e5db5-1760-4f47-aa39-494f47c256ef', '感遇十二首 八', '感遇十二首 八', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["永日徒離憂，臨風懷蹇修。","美人何處所？孤客空悠悠。","青鳥跂不至，朱鱉誰云浮。","夜分起躑躅，時逝曷淹留。"]', '["永日徒離憂，臨风懷蹇修。","美人何处所？孤客空悠悠。","青鸟跂不至，朱鱉誰云浮。","夜分起躑躅，时逝曷淹留。"]', '诗', 'shi', '', NULL, '感遇十二首 八 張九齡 shi');
